function getKingstonsSellerPackDisplayCopy(documentRow = {}) {
  return KINGSTONS_SELLER_PACK_DISPLAY_COPY[normalizeKey(documentRow?.key)] || {
    title: normalizeText(documentRow?.label),
    description: normalizeText(documentRow?.description),
  }
}

function splitKingstonsSellerPackList(value = '') {
  return String(value ?? '')
    .split(/\r?\n|,/)
    .map((item) => normalizeText(item))
    .filter(Boolean)
}

function joinKingstonsSellerPackList(value = []) {
  return asArray(value)
    .map((item) => normalizeText(item?.name || item))
    .filter(Boolean)
    .join('\n')
}

function buildKingstonsSellerPackPersonRecords(value = '', prefix = 'person') {
  return splitKingstonsSellerPackList(value).map((name, index) => ({
    id: `${normalizeKey(prefix) || 'person'}-${index + 1}`,
    name,
  }))
}

function normalizeKingstonsFicaPersonRecord(value = {}, fallback = {}) {
  const record = typeof value === 'string' ? { name: value } : asRecord(value)
  const fallbackRecord = asRecord(fallback)
  const name = firstWorkspaceText(
    record.name,
    record.fullName,
    record.full_name,
    record.displayName,
    fallbackRecord.name,
    fallbackRecord.fullName,
  )
  return {
    ...record,
    id: normalizeKey(record.id || record.key || name || fallbackRecord.id || fallbackRecord.key),
    name,
    idNumber: firstWorkspaceText(record.idNumber, record.id_number, record.identityNumber, record.identity_number),
    email: firstWorkspaceText(record.email, record.emailAddress, record.email_address).toLowerCase(),
    phone: firstWorkspaceText(record.phone, record.mobile, record.mobileNumber, record.mobile_number),
  }
}

function getLeadPrimaryPersonName(lead = {}, contact = {}) {
  return firstWorkspaceText(
    [contact?.firstName, contact?.lastName].map(normalizeText).filter(Boolean).join(' '),
    contact?.name,
    contact?.fullName,
    lead?.sellerName,
    lead?.buyerName,
    lead?.name,
    lead?.fullName,
    [lead?.firstName, lead?.lastName].map(normalizeText).filter(Boolean).join(' '),
  )
}

function buildKingstonsSellerFicaRoleplayers(lead = {}, contact = {}) {
  const pack = getKingstonsSellerPackState(lead)
  const legalPath = asRecord(pack.legalPath || pack.legal_path || pack.sellerProfile || pack.seller_profile)
  const naturalPath = asRecord(legalPath.natural || legalPath.person)
  const juristicPath = asRecord(legalPath.juristic || legalPath.entity)
  const sellerType = normalizeKey(pack.sellerType || pack.ficaSellerType || legalPath.sellerType || legalPath.seller_type)
  const roleplayers = []
  const addRoleplayer = (person = {}, role = 'owner', index = 0, labelPrefix = 'Seller') => {
    const normalized = normalizeKingstonsFicaPersonRecord(person, { id: `${role}-${index + 1}` })
    const roleKey = normalizeKey(role) || 'roleplayer'
    const sequence = index + 1
    const id = normalizeKey(normalized.id || `${roleKey}-${sequence}`)
    roleplayers.push({
      ...normalized,
      id,
      role: roleKey,
      roleLabel: labelPrefix,
      tabLabel: `${labelPrefix} ${sequence}`,
      displayName: normalized.name || `${labelPrefix} ${sequence}`,
    })
  }

  if (sellerType === 'juristic') {
    const entityType = normalizeKey(pack.juristicEntityType || pack.entityType || legalPath.juristicEntityType || juristicPath.entityType)
    const companyDirectors = asArray(pack.companyDirectors || pack.company_directors || legalPath.company?.directors || juristicPath.company?.directors)
    const trustees = asArray(pack.trustees || pack.trustees_list || legalPath.trust?.trustees || juristicPath.trust?.trustees)
    const members = asArray(pack.closeCorporationMembers || pack.close_corporation_members || legalPath.closeCorporation?.members || juristicPath.closeCorporation?.members)
    const people = entityType === 'trust'
      ? trustees
      : entityType === 'close_corporation'
        ? members
        : companyDirectors
    const role = entityType === 'trust' ? 'trustee' : entityType === 'close_corporation' ? 'member' : 'director'
    const label = entityType === 'trust' ? 'Trustee' : entityType === 'close_corporation' ? 'Member' : 'Director'
    ;(people.length ? people : [{ name: `${label} 1` }]).forEach((person, index) => addRoleplayer(person, role, index, label))
    return roleplayers
  }

  const owners = asArray(pack.owners || legalPath.owners || naturalPath.owners)
  const primaryName = getLeadPrimaryPersonName(lead, contact)
  ;(owners.length ? owners : [{ name: primaryName || 'Seller 1' }]).forEach((person, index) => addRoleplayer(person, 'owner', index, 'Seller'))

  const maritalSetup = normalizeKey(pack.maritalSetup || pack.maritalRegime || legalPath.naturalSetup || naturalPath.maritalSetup || naturalPath.maritalRegime)
  const spouse = normalizeKingstonsFicaPersonRecord(
    legalPath.spouse || naturalPath.spouse || {
      name: pack.spouseName,
      idNumber: pack.spouseIdNumber,
      email: pack.spouseEmail,
      phone: pack.spousePhone,
    },
    { id: 'spouse-1' },
  )
  if ((maritalSetup === 'in_community' || spouse.name) && spouse.name) {
    roleplayers.push({
      ...spouse,
      id: normalizeKey(spouse.id || 'spouse-1'),
      role: 'spouse',
      roleLabel: 'Spouse',
      tabLabel: 'Spouse',
      displayName: spouse.name || 'Spouse',
    })
  }

  return roleplayers
}

function buildKingstonsSellerFicaRoleplayerDocumentRows(lead = {}, contact = {}) {
  const pack = getKingstonsSellerPackState(lead)
  const roleplayers = buildKingstonsSellerFicaRoleplayers(lead, contact)
  return roleplayers.flatMap((roleplayer) =>
    KINGSTONS_SELLER_FICA_ROLEPLAYER_DOCUMENTS.map((definition, index) => {
      const key = normalizeKey(`seller_fica_${roleplayer.id}_${definition.key}`)
      const uploaded = asRecord(pack.documents?.[key])
      const uploadedAt = firstWorkspaceText(uploaded.uploadedAt, uploaded.uploaded_at)
      const uploadedFileName = firstWorkspaceText(uploaded.uploadedFileName, uploaded.uploaded_file_name, uploaded.fileName, uploaded.file_name)
      const storagePath = firstWorkspaceText(uploaded.storagePath, uploaded.storage_path)
      const storageBucket = firstWorkspaceText(uploaded.storageBucket, uploaded.storage_bucket)
      const url = firstWorkspaceText(uploaded.url, uploaded.fileUrl, uploaded.file_url, uploaded.downloadUrl, uploaded.download_url)
      const hasUpload = sellerLeadDocumentHasFileEvidence({ ...uploaded, uploadedAt, storagePath, url })
      return {
        ...definition,
        ...uploaded,
        id: key,
        key,
        requirementKey: key,
        requirement_key: key,
        documentType: key,
        document_type: key,
        title: `${definition.label}: ${roleplayer.displayName}`,
        label: `${definition.label}: ${roleplayer.displayName}`,
        required: true,
        source: KINGSTONS_FICA_ROLEPLAYER_SOURCE,
        category: 'seller',
        document_category: 'seller',
        group: 'seller_fica',
        requirement_group: 'seller_fica',
        requirementLane: 'ownership_driven',
        requirement_lane: 'ownership_driven',
        documentRequirementSection: 'seller_identity_fica',
        document_requirement_section: 'seller_identity_fica',
        partyRole: roleplayer.role,
        party_role: roleplayer.role,
        partyName: roleplayer.displayName,
        party_name: roleplayer.displayName,
        partyIdNumber: roleplayer.idNumber,
        party_id_number: roleplayer.idNumber,
        partyEmail: roleplayer.email,
        party_email: roleplayer.email,
        ficaRoleplayerId: roleplayer.id,
        fica_roleplayer_id: roleplayer.id,
        ficaRoleplayerLabel: roleplayer.displayName,
        fica_roleplayer_label: roleplayer.displayName,
        ficaRoleplayerTabLabel: roleplayer.tabLabel,
        fica_roleplayer_tab_label: roleplayer.tabLabel,
        ficaDocumentOrder: index,
        fica_document_order: index,
        status: hasUpload ? 'uploaded' : 'required',
        statusLabel: hasUpload ? 'Uploaded' : 'Required',
        uploadedAt,
        uploaded_at: uploadedAt,
        uploadedFileName,
        uploaded_file_name: uploadedFileName,
        storagePath,
        storage_path: storagePath,
        storageBucket,
        storage_bucket: storageBucket,
        url,
        fileUrl: url,
        file_url: url,
        downloadUrl: url,
        download_url: url,
      }
    }),
  )
}

function buildKingstonsSellerPackProfileDraft(pack = {}) {
  const sellerPath = asRecord(pack.legalPath || pack.legal_path || pack.sellerProfile || pack.seller_profile)
  const naturalPath = asRecord(sellerPath.natural || sellerPath.person || {})
  const juristicPath = asRecord(sellerPath.juristic || sellerPath.entity || {})
  const companyPath = asRecord(juristicPath.company || {})
  const trustPath = asRecord(juristicPath.trust || {})
  const closeCorporationPath = asRecord(juristicPath.closeCorporation || juristicPath.close_corporation || {})
  const sellerType = normalizeKey(pack.sellerType || pack.ficaSellerType || sellerPath.sellerType || sellerPath.seller_type)
  return {
    sellerType,
    naturalSetup: normalizeKey(firstWorkspaceText(
      sellerPath.naturalSetup,
      sellerPath.maritalRegime,
      pack.maritalRegime,
      naturalPath.maritalSetup,
      naturalPath.maritalRegime,
    )),
    ownersText: joinKingstonsSellerPackList(
      sellerPath.owners ||
        pack.owners ||
        naturalPath.owners ||
        [],
    ),
    spouseName: firstWorkspaceText(
      sellerPath.spouse?.name,
      pack.spouseName,
      pack.spouse_full_name,
      naturalPath.spouse?.name,
    ),
    spouseIdNumber: firstWorkspaceText(
      sellerPath.spouse?.idNumber,
      sellerPath.spouse?.id_number,
      pack.spouseIdNumber,
      pack.spouse_id_number,
      naturalPath.spouse?.id_number,
    ),
    spouseEmail: firstWorkspaceText(
      sellerPath.spouse?.email,
      pack.spouseEmail,
      pack.spouse_email,
      naturalPath.spouse?.email,
    ),
    spousePhone: firstWorkspaceText(
      sellerPath.spouse?.phone,
      pack.spousePhone,
      pack.spouse_phone,
      naturalPath.spouse?.phone,
    ),
    juristicEntityType: normalizeKey(firstWorkspaceText(
      sellerPath.juristicEntityType,
      juristicPath.entityType,
      pack.juristicEntityType,
      pack.entityType,
    )),
    companyName: firstWorkspaceText(
      sellerPath.company?.name,
      pack.companyName,
      pack.company_name,
      companyPath.name,
    ),
    companyRegistrationNumber: firstWorkspaceText(
      sellerPath.company?.registrationNumber,
      sellerPath.company?.registration_number,
      pack.companyRegistrationNumber,
      pack.companyRegistrationNumber,
      companyPath.registrationNumber,
      companyPath.registration_number,
    ),
    companyDirectorsText: joinKingstonsSellerPackList(
      sellerPath.company?.directors ||
        pack.companyDirectors ||
        pack.company_directors ||
        companyPath.directors ||
        [],
    ),
    trustName: firstWorkspaceText(
      sellerPath.trust?.name,
      pack.trustName,
      pack.trust_name,
      trustPath.name,
    ),
    trustRegistrationNumber: firstWorkspaceText(
      sellerPath.trust?.registrationNumber,
      sellerPath.trust?.registration_number,
      pack.trustRegistrationNumber,
      pack.trust_registration_number,
      trustPath.registrationNumber,
      trustPath.registration_number,
    ),
    trustTrusteesText: joinKingstonsSellerPackList(
      sellerPath.trust?.trustees ||
        pack.trustees ||
        pack.trustees_list ||
        trustPath.trustees ||
        [],
    ),
    closeCorporationName: firstWorkspaceText(
      sellerPath.closeCorporation?.name,
      pack.closeCorporationName,
      pack.close_corporation_name,
      closeCorporationPath.name,
      normalizeKey(pack.juristicEntityType || sellerPath.juristicEntityType || juristicPath.entityType) === 'close_corporation' ? pack.companyName : '',
    ),
    closeCorporationRegistrationNumber: firstWorkspaceText(
      sellerPath.closeCorporation?.registrationNumber,
      sellerPath.closeCorporation?.registration_number,
      pack.closeCorporationRegistrationNumber,
      pack.close_corporation_registration_number,
      closeCorporationPath.registrationNumber,
      closeCorporationPath.registration_number,
      normalizeKey(pack.juristicEntityType || sellerPath.juristicEntityType || juristicPath.entityType) === 'close_corporation' ? pack.companyRegistrationNumber : '',
    ),
    closeCorporationMembersText: joinKingstonsSellerPackList(
      sellerPath.closeCorporation?.members ||
        pack.closeCorporationMembers ||
        pack.close_corporation_members ||
        closeCorporationPath.members ||
        [],
    ),
  }
}

function buildKingstonsSellerPackProfilePayload(draft = {}) {
  const sellerType = normalizeKey(draft.sellerType)
  const naturalSetup = normalizeKey(draft.naturalSetup)
  const owners = buildKingstonsSellerPackPersonRecords(draft.ownersText, 'owner')
  const companyDirectors = buildKingstonsSellerPackPersonRecords(draft.companyDirectorsText, 'director')
  const trustTrustees = buildKingstonsSellerPackPersonRecords(draft.trustTrusteesText, 'trustee')
  const closeCorporationMembers = buildKingstonsSellerPackPersonRecords(draft.closeCorporationMembersText, 'member')
  const juristicEntityType = normalizeKey(draft.juristicEntityType)
  const profile = {
    ownershipModelVersion: 'kingstons_seller_ownership_capture_phase3_v1',
    sellerType,
    legalPathType: sellerType,
    owners,
    natural: {
      maritalSetup: naturalSetup,
      maritalRegime: naturalSetup,
      owners,
      spouse: {
        name: normalizeText(draft.spouseName),
        idNumber: normalizeText(draft.spouseIdNumber),
        email: normalizeText(draft.spouseEmail).toLowerCase(),
        phone: normalizeText(draft.spousePhone),
      },
    },
    juristic: {
      entityType: juristicEntityType,
      company: {
        name: normalizeText(draft.companyName),
        registrationNumber: normalizeText(draft.companyRegistrationNumber),
        directors: companyDirectors,
      },
      trust: {
        name: normalizeText(draft.trustName),
        registrationNumber: normalizeText(draft.trustRegistrationNumber),
        trustees: trustTrustees,
      },
      closeCorporation: {
        name: normalizeText(draft.closeCorporationName || draft.companyName),
        registrationNumber: normalizeText(draft.closeCorporationRegistrationNumber || draft.companyRegistrationNumber),
        members: closeCorporationMembers,
      },
    },
  }

  return {
    ...profile,
    ...(sellerType === 'natural'
      ? {
          maritalSetup: naturalSetup,
          maritalRegime: naturalSetup,
          spouseName: profile.natural.spouse.name,
          spouseIdNumber: profile.natural.spouse.idNumber,
          spouseEmail: profile.natural.spouse.email,
          spousePhone: profile.natural.spouse.phone,
          owners,
        }
      : {}),
    ...(sellerType === 'juristic'
      ? {
          juristicEntityType,
          companyName: juristicEntityType === 'close_corporation' ? profile.juristic.closeCorporation.name : profile.juristic.company.name,
          companyRegistrationNumber: juristicEntityType === 'close_corporation' ? profile.juristic.closeCorporation.registrationNumber : profile.juristic.company.registrationNumber,
          companyDirectors,
          trustName: profile.juristic.trust.name,
          trustRegistrationNumber: profile.juristic.trust.registrationNumber,
          trustees: trustTrustees,
          closeCorporationName: profile.juristic.closeCorporation.name,
          closeCorporationRegistrationNumber: profile.juristic.closeCorporation.registrationNumber,
          closeCorporationMembers,
        }
      : {}),
  }
}

function getKingstonsSellerPackCaptureSummaryLabel(pack = {}) {
  const sellerType = normalizeKey(pack.sellerType || pack.ficaSellerType)
  if (sellerType === 'natural') {
    const setup = normalizeKey(pack.maritalRegime || pack.maritalSetup || pack.legalPath?.natural?.maritalSetup)
    const ownerCount = asArray(pack.owners || pack.legalPath?.owners || pack.legalPath?.natural?.owners).length
    const ownerSuffix = ownerCount > 1 ? ` · ${ownerCount} owners captured` : ''
    if (setup === 'in_community') return `Natural person · Married in community of property${ownerSuffix}`
    if (setup === 'anc') return `Natural person · Married out of community (ANC)${ownerSuffix}`
    return 'Natural person'
  }
  if (sellerType === 'juristic') {
    const entityType = normalizeKey(pack.juristicEntityType || pack.entityType || pack.legalPath?.juristic?.entityType)
    const directorCount = asArray(pack.companyDirectors || pack.legalPath?.juristic?.company?.directors).length
    const trusteeCount = asArray(pack.trustees || pack.legalPath?.juristic?.trust?.trustees).length
    const memberCount = asArray(pack.closeCorporationMembers || pack.legalPath?.juristic?.closeCorporation?.members).length
    if (entityType === 'company') return directorCount ? `Company · ${directorCount} director${directorCount === 1 ? '' : 's'} captured` : 'Company'
    if (entityType === 'trust') return trusteeCount ? `Trust · ${trusteeCount} trustee${trusteeCount === 1 ? '' : 's'} captured` : 'Trust'
    if (entityType === 'close_corporation') return memberCount ? `Close corporation · ${memberCount} member${memberCount === 1 ? '' : 's'} captured` : 'Close corporation'
    return 'Juristic person'
  }
  return 'Capture seller details'
}

const KINGSTONS_FICA_SELLER_TYPE_LABELS = Object.freeze(
  KINGSTONS_FICA_SELLER_TYPE_OPTIONS.reduce((accumulator, option) => ({
    ...accumulator,
    [option.value]: option.label,
  }), {}),
)

const KINGSTONS_PIPELINE_STAGE_LABELS = Object.freeze({
  first_contact: 'First Contact',
  valuation_appointment_scheduled: 'Schedule Valuation Appointment',
  formal_valuation_completed: 'Formal Valuation',
  valuation_presentation_scheduled: 'Valuation Presentation',
  valuation_presented: 'Valuation Presented',
  seller_pack_signed: 'Seller Pack',
  listing_terms_confirmed: 'Listing Terms',
  listing_ready: 'List Property',
})

function hasKingstonsPipelineSignal(source = {}) {
  const lead = source.selectedLead || source.lead || {}
  const listing = source.listing || source.listingRecord || {}
  const exactOrganisationId = normalizeText(
    source.organisationId ||
      source.currentWorkspace?.id ||
      source.currentWorkspace?.organisationId ||
      source.currentWorkspace?.organisation_id ||
      source.currentMembership?.organisation_id ||
      source.currentMembership?.organization_id ||
      listing.organisationId ||
      listing.organisation_id ||
      lead.organisationId ||
      lead.organisation_id,
  ).toLowerCase()
  if (KINGSTONS_SELLER_PROCESS_ORGANISATION_IDS.includes(exactOrganisationId)) return true

  const listingFacts = asRecord(listing.sellerCanonicalFacts || listing.seller_canonical_facts_json)
  const listingPackFacts = asRecord(listingFacts.kingstonsSellerPack || listingFacts.sellerPackHandoff || listing.kingstonsSellerPack || listing.sellerPackHandoff)
  if (normalizeText(listingPackFacts.source).toLowerCase().includes('kingstons_seller_pack')) return true
  return false
}

function getKingstonsPipelineActionMeta(model = {}) {
  const cards = Array.isArray(model?.actionCards) ? model.actionCards : []
  const pending = cards.find((card) => card.pending) || cards[0] || null
  if (!pending) {
    return {
      title: model?.currentStageLabel || 'Kingstons Seller Process',
      copy: 'Review the Kingston seller process and continue from the correct workspace surface.',
      actionId: 'open_journey',
      label: 'Review Process',
    }
  }
  return {
    title: pending.label,
    copy: KINGSTONS_PIPELINE_ACTION_COPY[pending.key] || 'Continue the Kingston seller process from the correct workspace surface.',
    actionId: pending.key,
    label: pending.label,
    disabled: pending.disabled === true,
  }
}

function buildKingstonsPipelineRailSteps(model = {}) {
  const definition = getSellerProcessDefinition({ sellerProcessProfile: KINGSTONS_SELLER_PROCESS_PROFILE })
  const modelProgress = new Map(
    (model.sections?.find((section) => section.key === 'progress')?.items || []).map((item) => [item.key, item]),
  )
  return definition.stages
    .filter((stage) => stage.key !== 'valuation_presented')
    .map((stage, index) => {
      const progress = modelProgress.get(stage.key) || {}
      const isCurrent = progress.state === 'current' || stage.label === model.currentStageLabel
      const isCompleted = progress.state === 'complete' || progress.state === 'completed'
      return {
        key: stage.key,
        label: KINGSTONS_PIPELINE_STAGE_LABELS[stage.key] || stage.label,
        status: isCompleted ? 'Complete' : isCurrent ? 'Current Stage' : 'Upcoming',
        state: isCompleted ? 'completed' : isCurrent ? 'current' : 'upcoming',
        current: isCurrent,
        completed: isCompleted,
        upcoming: !isCurrent && !isCompleted,
        index,
      }
    })
}

function parseLeadRawEnquiryPayload(value) {
  if (!value) return {}
  if (value && typeof value === 'object' && !Array.isArray(value)) return value
  if (typeof value !== 'string') return {}
  try {
    const parsed = JSON.parse(value)
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {}
  } catch {
    return {}
  }
}

function getKingstonsSellerPackState(lead = {}) {
  const rawPayload = parseLeadRawEnquiryPayload(lead?.rawEnquiryPayload || lead?.raw_enquiry_payload)
  const pack = asRecord(
    lead?.kingstonsSellerPack ||
      lead?.kingstons_seller_pack ||
      lead?.sellerPack ||
      lead?.seller_pack ||
      rawPayload.kingstonsSellerPack ||
      rawPayload.kingstons_seller_pack ||
      rawPayload.sellerPack ||
      rawPayload.seller_pack,
  )
  const rawDocuments = asRecord(pack.documents || pack.documentUploads || pack.uploads)
  return {
    ...pack,
    sellerType: normalizeKey(pack.sellerType || pack.seller_type || pack.ficaSellerType || pack.fica_seller_type),
    documents: rawDocuments,
  }
}

function getKingstonsListingTermsState(lead = {}, listing = {}) {
  const rawPayload = parseLeadRawEnquiryPayload(lead?.rawEnquiryPayload || lead?.raw_enquiry_payload)
  const listingFacts = parseLeadRawEnquiryPayload(listing?.sellerCanonicalFacts || listing?.seller_canonical_facts_json)
  const terms = asRecord(
    lead?.kingstonsListingTerms ||
      lead?.kingstons_listing_terms ||
      lead?.listingTerms ||
      lead?.listing_terms ||
      rawPayload.kingstonsListingTerms ||
      rawPayload.kingstons_listing_terms ||
      rawPayload.listingTerms ||
      rawPayload.listing_terms ||
      listing?.kingstonsListingTerms ||
      listing?.kingstons_listing_terms ||
      listingFacts.kingstonsListingTerms ||
      listingFacts.listingTerms,
  )
  const commission = asRecord(terms.commission || terms.commissionTerms || terms.commission_terms)
  const transferAttorney = asRecord(terms.transferAttorney || terms.transfer_attorney || terms.attorney || terms.nominatedAttorney)
  return {
    ...terms,
    commission,
    transferAttorney,
  }
}

function buildKingstonsListingTermsDraft(terms = {}) {
  const commission = asRecord(terms.commission || terms.commissionTerms || terms.commission_terms)
  const attorney = asRecord(terms.transferAttorney || terms.transfer_attorney || terms.attorney || terms.nominatedAttorney)
  return {
    commissionType: normalizeKey(commission.type || commission.commissionType || commission.commission_type || terms.commissionType || terms.commission_type) || 'percentage',
    commissionPercentage: normalizeText(commission.percentage || commission.commissionPercentage || commission.commission_percentage || terms.commissionPercentage || terms.commission_percentage),
    commissionAmount: normalizeText(commission.amount || commission.commissionAmount || commission.commission_amount || terms.commissionAmount || terms.commission_amount),
    commissionNotes: normalizeText(commission.notes || commission.commissionNotes || commission.commission_notes || terms.commissionNotes || terms.notes),
    transferAttorneyMode: normalizeKey(attorney.mode || attorney.selectionSource || attorney.selection_source || terms.transferAttorneyMode || terms.transfer_attorney_mode) || 'agency_recommended',
    transferAttorneyId: normalizeText(attorney.id || attorney.preferredPartnerId || attorney.preferred_partner_id || terms.transferAttorneyId || terms.transfer_attorney_id),
    transferAttorneyCompany: normalizeText(attorney.companyName || attorney.company_name || attorney.name || attorney.label || terms.transferAttorneyCompany || terms.transfer_attorney_company),
    transferAttorneyContact: normalizeText(attorney.contactPerson || attorney.contact_person || attorney.contactName || attorney.contact_name || terms.transferAttorneyContact || terms.transfer_attorney_contact),
    transferAttorneyEmail: normalizeText(attorney.email || attorney.emailAddress || attorney.email_address || terms.transferAttorneyEmail || terms.transfer_attorney_email).toLowerCase(),
    transferAttorneyPhone: normalizeText(attorney.phone || attorney.phoneNumber || attorney.phone_number || terms.transferAttorneyPhone || terms.transfer_attorney_phone),
  }
}

function summarizeKingstonsListingTerms(terms = {}) {
  const draft = buildKingstonsListingTermsDraft(terms)
  const commissionType = normalizeKey(draft.commissionType)
  const commissionComplete = commissionType === 'fixed'
    ? Number(draft.commissionAmount || 0) > 0
    : Number(draft.commissionPercentage || 0) > 0
  const attorneyComplete = Boolean(
    normalizeText(draft.transferAttorneyId) ||
      normalizeText(draft.transferAttorneyCompany) ||
      normalizeText(draft.transferAttorneyEmail),
  )
  const missingLabels = [
    ...(commissionComplete ? [] : ['Commission terms']),
    ...(attorneyComplete ? [] : ['Transfer attorney']),
  ]
  return {
    commissionComplete,
    attorneyComplete,
    complete: commissionComplete && attorneyComplete,
    missingLabels,
    commissionLabel: commissionComplete
      ? commissionType === 'fixed'
        ? `Fixed fee R ${Number(draft.commissionAmount || 0).toLocaleString('en-ZA')}`
        : `${draft.commissionPercentage}% commission`
      : 'Commission not captured',
    attorneyLabel: attorneyComplete
      ? normalizeText(draft.transferAttorneyCompany || draft.transferAttorneyEmail || draft.transferAttorneyId)
      : 'Attorney not nominated',
  }
}

function getKingstonsListingTermsPipelineStatus(terms = {}, summary = {}) {
  const attorney = asRecord(terms.transferAttorney || terms.transfer_attorney || terms.attorney || terms.nominatedAttorney)
  const partnerOrganisationId = normalizeText(
    attorney.partnerOrganisationId ||
      attorney.partner_organisation_id ||
      attorney.partnerOrgId ||
      attorney.partner_org_id,
  )

  if (!summary.complete) {
    return {
      label: 'Not ready',
      copy: 'Confirm commission and transfer attorney before listing.',
    }
  }

  if (partnerOrganisationId) {
    return {
      label: 'Awaiting buyer',
      copy: 'Connected attorney is visible in the pre-instruction pipeline.',
    }
  }

  return {
    label: 'Pending connection',
    copy: 'Attorney is captured, but not routed until the firm is connected.',
  }
}

function buildKingstonsAttorneyPipelineVerification({
  listingId = '',
  summary = {},
  terms = {},
  allocation = null,
  loading = false,
  error = '',
} = {}) {
  const attorney = asRecord(terms.transferAttorney || terms.transfer_attorney || terms.attorney || terms.nominatedAttorney)
  const partnerOrganisationId = normalizeText(
    attorney.partnerOrganisationId ||
      attorney.partner_organisation_id ||
      attorney.partnerOrgId ||
      attorney.partner_org_id,
  )
  const allocationStatus = normalizeKey(allocation?.status || allocation?.allocationStatus || allocation?.allocation_status)

  if (!summary.complete) {
    return {
      state: 'not_ready',
      label: 'Not ready',
      copy: 'Confirm commission and transfer attorney before listing.',
    }
  }

  if (!normalizeText(listingId)) {
    return {
      state: 'not_listed',
      label: 'Not listed yet',
      copy: 'Create the listing to add a connected attorney to the pre-instruction pipeline.',
    }
  }

  if (loading) {
    return {
      state: 'checking',
      label: 'Checking pipeline',
      copy: 'Verifying the transfer attorney allocation against the attorney pipeline.',
    }
  }

  if (error) {
    return {
      state: 'error',
      label: 'Check failed',
      copy: error,
    }
  }

  if (allocationStatus === 'awaiting_buyer') {
    return {
      state: 'verified_pre_instruction',
      label: 'Verified in attorney pipeline',
      copy: 'Attorney can see this as awaiting buyer. Signed OTP still sends the formal instruction.',
      allocation,
    }
  }

  if (allocationStatus === 'under_offer') {
    return {
      state: 'under_offer',
      label: 'Buyer offer active',
      copy: 'Attorney allocation has moved beyond pre-instruction, but is not formally instructed until signed OTP.',
      allocation,
    }
  }

  if (['instructed', 'converted'].includes(allocationStatus)) {
    return {
      state: allocationStatus,
      label: 'Formal instruction active',
      copy: 'Signed OTP has promoted this transfer attorney allocation into the instruction lane.',
      allocation,
    }
  }

  if (allocation) {
    return {
      state: allocationStatus || 'allocated',
      label: allocationStatus ? titleCaseWorkspaceValue(allocationStatus) : 'Allocated',
      copy: 'Transfer attorney allocation exists for this listing.',
      allocation,
    }
  }

  if (!partnerOrganisationId) {
    return {
      state: 'pending_connection',
      label: 'Pending connection',
      copy: 'Attorney is captured, but not routed until the firm is connected.',
    }
  }

  return {
    state: 'missing_allocation',
    label: 'Not visible in pipeline',
    copy: 'A connected attorney is nominated, but no awaiting-buyer allocation was found for this listing.',
  }
}

function getKingstonsExceptionSeverityClass(severity = '') {
  const normalized = normalizeKey(severity)
  if (normalized === 'critical') {
    return {
      rail: 'border-[#f3c6c3] bg-[#fff5f4]',
      icon: 'bg-white text-[#b42318]',
      badge: 'border-[#f3c6c3] bg-white text-[#b42318]',
    }
  }
  if (normalized === 'warning') {
    return {
      rail: 'border-[#f0d9ab] bg-[#fff8e8]',
      icon: 'bg-white text-[#9a6b19]',
      badge: 'border-[#f0d9ab] bg-white text-[#8a641d]',
    }
  }
  return {
    rail: 'border-[#dce8f4] bg-[#fbfdff]',
    icon: 'bg-white text-[#315b7a]',
    badge: 'border-[#dce8f4] bg-white text-[#315b7a]',
  }
}

function buildKingstonsListingTermsExceptionReport({
  sellerJourney = {},
  sellerPackSummary = {},
  listingTermsSummary = {},
  listingTerms = {},
  listingId = '',
  pipelineVerification = {},
  thresholds = KINGSTONS_LISTING_TERMS_EXCEPTION_THRESHOLDS,
} = {}) {
  const currentStageDays = Math.max(0, Number(sellerJourney?.daysInCurrentStage || 0) || 0)
  const pipelineState = normalizeKey(pipelineVerification?.state)
  const listingCreated = Boolean(normalizeText(listingId))
  const sellerPackComplete = sellerPackSummary?.complete === true
  const listingTermsComplete = listingTermsSummary?.complete === true
  const termsConfirmedAt = normalizeText(listingTerms?.confirmedAt || listingTerms?.confirmed_at)
  const items = []

  if (sellerPackComplete && !listingTermsComplete) {
    const stale = currentStageDays >= thresholds.listingTermsDays
    items.push({
      key: 'listing_terms_stale',
      severity: stale ? 'warning' : 'info',
      title: stale ? 'Listing Terms is waiting' : 'Listing Terms still outstanding',
      copy: `Capture commission and the nominated transfer attorney before List Property. Still needed: ${(listingTermsSummary?.missingLabels || []).join(', ') || 'Listing Terms'}.`,
      ageLabel: `${currentStageDays} days in current stage`,
      action: 'confirm_terms',
      actionLabel: 'Confirm terms',
    })
  }

  if (sellerPackComplete && listingTermsComplete && !listingCreated) {
    const stale = currentStageDays >= thresholds.listPropertyDays
    items.push({
      key: 'list_property_stale',
      severity: stale ? 'warning' : 'info',
      title: stale ? 'Ready to list, but not listed' : 'Ready for List Property',
      copy: 'Seller Pack and Listing Terms are complete. Create the listing to open the pre-instruction attorney visibility path.',
      ageLabel: termsConfirmedAt ? `Terms confirmed ${termsConfirmedAt}` : `${currentStageDays} days in current stage`,
      action: 'create_listing',
      actionLabel: 'Create listing',
    })
  }

  if (sellerPackComplete && listingTermsComplete && ['missing_allocation', 'error'].includes(pipelineState)) {
    items.push({
      key: 'attorney_pipeline_exception',
      severity: 'critical',
      title: 'Transfer attorney is not visible',
      copy: pipelineVerification?.copy || 'The nominated transfer attorney should be in the awaiting-buyer pipeline, but the allocation was not found.',
      ageLabel: `${Math.max(currentStageDays, thresholds.attorneyPipelineDays)} day watch`,
      action: 'retry_pipeline_sync',
      actionLabel: 'Retry pipeline sync',
    })
  }

  if (sellerPackComplete && listingTermsComplete && pipelineState === 'pending_connection') {
    items.push({
      key: 'attorney_connection_pending',
      severity: 'warning',
      title: 'Attorney connection required',
      copy: pipelineVerification?.copy || 'The seller-selected attorney is captured, but the firm is not connected to this agency yet.',
      ageLabel: 'Partner setup needed',
      action: 'confirm_terms',
      actionLabel: 'Review terms',
    })
  }

  const criticalCount = items.filter((item) => item.severity === 'critical').length
  const warningCount = items.filter((item) => item.severity === 'warning').length
  const health = criticalCount ? 'critical' : warningCount ? 'attention' : items.length ? 'watch' : 'clear'

  return {
    health,
    statusLabel: health === 'clear'
      ? 'Clear'
      : criticalCount
        ? `${criticalCount} critical`
        : `${warningCount || items.length} on watch`,
    currentStageDays,
    items,
    metrics: [
      {
        key: 'seller_pack',
        label: 'Seller Pack',
        value: sellerPackComplete ? 'Complete' : `${sellerPackSummary?.completed || 0} of ${sellerPackSummary?.total || 0}`,
      },
      {
        key: 'listing_terms',
        label: 'Listing Terms',
        value: listingTermsComplete ? 'Confirmed' : 'Outstanding',
      },
      {
        key: 'list_property',
        label: 'List Property',
        value: listingCreated ? 'Created' : 'Not created',
      },
      {
        key: 'attorney_pipeline',
        label: 'Attorney Pipeline',
        value: pipelineVerification?.label || 'Not checked',
      },
    ],
  }
}

function buildKingstonsPrincipalListingTermsExceptionReport({
  leads = [],
  appointments = [],
  organisationId = '',
  currentAgent = {},
  resolveLeadLinkedListing = null,
  allocationByListingId = {},
  checkedListingIds = [],
  allocationsLoading = false,
  allocationsError = '',
} = {}) {
  const rows = []
  let totalKingstonsLeads = 0
  const checkedIds = new Set((Array.isArray(checkedListingIds) ? checkedListingIds : []).map(normalizeText).filter(Boolean))

  for (const lead of Array.isArray(leads) ? leads : []) {
    if (resolveLeadCategoryView(lead) !== 'seller') continue
    const listing = typeof resolveLeadLinkedListing === 'function' ? resolveLeadLinkedListing(lead) : null
    const isKingstons = hasKingstonsPipelineSignal({
      lead,
      listing,
      organisationId,
      currentAgent,
    })
    if (!isKingstons) continue
    totalKingstonsLeads += 1

    const leadKey = normalizeLeadIdentityKey(lead?.leadId || lead?.id)
    const leadAppointments = (Array.isArray(appointments) ? appointments : []).filter(
      (appointment) => normalizeLeadIdentityKey(appointment?.leadId) === leadKey,
    )
    const sellerJourney = buildSellerJourney({
      lead,
      appointments: leadAppointments,
      listing,
      documents: listing?.documents || [],
    })
    const sellerPackSummary = summarizeKingstonsSellerPack(buildKingstonsSellerPackDocumentRows(lead))
    const listingTerms = getKingstonsListingTermsState(lead, listing || {})
    const listingTermsSummary = summarizeKingstonsListingTerms(listingTerms)
    const listingId = normalizeText(
      listing?.id ||
        listing?.listingId ||
        listing?.listing_id ||
        lead?.listingId ||
        lead?.listing_id ||
        lead?.privateListingId ||
        lead?.private_listing_id,
    )
    const allocation = listingId
      ? allocationByListingId?.[listingId] || allocationByListingId?.[normalizeText(listingId)] || null
      : null
    const allocationChecked = listingId ? checkedIds.has(listingId) : false
    const pipelineVerification = buildKingstonsAttorneyPipelineVerification({
      listingId,
      summary: listingTermsSummary,
      terms: listingTerms,
      allocation,
      loading: Boolean(allocationsLoading && listingId && !allocationChecked),
    })
    const report = buildKingstonsListingTermsExceptionReport({
      sellerJourney,
      sellerPackSummary,
      listingTermsSummary,
      listingTerms,
      listingId,
      pipelineVerification,
    })

    for (const item of report.items || []) {
      rows.push({
        ...item,
        leadId: normalizeText(lead?.leadId || lead?.id),
        leadName: resolveLeadDisplayName(lead, null, null, 'Unnamed seller'),
        agent: normalizeText(lead?.assignedAgentName || lead?.assignedAgentEmail || currentAgent?.fullName || currentAgent?.email) || 'Unassigned',
        property: normalizeText(lead?.sellerPropertyAddress || lead?.propertyInterest || listing?.address || listing?.label || listing?.title) || 'Property pending',
        stage: sellerJourney?.stage?.label || KINGSTONS_PIPELINE_STAGE_LABELS[normalizeKey(sellerJourney?.stage?.key)] || 'Kingstons Seller Process',
        days: report.currentStageDays,
        pipelineLabel: pipelineVerification?.label || 'Not checked',
        allocationChecked,
      })
    }
  }

  const severityRank = { critical: 0, warning: 1, info: 2 }
  const sortedRows = rows.sort((left, right) => {
    const leftRank = severityRank[normalizeKey(left.severity)] ?? 3
    const rightRank = severityRank[normalizeKey(right.severity)] ?? 3
    if (leftRank !== rightRank) return leftRank - rightRank
    return Number(right.days || 0) - Number(left.days || 0)
  })
  const criticalCount = sortedRows.filter((row) => normalizeKey(row.severity) === 'critical').length
  const warningCount = sortedRows.filter((row) => normalizeKey(row.severity) === 'warning').length
  const listingTermsCount = sortedRows.filter((row) => row.key === 'listing_terms_stale').length
  const listPropertyCount = sortedRows.filter((row) => row.key === 'list_property_stale').length
  const attorneyCount = sortedRows.filter((row) => row.key === 'attorney_pipeline_exception' || row.key === 'attorney_connection_pending').length

  return {
    totalKingstonsLeads,
    totalExceptions: sortedRows.length,
    criticalCount,
    warningCount,
    listingTermsCount,
    listPropertyCount,
    attorneyCount,
    allocationsLoading: allocationsLoading === true,
    allocationsError: normalizeText(allocationsError),
    checkedListingCount: checkedIds.size,
    averageDays: sortedRows.length
      ? Math.round(sortedRows.reduce((sum, row) => sum + Number(row.days || 0), 0) / sortedRows.length)
      : 0,
    rows: sortedRows,
  }
}

function escapeKingstonsPrincipalCsvCell(value = '') {
  const text = String(value ?? '')
  if (!/[",\n\r]/.test(text)) return text
  return `"${text.replace(/"/g, '""')}"`
}

function formatKingstonsPrincipalActionLabel(action = '') {
  const normalized = normalizeKey(action)
  if (normalized === 'confirm_terms') return 'Confirm listing terms'
  if (normalized === 'create_listing') return 'Create private listing'
  if (normalized === 'retry_pipeline_sync') return 'Retry attorney pipeline sync'
  if (normalized === 'connect_attorney') return 'Connect nominated attorney'
  return 'Review lead'
}

function buildKingstonsPrincipalExceptionReportCsv(report = {}, { generatedAt = new Date() } = {}) {
  const rows = Array.isArray(report.rows) ? report.rows : []
  const generatedIso = generatedAt instanceof Date && !Number.isNaN(generatedAt.getTime())
    ? generatedAt.toISOString()
    : new Date().toISOString()
  const headers = [
    'Generated At',
    'Seller',
    'Property',
    'Agent',
    'Stage',
    'Days In Stage',
    'Severity',
    'Exception',
    'Detail',
    'Recommended Action',
    'Attorney Pipeline',
    'Allocation Checked',
    'Lead ID',
  ]
  const bodyRows = rows.length
    ? rows.map((row) => [
        generatedIso,
        row.leadName,
        row.property,
        row.agent,
        row.stage,
        row.days,
        row.severity,
        row.title,
        row.copy,
        formatKingstonsPrincipalActionLabel(row.action),
        row.pipelineLabel,
        row.allocationChecked ? 'Yes' : 'No',
        row.leadId,
      ])
    : [[
        generatedIso,
        'No open Kingstons seller workflow exceptions',
        '',
        '',
        '',
        '',
        'clear',
        'Clear',
        `Kingstons leads checked: ${report.totalKingstonsLeads || 0}; listings checked: ${report.checkedListingCount || 0}`,
        'No action required',
        report.allocationsError ? `Verification failed: ${report.allocationsError}` : 'Verified from loaded workspace data',
        report.checkedListingCount ? 'Yes' : 'No',
        '',
      ]]

  return [headers, ...bodyRows]
    .map((row) => row.map(escapeKingstonsPrincipalCsvCell).join(','))
    .join('\n')
}

function downloadKingstonsPrincipalExceptionReportCsv(report = {}) {
  if (typeof document === 'undefined' || typeof Blob === 'undefined' || typeof URL === 'undefined') return
  const today = new Date().toISOString().slice(0, 10)
  const csv = buildKingstonsPrincipalExceptionReportCsv(report)
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' })
  const objectUrl = URL.createObjectURL(blob)
  try {
    const link = document.createElement('a')
    link.href = objectUrl
    link.download = `kingstons-seller-workflow-exceptions-${today}.csv`
    link.rel = 'noopener'
    link.style.display = 'none'
    document.body.appendChild(link)
    link.click()
    link.remove()
  } finally {
    URL.revokeObjectURL(objectUrl)
  }
}

function buildKingstonsPrincipalExceptionDigest(report = {}, { generatedAt = new Date(), maxRows = 8 } = {}) {
  const rows = Array.isArray(report.rows) ? report.rows : []
  const generatedIso = generatedAt instanceof Date && !Number.isNaN(generatedAt.getTime())
    ? generatedAt.toISOString()
    : new Date().toISOString()
  const lines = [
    'Kingstons Seller Workflow Digest',
    `Generated: ${generatedIso}`,
    '',
    'Summary',
    `- Kingstons seller leads checked: ${report.totalKingstonsLeads || 0}`,
    `- Open exceptions: ${report.totalExceptions || 0}`,
    `- Critical: ${report.criticalCount || 0}`,
    `- Warnings: ${report.warningCount || 0}`,
    `- Listing Terms exceptions: ${report.listingTermsCount || 0}`,
    `- Attorney watch exceptions: ${report.attorneyCount || 0}`,
    `- Transfer-attorney allocations checked: ${report.checkedListingCount || 0}`,
  ]

  if (report.allocationsError) {
    lines.push(`- Allocation verification issue: ${report.allocationsError}`)
  } else if (report.allocationsLoading) {
    lines.push('- Allocation verification: still checking loaded Kingstons listings')
  } else {
    lines.push('- Allocation verification: complete for loaded Kingstons listings')
  }

  lines.push('')

  if (!rows.length) {
    lines.push('No open Kingstons seller workflow exceptions right now.')
    lines.push('Recommended action: no principal follow-up required.')
    return lines.join('\n')
  }

  lines.push(`Top ${Math.min(rows.length, maxRows)} exceptions`)
  rows.slice(0, maxRows).forEach((row, index) => {
    lines.push(`${index + 1}. ${row.leadName || 'Unnamed seller'} - ${row.title || 'Workflow exception'}`)
    lines.push(`   Property: ${row.property || 'Property pending'}`)
    lines.push(`   Agent: ${row.agent || 'Unassigned'}`)
    lines.push(`   Stage: ${row.stage || 'Kingstons Seller Process'} (${row.days || 0} days)`)
    lines.push(`   Severity: ${row.severity || 'warning'}`)
    lines.push(`   Attorney pipeline: ${row.pipelineLabel || 'Not checked'}; allocation checked: ${row.allocationChecked ? 'yes' : 'no'}`)
    lines.push(`   Recommended action: ${formatKingstonsPrincipalActionLabel(row.action)}`)
    if (row.copy) lines.push(`   Detail: ${row.copy}`)
  })

  if (rows.length > maxRows) {
    lines.push('')
    lines.push(`${rows.length - maxRows} more exception${rows.length - maxRows === 1 ? '' : 's'} in the principal report. Export CSV for the full list.`)
  }

  return lines.join('\n')
}

async function copyKingstonsPrincipalExceptionDigest(report = {}) {
  const digest = buildKingstonsPrincipalExceptionDigest(report)
  if (typeof navigator !== 'undefined' && navigator.clipboard?.writeText) {
    await navigator.clipboard.writeText(digest)
    return digest
  }
  if (typeof document === 'undefined') return digest
  const textarea = document.createElement('textarea')
  textarea.value = digest
  textarea.setAttribute('readonly', 'true')
  textarea.style.position = 'fixed'
  textarea.style.left = '-9999px'
  document.body.appendChild(textarea)
  textarea.select()
  const copied = document.execCommand?.('copy')
  textarea.remove()
  if (copied === false) throw new Error('Clipboard copy was not allowed by the browser.')
  return digest
}

