function buildKingstonsListingTermsPayload(draft = {}, attorneyOption = null, actorLabel = '') {
  const selectedAttorney = asRecord(attorneyOption)
  const companyName = normalizeText(
    selectedAttorney.companyName ||
      selectedAttorney.company_name ||
      selectedAttorney.name ||
      draft.transferAttorneyCompany,
  )
  const contactPerson = normalizeText(
    selectedAttorney.contactPerson ||
      selectedAttorney.contact_person ||
      selectedAttorney.preferredAttorneyName ||
      selectedAttorney.selectedPerson?.name ||
      draft.transferAttorneyContact,
  )
  const email = normalizeText(
    selectedAttorney.email ||
      selectedAttorney.emailAddress ||
      selectedAttorney.email_address ||
      selectedAttorney.preferredAttorneyEmail ||
      selectedAttorney.selectedPerson?.email ||
      draft.transferAttorneyEmail,
  ).toLowerCase()
  const phone = normalizeText(
    selectedAttorney.phone ||
      selectedAttorney.phoneNumber ||
      selectedAttorney.phone_number ||
      selectedAttorney.preferredAttorneyPhone ||
      selectedAttorney.selectedPerson?.phone ||
      draft.transferAttorneyPhone,
  )
  const commissionType = normalizeKey(draft.commissionType) || 'percentage'
  const commissionPercentage = Number(draft.commissionPercentage || 0) || null
  const commissionAmount = Number(draft.commissionAmount || 0) || null
  return {
    source: 'kingstons_listing_terms_phase1',
    status: 'confirmed',
    commissionConfirmed: true,
    transferAttorneyNominated: true,
    confirmedAt: new Date().toISOString(),
    confirmedBy: actorLabel,
    commission: {
      type: commissionType,
      commissionType,
      percentage: commissionType === 'percentage' ? commissionPercentage : null,
      commissionPercentage: commissionType === 'percentage' ? commissionPercentage : null,
      amount: commissionType === 'fixed' ? commissionAmount : null,
      commissionAmount: commissionType === 'fixed' ? commissionAmount : null,
      notes: normalizeText(draft.commissionNotes),
      confirmed: true,
    },
    transferAttorney: {
      id: normalizeText(selectedAttorney.id || draft.transferAttorneyId),
      preferredPartnerId: normalizeText(selectedAttorney.preferredPartnerId || selectedAttorney.preferred_partner_id || selectedAttorney.id || draft.transferAttorneyId),
      partnerOrganisationId: normalizeText(selectedAttorney.partnerOrganisationId || selectedAttorney.partner_organisation_id),
      preferredAttorneyUserId: normalizeText(selectedAttorney.preferredAttorneyUserId || selectedAttorney.preferred_attorney_user_id),
      companyName,
      contactPerson,
      email,
      phone,
      selectionSource: normalizeKey(draft.transferAttorneyMode) || 'agency_recommended',
      allocationStatus: 'awaiting_buyer',
      nominated: true,
    },
  }
}

function validateKingstonsListingTermsDraft(draft = {}) {
  const commissionType = normalizeKey(draft.commissionType)
  if (!commissionType) return 'Choose the commission type.'
  if (commissionType === 'fixed') {
    if (!(Number(draft.commissionAmount || 0) > 0)) return 'Add the fixed commission amount.'
  } else if (!(Number(draft.commissionPercentage || 0) > 0)) {
    return 'Add the commission percentage.'
  }
  if (!normalizeText(draft.transferAttorneyId || draft.transferAttorneyCompany || draft.transferAttorneyEmail)) {
    return 'Choose or capture the nominated transfer attorney.'
  }
  return ''
}

function isValidKingstonsFicaSellerType(value = '') {
  return Boolean(KINGSTONS_FICA_SELLER_TYPE_LABELS[normalizeKey(value)])
}

function getKingstonsFicaSellerTypeLabel(value = '') {
  return KINGSTONS_FICA_SELLER_TYPE_LABELS[normalizeKey(value)] || 'Not selected'
}

function hasKingstonsSellerPackUploadEvidence(documentRow = {}) {
  return Boolean(
    documentRow.url ||
      documentRow.fileUrl ||
      documentRow.file_url ||
      documentRow.downloadUrl ||
      documentRow.download_url ||
      documentRow.storagePath ||
      documentRow.storage_path ||
      documentRow.documentId ||
      documentRow.document_id ||
      documentRow.fileId ||
      documentRow.file_id ||
      documentRow.uploadedAt ||
      documentRow.uploaded_at ||
      Number(documentRow.fileSize || documentRow.file_size || 0) > 0,
  )
}

function isKingstonsSellerPackDocumentUploaded(documentRow = {}) {
  return hasKingstonsSellerPackUploadEvidence(documentRow)
}

function getKingstonsFormalValuationState(lead = {}) {
  const rawPayload = parseLeadRawEnquiryPayload(lead?.rawEnquiryPayload || lead?.raw_enquiry_payload)
  const formalValuation = asRecord(
    lead?.kingstonsFormalValuation ||
      lead?.kingstons_formal_valuation ||
      lead?.formalValuation ||
      lead?.formal_valuation ||
      lead?.valuationDocument ||
      lead?.valuation_document ||
      rawPayload.kingstonsFormalValuation ||
      rawPayload.kingstons_formal_valuation ||
      rawPayload.formalValuation ||
      rawPayload.formal_valuation ||
      rawPayload.valuationDocument ||
      rawPayload.valuation_document,
  )
  const document = asRecord(formalValuation.document || formalValuation.upload || formalValuation.file || formalValuation)
  return {
    ...formalValuation,
    document,
  }
}

function buildKingstonsFormalValuationDocumentRow(lead = {}) {
  const valuation = getKingstonsFormalValuationState(lead)
  const uploaded = asRecord(valuation.document)
  const uploadedAt = firstWorkspaceText(uploaded.uploadedAt, uploaded.uploaded_at, valuation.uploadedAt, valuation.uploaded_at)
  const uploadedFileName = firstWorkspaceText(uploaded.uploadedFileName, uploaded.uploaded_file_name, uploaded.fileName, uploaded.file_name, valuation.uploadedFileName, valuation.fileName)
  const storagePath = firstWorkspaceText(uploaded.storagePath, uploaded.storage_path, valuation.storagePath, valuation.storage_path)
  const storageBucket = firstWorkspaceText(uploaded.storageBucket, uploaded.storage_bucket, valuation.storageBucket, valuation.storage_bucket)
  const url = firstWorkspaceText(uploaded.url, uploaded.fileUrl, uploaded.file_url, uploaded.downloadUrl, uploaded.download_url, valuation.url, valuation.fileUrl, valuation.downloadUrl)
  const hasUpload = isKingstonsSellerPackDocumentUploaded({
    ...uploaded,
    uploadedAt,
    storagePath,
    url,
  })

  return {
    ...KINGSTONS_FORMAL_VALUATION_DOCUMENT,
    ...uploaded,
    id: KINGSTONS_FORMAL_VALUATION_DOCUMENT.key,
    key: KINGSTONS_FORMAL_VALUATION_DOCUMENT.key,
    requirementKey: KINGSTONS_FORMAL_VALUATION_DOCUMENT.key,
    requirement_key: KINGSTONS_FORMAL_VALUATION_DOCUMENT.key,
    documentType: KINGSTONS_FORMAL_VALUATION_DOCUMENT.key,
    document_type: KINGSTONS_FORMAL_VALUATION_DOCUMENT.key,
    title: KINGSTONS_FORMAL_VALUATION_DOCUMENT.label,
    label: KINGSTONS_FORMAL_VALUATION_DOCUMENT.label,
    required: true,
    source: 'kingstons_formal_valuation',
    category: KINGSTONS_FORMAL_VALUATION_DOCUMENT.category,
    document_category: KINGSTONS_FORMAL_VALUATION_DOCUMENT.category,
    status: hasUpload ? 'uploaded' : 'required',
    statusLabel: hasUpload ? 'Uploaded' : 'Required',
    uploadedAt,
    uploaded_at: uploadedAt,
    uploadedFileName,
    storagePath,
    storage_path: storagePath,
    storageBucket,
    storage_bucket: storageBucket,
    url,
    fileUrl: url,
    file_url: url,
    downloadUrl: url,
    download_url: url,
  }
}

function buildKingstonsSellerPackBaselineDocumentRows(lead = {}) {
  const sellerPack = getKingstonsSellerPackState(lead)
  return KINGSTONS_SELLER_PACK_DOCUMENTS.map((definition) => {
    const uploaded = asRecord(sellerPack.documents?.[definition.key])
    const uploadedAt = firstWorkspaceText(uploaded.uploadedAt, uploaded.uploaded_at)
    const uploadedFileName = firstWorkspaceText(uploaded.uploadedFileName, uploaded.uploaded_file_name, uploaded.fileName, uploaded.file_name)
    const storagePath = firstWorkspaceText(uploaded.storagePath, uploaded.storage_path)
    const storageBucket = firstWorkspaceText(uploaded.storageBucket, uploaded.storage_bucket)
    const url = firstWorkspaceText(uploaded.url, uploaded.fileUrl, uploaded.file_url, uploaded.downloadUrl, uploaded.download_url)
    return {
      ...definition,
      ...uploaded,
      id: definition.key,
      key: definition.key,
      requirementKey: definition.key,
      requirement_key: definition.key,
      title: definition.label,
      label: definition.label,
      required: true,
      source: 'kingstons_seller_pack',
      category: definition.category,
      document_category: definition.category,
      status: isKingstonsSellerPackDocumentUploaded(uploaded) ? 'uploaded' : 'required',
      statusLabel: isKingstonsSellerPackDocumentUploaded(uploaded) ? 'Uploaded' : 'Required',
      uploadedAt,
      uploaded_at: uploadedAt,
      uploadedFileName,
      storagePath,
      storage_path: storagePath,
      storageBucket,
      storage_bucket: storageBucket,
      url,
      fileUrl: url,
      file_url: url,
      downloadUrl: url,
      download_url: url,
      sellerType: definition.requiresSellerType ? sellerPack.sellerType : '',
    }
  })
}

function isKingstonsGeneratedSellerPackRequirementRow(documentRow = {}) {
  const lane = normalizeKey(documentRow.requirementLane || documentRow.requirement_lane)
  const section = normalizeKey(documentRow.documentRequirementSection || documentRow.document_requirement_section)
  const key = normalizeKey(documentRow.key || documentRow.requirementKey || documentRow.requirement_key)
  return lane === 'ownership_driven' ||
    section === 'seller_identity_fica' ||
    section === 'authority_documents' ||
    normalizeKey(documentRow.source) === normalizeKey(KINGSTONS_FICA_ROLEPLAYER_SOURCE) ||
    /(seller_fica|owner_fica|director_fica|trustee_fica|member_fica|spouse_fica|resolution_to_sell|letters_of_authority|trust_deed|spouse_consent|owner_authority_consent)/.test(key)
}

function buildKingstonsSellerPackDocumentRows(lead = {}, {
  listing = null,
  journey = null,
  mandatePacketStatus = null,
  contact = null,
} = {}) {
  const baselineRows = buildKingstonsSellerPackBaselineDocumentRows(lead)
  const roleplayerFicaRows = buildKingstonsSellerFicaRoleplayerDocumentRows(lead, contact || {})
  const sourceRows = buildSellerLeadDocumentRowsFromSource({
    lead,
    listing,
    journey,
    mandatePacketStatus,
  })
  const generatedRows = sourceRows.filter((documentRow) => {
    const key = normalizeKey(documentRow.key || documentRow.requirementKey || documentRow.requirement_key)
    if (!key || key === KINGSTONS_FORMAL_VALUATION_DOCUMENT.key) return false
    return isKingstonsGeneratedSellerPackRequirementRow(documentRow)
  })

  return dedupeSellerLeadDocumentRows([
    ...baselineRows,
    ...roleplayerFicaRows,
    ...generatedRows,
  ])
}

function summarizeKingstonsSellerPack(documentRows = []) {
  const rows = Array.isArray(documentRows) ? documentRows : []
  const total = rows.length
  const missingRows = rows.filter((row) => !isKingstonsSellerPackDocumentUploaded(row))
  const completed = total - missingRows.length
  const ficaRow = rows.find((row) => row.requiresSellerType || row.key === 'signed_fica_form') || {}
  const sellerType = normalizeKey(ficaRow.sellerType)
  const sellerTypeCaptured = isValidKingstonsFicaSellerType(sellerType)
  const missingLabels = [
    ...missingRows.map((row) => row.label).filter(Boolean),
    ...(sellerTypeCaptured ? [] : ['FICA seller type']),
  ]
  const documentsComplete = total > 0 && completed === total
  return {
    total,
    completed,
    outstanding: Math.max(total - completed, 0),
    progress: total ? Math.round((completed / total) * 100) : 0,
    documentsComplete,
    sellerType,
    sellerTypeCaptured,
    sellerTypeLabel: getKingstonsFicaSellerTypeLabel(sellerType),
    complete: documentsComplete && sellerTypeCaptured,
    requiredLabels: rows.map((row) => row.label).filter(Boolean),
    missingLabels,
  }
}

function buildKingstonsSellerPackListingHandoffPayload({
  lead = {},
  documentRows = [],
  summary = null,
  contact = {},
  existingFacts = {},
  existingReadiness = {},
} = {}) {
  const rows = Array.isArray(documentRows) ? documentRows : []
  const packSummary = summary || summarizeKingstonsSellerPack(rows)
  const sellerType = normalizeKey(packSummary.sellerType || getKingstonsSellerPackState(lead).sellerType)
  const sellerTypeLabel = getKingstonsFicaSellerTypeLabel(sellerType)
  const listingTerms = getKingstonsListingTermsState(lead)
  const listingTermsSummary = summarizeKingstonsListingTerms(listingTerms)
  const listingTermsFacts = {
    ...listingTerms,
    source: listingTerms.source || 'kingstons_listing_terms_phase1',
    status: listingTermsSummary.complete ? 'confirmed' : 'incomplete',
    complete: listingTermsSummary.complete === true,
    commissionConfirmed: listingTermsSummary.commissionComplete === true,
    transferAttorneyNominated: listingTermsSummary.attorneyComplete === true,
  }
  const documents = rows.map((documentRow) => {
    const meta = getKingstonsSellerPackListingRequirementMeta(documentRow.key, documentRow)
    return {
      key: documentRow.key,
      label: documentRow.label,
      requirementKey: meta.requirementKey,
      documentType: meta.documentType,
      status: isKingstonsSellerPackDocumentUploaded(documentRow) ? 'uploaded' : 'required',
      uploadedAt: normalizeText(documentRow.uploadedAt || documentRow.uploaded_at),
      uploadedFileName: normalizeText(documentRow.uploadedFileName || documentRow.uploaded_file_name || documentRow.fileName || documentRow.file_name),
      storagePath: normalizeText(documentRow.storagePath || documentRow.storage_path),
      fileUrl: normalizeText(documentRow.url || documentRow.fileUrl || documentRow.file_url || documentRow.downloadUrl || documentRow.download_url),
    }
  })
  const portalRequests = buildKingstonsSellerPackPortalRequestRows(rows)
  const sellerPackFacts = {
    source: KINGSTONS_SELLER_PACK_LISTING_HANDOFF_SOURCE,
    status: packSummary.complete ? 'complete' : 'incomplete',
    complete: packSummary.complete === true,
    documentsComplete: packSummary.documentsComplete === true,
    sellerType,
    sellerTypeLabel,
    requiredLabels: packSummary.requiredLabels,
    missingLabels: packSummary.missingLabels,
    documents,
    sellerPortalRequestSource: KINGSTONS_SELLER_PACK_PORTAL_REQUEST_SYNC_SOURCE,
    portalRequests,
  }
  const sellerName = normalizeText(contact?.name || [contact?.firstName, contact?.lastName].filter(Boolean).join(' '))
  const sellerEmail = normalizeText(contact?.email).toLowerCase()
  const sellerPhone = normalizeText(contact?.phone)
  const sellerCanonicalFacts = {
    ...asRecord(existingFacts),
    ...(sellerType ? { sellerType, ficaSellerType: sellerType } : {}),
    ...(sellerName ? { sellerName } : {}),
    ...(sellerEmail ? { sellerEmail } : {}),
    ...(sellerPhone ? { sellerPhone } : {}),
    kingstonsSellerPack: sellerPackFacts,
    sellerPackHandoff: sellerPackFacts,
    kingstonsListingTerms: listingTermsFacts,
    listingTerms: listingTermsFacts,
  }
  const sellerCanonicalFactReadiness = {
    ...asRecord(existingReadiness),
    sellerType: packSummary.sellerTypeCaptured === true,
    ficaSellerType: packSummary.sellerTypeCaptured === true,
    signedMandate: documents.some((document) => document.key === 'signed_mandate' && document.status === 'uploaded'),
    signedDefectForm: documents.some((document) => document.key === 'signed_defect_form' && document.status === 'uploaded'),
    signedFicaForm: documents.some((document) => document.key === 'signed_fica_form' && document.status === 'uploaded'),
    kingstonsSellerPack: packSummary.complete === true,
    commissionTerms: listingTermsSummary.commissionComplete === true,
    transferAttorney: listingTermsSummary.attorneyComplete === true,
    kingstonsListingTerms: listingTermsSummary.complete === true,
    listingHandoff: packSummary.complete === true && listingTermsSummary.complete === true,
  }

  return {
    source: KINGSTONS_SELLER_PACK_LISTING_HANDOFF_SOURCE,
    sellerType,
    sellerTypeLabel,
    complete: packSummary.complete === true,
    documents,
    portalRequests,
    sellerCanonicalFacts,
    sellerCanonicalFactReadiness,
    listingPayload: {
      sellerType,
      mandateStatus: packSummary.complete ? 'signed_uploaded' : 'not_started',
      sellerCanonicalFacts,
      sellerCanonicalFactReadiness,
      sellerCanonicalFactsUpdatedAt: new Date().toISOString(),
      commission: listingTermsFacts.commission,
      commissionTerms: listingTermsFacts.commission,
      rolePlayers: {
        transferAttorney: listingTermsFacts.transferAttorney,
      },
      transferAttorneyName: listingTermsFacts.transferAttorney?.companyName || listingTermsFacts.transferAttorney?.contactPerson || '',
      transferAttorneyEmail: listingTermsFacts.transferAttorney?.email || '',
    },
  }
}

function getKingstonsSellerPackListingRequirementMeta(documentKey = '', documentRow = {}) {
  const key = normalizeKey(documentKey || documentRow.key || documentRow.requirementKey || documentRow.requirement_key)
  const label = normalizeText(documentRow.label || documentRow.title)
  const section = normalizeKey(documentRow.documentRequirementSection || documentRow.document_requirement_section)
  const group = normalizeKey(documentRow.group || documentRow.requirement_group)
  if (key === 'signed_defect_form') {
    return {
      requirementKey: 'property_condition_disclosure',
      requirementName: 'Signed Defect Form',
      requirementDescription: 'Signed seller defect disclosure required before listing.',
      requirementGroup: 'property',
      documentType: 'property_condition_disclosure',
      documentCategory: 'property_condition_disclosure',
    }
  }
  if (key === 'signed_fica_form') {
    return {
      requirementKey: 'signed_fica_form',
      requirementName: 'Signed FICA Form',
      requirementDescription: 'Signed FICA form for the selected seller type.',
      requirementGroup: 'fica',
      documentType: 'signed_fica_form',
      documentCategory: 'fica',
    }
  }
  if (section === 'seller_identity_fica' || /(owner_fica|director_fica|trustee_fica|member_fica|spouse_fica)/.test(key)) {
    return {
      requirementKey: key,
      requirementName: label || 'Seller FICA Document',
      requirementDescription: normalizeText(documentRow.description) || 'FICA document generated from the captured seller legal path.',
      requirementGroup: 'fica',
      documentType: key,
      documentCategory: 'fica',
    }
  }
  if (section === 'authority_documents' || group === 'authority_documents' || /(resolution_to_sell|letters_of_authority|trust_deed|spouse_consent|owner_authority_consent)/.test(key)) {
    return {
      requirementKey: key,
      requirementName: label || 'Seller Authority Document',
      requirementDescription: normalizeText(documentRow.description) || 'Authority document generated from the captured seller legal path.',
      requirementGroup: 'authority_documents',
      documentType: key,
      documentCategory: 'authority_documents',
    }
  }
  return {
    requirementKey: 'signed_mandate',
    requirementName: 'Signed Mandate',
    requirementDescription: 'Signed mandate required before listing.',
    requirementGroup: 'mandate',
    documentType: 'signed_mandate',
    documentCategory: 'mandate_signature',
  }
}

function getKingstonsSellerPackPortalRequestMeta(documentRow = {}) {
  const key = normalizeKey(documentRow.key || documentRow.requirementKey || documentRow.requirement_key)
  const section = normalizeKey(documentRow.documentRequirementSection || documentRow.document_requirement_section)
  const group = normalizeKey(documentRow.group || documentRow.requirement_group)
  const label = normalizeText(documentRow.label || documentRow.title || documentRow.name) || key.replace(/_/g, ' ').replace(/\b\w/g, (letter) => letter.toUpperCase())
  const isGenerated = isKingstonsGeneratedSellerPackRequirementRow(documentRow)
  const isAuthority = section === 'authority_documents' || group === 'authority_documents'
  const isFica = section === 'seller_identity_fica' || key.includes('fica')
  const partyName = normalizeText(documentRow.partyName || documentRow.party_name)
  const partyRole = normalizeKey(documentRow.partyRole || documentRow.party_role)
  return {
    key,
    label,
    requestTitle: label,
    requestDescription: normalizeText(documentRow.description) || (
      isAuthority
        ? 'Upload the authority document required for this seller legal path.'
        : isFica
          ? `Upload FICA documents${partyName ? ` for ${partyName}` : ''}.`
          : 'Upload this signed Seller Pack document.'
    ),
    requestedFromRole: 'seller',
    requestStage: 'seller_pack',
    requestPriority: isGenerated ? 'standard' : 'high',
    requestDeliveryChannels: ['seller_portal'],
    requestSource: KINGSTONS_SELLER_PACK_PORTAL_REQUEST_SYNC_SOURCE,
    requestDedupeKey: `kingstons_seller_pack:${key}`,
    portalSection: isAuthority ? 'Authority Documents' : isFica ? 'Seller FICA' : 'Legal Documents',
    portalInstruction: isAuthority
      ? 'Authority documents help confirm who can sign and approve the sale.'
      : isFica
        ? 'FICA documents are required before listing can proceed.'
        : 'This signed document is required before the property can be listed.',
    partyRole,
    partyName,
  }
}

function buildKingstonsSellerPackPortalRequestRows(documentRows = []) {
  return (Array.isArray(documentRows) ? documentRows : [])
    .filter((documentRow) => {
      const key = normalizeKey(documentRow.key || documentRow.requirementKey || documentRow.requirement_key)
      return Boolean(key && key !== KINGSTONS_FORMAL_VALUATION_DOCUMENT.key)
    })
    .map((documentRow) => {
      const meta = getKingstonsSellerPackListingRequirementMeta(documentRow.key, documentRow)
      const portalRequest = getKingstonsSellerPackPortalRequestMeta(documentRow)
      return {
        key: portalRequest.key,
        label: portalRequest.label,
        requirementKey: meta.requirementKey,
        documentType: meta.documentType,
        documentCategory: meta.documentCategory,
        requirementGroup: meta.requirementGroup,
        status: isKingstonsSellerPackDocumentUploaded(documentRow) ? 'uploaded' : 'requested',
        uploaded: isKingstonsSellerPackDocumentUploaded(documentRow),
        portalRequest,
      }
    })
}

function buildKingstonsSellerPackListingRequirementRows(documentRows = KINGSTONS_SELLER_PACK_DOCUMENTS) {
  return (Array.isArray(documentRows) && documentRows.length ? documentRows : KINGSTONS_SELLER_PACK_DOCUMENTS).map((documentRow) => {
    const meta = getKingstonsSellerPackListingRequirementMeta(documentRow.key, documentRow)
    const portalRequest = getKingstonsSellerPackPortalRequestMeta(documentRow)
    return {
      ...meta,
      status: 'required',
      isRequired: true,
      visibility: 'seller_visible',
      requestedFromRole: portalRequest.requestedFromRole,
      requestStage: portalRequest.requestStage,
      requestPriority: portalRequest.requestPriority,
      requestDeliveryChannels: portalRequest.requestDeliveryChannels,
      requestDedupeKey: portalRequest.requestDedupeKey,
      requestSource: portalRequest.requestSource,
      generatedFrom: {
        source: KINGSTONS_SELLER_PACK_PORTAL_REQUEST_SYNC_SOURCE,
        previousSource: 'kingstons_seller_lead_pack_phase7_readiness_gate',
        sellerPackDocumentKey: documentRow.key,
        portalRequest,
      },
    }
  })
}

function sanitizeSellerPackStorageSegment(value = '', fallback = 'document') {
  return normalizeText(value)
    .replace(/[^a-zA-Z0-9._-]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
    .toLowerCase() || fallback
}

function buildKingstonsSellerPackStoragePath({
  organisationId = '',
  leadId = '',
  documentKey = '',
  fileName = '',
  storageFolder = KINGSTONS_SELLER_PACK_STORAGE_FOLDER,
} = {}) {
  const timestamp = new Date().toISOString().replace(/[:.]/g, '-')
  return [
    storageFolder,
    sanitizeSellerPackStorageSegment(organisationId, 'organisation'),
    sanitizeSellerPackStorageSegment(leadId, 'lead'),
    sanitizeSellerPackStorageSegment(documentKey, 'document'),
    `${timestamp}-${sanitizeSellerPackStorageSegment(fileName, 'upload')}`,
  ].join('/')
}

async function uploadKingstonsSellerPackFile({
  file,
  organisationId = '',
  leadId = '',
  documentKey = '',
  storageFolder = KINGSTONS_SELLER_PACK_STORAGE_FOLDER,
} = {}) {
  if (!file) throw new Error('Select a file before uploading.')
  if (!isSupabaseConfigured || !supabase) throw new Error('Supabase storage is required before uploading seller pack files.')
  const objectPath = buildKingstonsSellerPackStoragePath({
    organisationId,
    leadId,
    documentKey,
    fileName: file.name || 'seller-pack-document',
    storageFolder,
  })
  let lastError = null
  for (const bucketName of DOCUMENTS_BUCKET_CANDIDATES) {
    const { data, error: uploadError } = await supabase.storage
      .from(bucketName)
      .upload(objectPath, file, {
        contentType: file.type || undefined,
        upsert: true,
      })
    if (uploadError) {
      lastError = uploadError
      continue
    }
    const storagePath = data?.path || objectPath
    return {
      storageBucket: bucketName,
      storagePath,
      url: '',
    }
  }
  throw lastError || new Error('Unable to upload the seller pack file.')
}

async function uploadBuyerOfferDocumentFile({
  file,
  organisationId = '',
  leadId = '',
  documentKey = BUYER_OFFER_DOCUMENT_TYPE,
  storageFolder = BUYER_OFFER_DOCUMENT_STORAGE_FOLDER,
} = {}) {
  return uploadKingstonsSellerPackFile({
    file,
    organisationId,
    leadId,
    documentKey,
    storageFolder,
  })
}

function resolveAgencyOfferEmailBranding({ organisationId = '', organisationName = '', profile = {}, currentWorkspace = {}, workspace = {} } = {}) {
  const resolved = resolveOnboardingBranding(currentWorkspace, workspace, profile)
  const fallbackName = normalizeText(
    organisationName ||
      profile?.companyName ||
      profile?.company ||
      profile?.organisationName ||
      currentWorkspace?.name ||
      workspace?.name,
  )
  const logoUrl = normalizeText(resolved.logoDarkUrl || resolved.logoLightUrl || resolved.logoIconUrl)
  const supportEmail = normalizeText(
    profile?.supportEmail ||
      profile?.support_email ||
      profile?.companyEmail ||
      profile?.company_email ||
      currentWorkspace?.supportEmail ||
      currentWorkspace?.support_email ||
      workspace?.supportEmail ||
      workspace?.support_email,
  )
  const supportPhone = normalizeText(
    profile?.supportPhone ||
      profile?.support_phone ||
      profile?.companyPhone ||
      profile?.company_phone ||
      currentWorkspace?.supportPhone ||
      currentWorkspace?.support_phone ||
      workspace?.supportPhone ||
      workspace?.support_phone,
  )
  const fromName = normalizeText(
    profile?.appointmentsFromName ||
      profile?.appointments_from_name ||
      profile?.emailFromName ||
      profile?.email_from_name ||
      currentWorkspace?.appointmentsFromName ||
      currentWorkspace?.appointments_from_name ||
      currentWorkspace?.emailFromName ||
      currentWorkspace?.email_from_name ||
      workspace?.appointmentsFromName ||
      workspace?.appointments_from_name ||
      workspace?.emailFromName ||
      workspace?.email_from_name ||
      fallbackName,
  )
  const fromEmail = normalizeText(
    profile?.appointmentsFromEmail ||
      profile?.appointments_from_email ||
      currentWorkspace?.appointmentsFromEmail ||
      currentWorkspace?.appointments_from_email ||
      workspace?.appointmentsFromEmail ||
      workspace?.appointments_from_email,
  )

  return {
    organisationId,
    organisationName: normalizeText(resolved.organisationName) || fallbackName,
    organisationLogoUrl: logoUrl,
    organisationLogoLightUrl: normalizeText(resolved.logoLightUrl || logoUrl),
    organisationLogoDarkUrl: normalizeText(resolved.logoDarkUrl || logoUrl),
    organisationLogoIconUrl: normalizeText(resolved.logoIconUrl),
    organisationBrandPrimaryColor: normalizeText(resolved.primaryColour),
    organisationBrandSecondaryColor: normalizeText(resolved.secondaryColour || resolved.accentColour),
    supportEmail,
    supportPhone,
    fromName,
    fromEmail,
  }
}

function getMandateManualOverrideFromSource(sourceContext = {}) {
  const override = sourceContext?.mandateManualOverride && typeof sourceContext.mandateManualOverride === 'object'
    ? sourceContext.mandateManualOverride
    : sourceContext?.mandate_manual_override && typeof sourceContext.mandate_manual_override === 'object'
      ? sourceContext.mandate_manual_override
      : {}
  return {
    ...override,
    fields: override?.fields && typeof override.fields === 'object' ? override.fields : {},
  }
}

function setManualMandateValue(target = {}, key = '', value = '') {
  const text = normalizeText(value)
  if (text) target[key] = text
}

function applyMandateManualOverrideToData(mandateData = null, sourceContext = {}) {
  if (!mandateData || typeof mandateData !== 'object') return mandateData
  const override = getMandateManualOverrideFromSource(sourceContext)
  const fields = override.fields || {}
  if (!Object.keys(fields).some((key) => normalizeText(fields[key]))) return mandateData

  const next = {
    ...mandateData,
    seller: { ...(mandateData.seller || {}) },
    property: { ...(mandateData.property || {}) },
    mandate: { ...(mandateData.mandate || {}) },
    agency: { ...(mandateData.agency || {}) },
    agent: { ...(mandateData.agent || {}) },
    transferAttorney: { ...(mandateData.transferAttorney || mandateData.transfer_attorney || {}) },
    placeholders: { ...(mandateData.placeholders || {}) },
    sourceContext: { ...(mandateData.sourceContext || mandateData.source_context || {}) },
  }
  const field = (key) => fields[key]
  const placeholder = (key, value) => setManualMandateValue(next.placeholders, key, value)
  const source = (key, value) => setManualMandateValue(next.sourceContext, key, value)
  const mandateDates = normalizeText(field('mandate_dates'))
  const [mandateStartDate, mandateEndDate] = mandateDates.includes(' to ')
    ? mandateDates.split(' to ').map(normalizeText)
    : [mandateDates, '']
  const commission = normalizeText(field('commission'))
  const commissionIsPercentage = commission.includes('%')

  setManualMandateValue(next.seller, 'fullName', field('seller_name'))
  setManualMandateValue(next.seller, 'email', field('seller_email'))
  setManualMandateValue(next.seller, 'phone', field('seller_phone'))
  setManualMandateValue(next.seller, 'entityType', field('seller_capacity'))
  setManualMandateValue(next.seller, 'maritalRegime', field('seller_marital'))
  placeholder('seller_full_name', field('seller_name'))
  placeholder('seller_email', field('seller_email'))
  placeholder('seller_phone', field('seller_phone'))
  placeholder('seller_entity_type', field('seller_capacity'))
  placeholder('seller_marital_regime', field('seller_marital'))
  source('sellerName', field('seller_name'))
  source('sellerEmail', field('seller_email'))
  source('sellerPhone', field('seller_phone'))

  setManualMandateValue(next.property, 'fullAddress', field('property_address'))
  setManualMandateValue(next.property, 'displayAddress', field('property_address'))
  setManualMandateValue(next.property, 'propertyType', field('property_type'))
  setManualMandateValue(next.property, 'propertyStructureType', field('property_title'))
  setManualMandateValue(next.property, 'titleType', field('property_title'))
  setManualMandateValue(next.property, 'erfNumber', field('property_reference'))
  setManualMandateValue(next.property, 'erfSize', field('property_size'))
  setManualMandateValue(next.property, 'askingPrice', field('asking_price'))
  placeholder('property_address', field('property_address'))
  placeholder('property_display_address', field('property_address'))
  placeholder('property_type', field('property_type'))
  placeholder('property_title_type', field('property_title'))
  placeholder('property_erf_number', field('property_reference'))
  placeholder('erf_number', field('property_reference'))
  placeholder('erf_size', field('property_size'))
  placeholder('property_asking_price', field('asking_price'))
  source('propertyAddress', field('property_address'))

  setManualMandateValue(next.mandate, 'askingPrice', field('asking_price'))
  setManualMandateValue(next.mandate, 'type', field('mandate_type'))
  setManualMandateValue(next.mandate, 'mandateType', field('mandate_type'))
  setManualMandateValue(next.mandate, 'startDate', mandateStartDate)
  setManualMandateValue(next.mandate, 'expiryDate', mandateEndDate)
  if (commission) {
    setManualMandateValue(next.mandate, 'commissionStructure', commissionIsPercentage ? 'percentage' : 'fixed')
    setManualMandateValue(next.mandate, commissionIsPercentage ? 'commissionPercentage' : 'commissionAmount', commission)
    setManualMandateValue(next.mandate, commissionIsPercentage ? 'commissionPercent' : 'commissionAmount', commission)
  }
  placeholder('asking_price', field('asking_price'))
  placeholder('mandate_type', field('mandate_type'))
  placeholder('mandate_start_date', mandateStartDate)
  placeholder('mandate_end_date', mandateEndDate)
  placeholder('commission_structure', commission ? (commissionIsPercentage ? 'Percentage' : 'Fixed') : '')
  placeholder(commissionIsPercentage ? 'mandate_commission_percent' : 'mandate_commission_amount', commission)
  placeholder(commissionIsPercentage ? 'commission_percentage' : 'commission_amount', commission)

  setManualMandateValue(next.transferAttorney, 'companyName', field('transfer_attorney'))
  placeholder('transfer_attorney_company_name', field('transfer_attorney'))
  setManualMandateValue(next.agent, 'fullName', field('agent'))
  placeholder('agent_full_name', field('agent'))
  setManualMandateValue(next.agency, 'name', field('agency'))
  placeholder('agency_name', field('agency'))
  placeholder('agency_display_name', field('agency'))
  source('manualRouteLabel', field('route'))
  source('manualRouteStatusLabel', field('route_status'))
  source('manualTemplateLabel', field('template'))
  source('manualTemplateKey', field('template_key'))
  next.transfer_attorney = next.transferAttorney
  next.sourceContext.mandateManualOverride = override
  return next
}

function getPreferredAttorneyInitials(attorney = {}) {
  const words = normalizeText(attorney.companyName || attorney.contactPerson || attorney.email).split(/\s+/).filter(Boolean)
  return words.slice(0, 2).map((word) => word[0]?.toUpperCase()).join('') || 'TA'
}

function mapConnectedAttorneyToPreferredAttorney(assignment = {}) {
  const partnerOrganisationId = normalizeText(assignment.partnerOrganisationId || assignment.partner_organisation_id || assignment.organisationId || assignment.organisation_id)
  const relationshipId = normalizeText(assignment.relationshipId || assignment.relationship_id || assignment.id)
  const companyName = normalizeText(assignment.organisationName || assignment.organisation_name || assignment.companyName || assignment.company_name || assignment.name || assignment.label)
  if (!partnerOrganisationId && !relationshipId && !companyName) return null
  return {
    id: relationshipId || partnerOrganisationId || companyName,
    preferredPartnerId: relationshipId || partnerOrganisationId,
    partnerOrganisationId,
    partnerType: 'transfer_attorney',
    companyName: companyName || 'Connected transfer attorney',
    contactPerson: normalizeText(assignment.contactPerson || assignment.contact_person || assignment.primaryContactName || assignment.primary_contact_name || assignment.email),
    email: normalizeText(assignment.email || assignment.primaryContactEmail || assignment.primary_contact_email),
    province: normalizeText(assignment.province || assignment.region),
    isPreferredDefault: assignment.isPreferredDefault === true || assignment.preferred === true,
  }
}

function getPreferredAttorneyDedupKey(attorney = {}) {
  const partnerOrganisationId = normalizeText(attorney.partnerOrganisationId)
  if (partnerOrganisationId) return `partner:${partnerOrganisationId}`
  const preferredPartnerId = normalizeText(attorney.preferredPartnerId)
  if (preferredPartnerId) return `preferred:${preferredPartnerId}`
  const email = normalizeText(attorney.email).toLowerCase()
  const companyName = normalizeText(attorney.companyName).toLowerCase()
  return `identity:${companyName}:${email || normalizeText(attorney.id)}`
}

function mergePreferredAttorneyOptions(primaryRows = [], fallbackRows = []) {
  const seen = new Set()
  const merged = []
  ;[...(Array.isArray(primaryRows) ? primaryRows : []), ...(Array.isArray(fallbackRows) ? fallbackRows : [])].forEach((attorney) => {
    const key = getPreferredAttorneyDedupKey(attorney)
    if (!key || seen.has(key)) return
    seen.add(key)
    merged.push(attorney)
  })
  return merged
}

function PreferredAttorneySelectionModal({
  open = false,
  attorneys = [],
  loading = false,
  error = '',
  selectedId = '',
  sending = false,
  onSelect,
  onClose,
  onConfirm,
}) {
  const selectedAttorney = attorneys.find((attorney) => String(attorney.id) === String(selectedId)) || null
  return (
    <Modal
      open={open}
      onClose={sending ? undefined : onClose}
      title="Choose the seller's transferring attorney"
      subtitle="Select the attorney before creating the onboarding link. The seller will see and accept this nomination during onboarding."
      className="max-w-2xl"
      footer={(
        <div className="flex flex-col-reverse gap-2 sm:flex-row sm:items-center sm:justify-end">
          <button type="button" onClick={onClose} disabled={sending} className="min-h-11 rounded-xl border border-slate-200 bg-white px-4 text-sm font-semibold text-slate-700 disabled:opacity-50">Cancel</button>
          <button
            type="button"
            onClick={() => onConfirm?.(selectedAttorney)}
            disabled={loading || sending || !selectedAttorney}
            className="inline-flex min-h-11 items-center justify-center gap-2 rounded-xl bg-slate-950 px-5 text-sm font-semibold text-white disabled:cursor-not-allowed disabled:bg-slate-300"
          >
            <Send size={15} />
            {sending ? 'Sending onboarding...' : 'Confirm attorney & send'}
          </button>
        </div>
      )}
    >
      {error ? <p className="mb-4 rounded-xl border border-rose-100 bg-rose-50 px-3 py-2 text-sm font-semibold text-rose-700">{error}</p> : null}
      {loading ? (
        <div className="grid gap-3">
          {[0, 1].map((item) => <div key={item} className="h-20 animate-pulse rounded-2xl bg-slate-100" />)}
        </div>
      ) : attorneys.length ? (
        <div className="grid max-h-[430px] gap-3 overflow-y-auto pr-1" role="radiogroup" aria-label="Preferred transferring attorneys">
          {attorneys.map((attorney) => {
            const selected = String(attorney.id) === String(selectedId)
            return (
              <button
                key={attorney.id}
                type="button"
                role="radio"
                aria-checked={selected}
                onClick={() => onSelect?.(attorney.id)}
                className={`flex w-full items-center gap-3 rounded-2xl border p-3 text-left transition ${selected ? 'border-blue-400 bg-blue-50 shadow-[0_8px_24px_rgba(37,99,235,0.08)]' : 'border-slate-200 bg-white hover:border-blue-200 hover:bg-slate-50'}`}
              >
                <span className="inline-flex h-12 w-12 shrink-0 items-center justify-center rounded-full border border-blue-100 bg-gradient-to-br from-blue-50 to-slate-100 text-xs font-bold tracking-wide text-blue-800">
                  {getPreferredAttorneyInitials(attorney)}
                </span>
                <span className="min-w-0 flex-1">
                  <span className="flex flex-wrap items-center gap-2">
                    <span className="truncate text-sm font-semibold text-slate-950">{attorney.companyName}</span>
                    {attorney.isPreferredDefault ? (
                      <span className="inline-flex items-center gap-1 rounded-full bg-amber-100 px-2 py-0.5 text-[0.65rem] font-bold uppercase tracking-wide text-amber-800">
                        <Star size={10} fill="currentColor" /> Agency preferred
                      </span>
                    ) : null}
                  </span>
                  <span className="mt-1 flex items-center gap-1.5 truncate text-xs text-slate-500">
                    <Building2 size={12} className="shrink-0" />
                    <span className="truncate">{attorney.contactPerson || attorney.email || attorney.province || 'Transfer attorney'}</span>
                  </span>
                </span>
                <span className={`inline-flex h-6 w-6 shrink-0 items-center justify-center rounded-full border ${selected ? 'border-blue-600 bg-blue-600 text-white' : 'border-slate-300 bg-white text-transparent'}`}>
                  <CheckCircle2 size={14} />
                </span>
              </button>
            )
          })}
        </div>
      ) : (
        <div className="rounded-2xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900">
          No active transfer attorneys are configured. Add one under Organisation / Partners before sending seller onboarding.
        </div>
      )}
    </Modal>
  )
}

function normalizeKey(value) {
  return normalizeText(value).toLowerCase()
}

function resolveMandatePacketStateHintFromLead(lead = {}) {
  const sourceContext =
    lead?.sourceContext && typeof lead.sourceContext === 'object'
      ? lead.sourceContext
      : lead?.source_context_json && typeof lead.source_context_json === 'object'
        ? lead.source_context_json
        : {}
  const mandatePacket = lead?.mandatePacket && typeof lead.mandatePacket === 'object' ? lead.mandatePacket : {}
  const packetId = normalizeText(lead?.mandatePacketId || lead?.mandate_packet_id || mandatePacket?.id)
  const leadLifecycleValues = [
    lead?.stage,
    lead?.status,
  ].map(normalizeKey)
  const mandateScopedValues = [
    lead?.mandateStatus,
    lead?.mandate_status,
    sourceContext?.mandateStatus,
    sourceContext?.mandate_status,
    sourceContext?.signingStatus,
    sourceContext?.signing_status,
    mandatePacket?.status,
    mandatePacket?.state,
  ].map(normalizeKey)
  const values = [...mandateScopedValues, ...leadLifecycleValues]

  if (
    mandateScopedValues.some((value) => ['completed', 'complete', 'signed', 'mandate signed', 'mandate_signed'].includes(value)) ||
    leadLifecycleValues.some((value) =>
      [
        'mandate complete',
        'mandate_complete',
        'mandate signed',
        'mandate_signed',
        'listing live',
        'listing_live',
        'listing active',
        'listing_active',
      ].includes(value),
    )
  ) return 'completed'
  if (values.some((value) => ['finalising', 'finalizing'].includes(value))) return 'finalising'
  if (values.some((value) => ['partially_signed', 'partially signed'].includes(value))) return 'partially_signed'
  if (
    normalizeText(lead?.mandateSentAt || lead?.mandate_sent_at || lead?.mandateSigningLink || lead?.mandateSignerLink) ||
    mandateScopedValues.some((value) =>
      [
        'sent',
        'mandate sent',
        'mandate_sent',
        'sent for signature',
        'sent_for_signature',
        'sent to seller',
        'sent_to_seller',
        'ready for client signature',
        'ready_for_client_signature',
        'seller signature requested',
        'seller_signature_requested',
        'awaiting seller signature',
        'awaiting_seller_signature',
      ].includes(value),
    ) ||
    leadLifecycleValues.some((value) =>
      [
        'mandate sent',
        'mandate_sent',
        'sent for signature',
        'sent_for_signature',
        'sent to seller',
        'sent_to_seller',
        'seller signature requested',
        'seller_signature_requested',
        'awaiting seller signature',
        'awaiting_seller_signature',
      ].includes(value),
    )
  ) {
    return 'sent'
  }
  if (values.some((value) => ['ready_to_send', 'ready to send'].includes(value))) return 'ready_to_send'
  if (values.some((value) => ['pdf_generated', 'generated', 'mandate generated', 'mandate_generated'].includes(value))) return 'pdf_generated'
  if (
    packetId ||
    values.some((value) =>
      [
        'draft',
        'mandate draft',
        'mandate_draft',
        'draft ready',
        'draft_ready',
        'mandate draft ready',
        'mandate_draft_ready',
      ].includes(value),
    )
  ) {
    return 'draft'
  }
  return ''
}

function getMandateStatePriority(value) {
  const state = normalizeKey(value)
  if (['completed', 'complete', 'signed', 'mandate complete', 'mandate_complete', 'mandate signed', 'mandate_signed', 'fully_signed', 'uploaded_signed', 'listing live', 'listing_live', 'listing active', 'listing_active'].includes(state)) return 60
  if (['publishing', 'finalising', 'finalizing'].includes(state)) return 55
  if (['partially_signed', 'partially signed', 'agent_signed', 'seller_signed'].includes(state)) return 50
  if (
    [
      'sent',
      'mandate sent',
      'mandate_sent',
      'sent for signature',
      'sent_for_signature',
      'sent to seller',
      'sent_to_seller',
      'ready for client signature',
      'ready_for_client_signature',
      'seller signature requested',
      'seller_signature_requested',
      'awaiting seller signature',
      'awaiting_seller_signature',
    ].includes(state)
  ) return 40
  if (['ready_to_send', 'ready to send', 'signing_prep', 'signing prepared'].includes(state)) return 30
  if (['pdf_generated', 'generated', 'mandate generated', 'mandate_generated'].includes(state)) return 20
  if (['draft', 'mandate draft', 'mandate_draft', 'draft ready', 'draft_ready', 'mandate draft ready', 'mandate_draft_ready'].includes(state)) return 10
  if (['no_packet', 'unknown'].includes(state)) return 0
  return state ? 5 : 0
}

function isMandatePreSendPacketState(value = '') {
  const state = normalizeKey(value)
  return [
    'draft',
    'mandate_draft',
    'draft_ready',
    'mandate_draft_ready',
    'generated',
    'pdf_generated',
    'mandate_generated',
    'ready_to_send',
    'ready',
    'signing_prep',
    'signing_prepared',
  ].includes(state)
}

function hasConfirmedMandateSendJob(job = null) {
  if (!job || typeof job !== 'object') return false
  const jobType = normalizeKey(job?.jobType || job?.job_type || job?.type)
  if (jobType !== 'send_for_signature') return false
  const status = normalizeKey(job?.status || job?.jobStatus || job?.job_status)
  const result = job?.result && typeof job.result === 'object' ? job.result : {}
  const metadata = job?.metadata && typeof job.metadata === 'object' ? job.metadata : {}
  const delivery = result?.delivery && typeof result.delivery === 'object'
    ? result.delivery
    : metadata?.delivery && typeof metadata.delivery === 'object'
      ? metadata.delivery
      : {}
  const deliveryStatus = normalizeKey(delivery?.status || result?.deliveryStatus || metadata?.deliveryStatus)
  return Boolean(
    ['succeeded', 'success', 'completed', 'complete', 'sent', 'delivered'].includes(status) &&
      (
        result?.emailConfirmed === true ||
        metadata?.emailConfirmed === true ||
        normalizeText(result?.emailId || result?.deliveryId || metadata?.emailId || metadata?.deliveryId || delivery?.id || delivery?.providerMessageId || delivery?.provider_message_id) ||
        ['sent', 'delivered', 'accepted', 'queued'].includes(deliveryStatus)
      ),
  )
}

function hasMandateSignerDeliveryEvidence(signer = null) {
  if (!signer || typeof signer !== 'object') return false
  const status = normalizeKey(signer?.status || signer?.statusRaw)
  return Boolean(
    ['sent', 'viewed', 'signed', 'completed', 'complete'].includes(status) ||
      normalizeText(signer?.sent_at || signer?.sentAt || signer?.viewed_at || signer?.viewedAt || signer?.signed_at || signer?.signedAt || signer?.token_used_at || signer?.tokenUsedAt),
  )
}

function hasExplicitMandateSentEvidence({ lead = {}, mandatePacketStatus = null } = {}) {
  const packet = mandatePacketStatus?.packet && typeof mandatePacketStatus.packet === 'object'
    ? mandatePacketStatus.packet
    : {}
  const leadSourceContext = lead?.sourceContext && typeof lead.sourceContext === 'object'
    ? lead.sourceContext
    : lead?.source_context_json && typeof lead.source_context_json === 'object'
      ? lead.source_context_json
      : {}
  const sourceContext = packet.source_context_json && typeof packet.source_context_json === 'object'
    ? packet.source_context_json
    : {}
  const signers = Array.isArray(mandatePacketStatus?.signingSummary?.signers)
    ? mandatePacketStatus.signingSummary.signers
    : Array.isArray(mandatePacketStatus?.signers)
      ? mandatePacketStatus.signers
      : []
  return Boolean(
    normalizeText(
      lead?.mandateSentAt ||
        lead?.mandate_sent_at ||
        lead?.mandateSigningLink ||
        lead?.mandateSignerLink ||
        leadSourceContext?.emailDeliveryId ||
        leadSourceContext?.email_delivery_id ||
        leadSourceContext?.deliveryId ||
        leadSourceContext?.delivery_id ||
        leadSourceContext?.mandateSentAt ||
        leadSourceContext?.mandate_sent_at ||
        leadSourceContext?.mandateSigningLink ||
        leadSourceContext?.mandate_signing_link ||
        sourceContext?.emailDeliveryId ||
        sourceContext?.email_delivery_id ||
        sourceContext?.deliveryId ||
        sourceContext?.delivery_id ||
        sourceContext?.mandateSentAt ||
        sourceContext?.mandate_sent_at ||
        sourceContext?.mandateSigningLink ||
        sourceContext?.mandate_signing_link ||
        packet?.sentAt ||
        packet?.sent_at ||
        packet?.completedAt ||
        packet?.completed_at,
    ) ||
      hasConfirmedMandateSendJob(mandatePacketStatus?.legalDocumentJob) ||
      signers.some(hasMandateSignerDeliveryEvidence),
  )
}

function hasMandateDeliveredOrSignedEvidence({ lead = {}, mandatePacketStatus = null } = {}) {
  const leadHint = resolveMandatePacketStateHintFromLead(lead)
  const packet = mandatePacketStatus?.packet && typeof mandatePacketStatus.packet === 'object'
    ? mandatePacketStatus.packet
    : {}
  const explicitSentEvidence = hasExplicitMandateSentEvidence({ lead, mandatePacketStatus })
  if (isMandatePreSendPacketState(mandatePacketStatus?.state || packet?.status) && !explicitSentEvidence) return false
  const values = [
    leadHint,
    mandatePacketStatus?.state,
    mandatePacketStatus?.signingStatus,
    packet?.status,
    packet?.state,
  ]
  return values.some((value) => getMandateStatePriority(value) >= 50) ||
    explicitSentEvidence
}

function isStaleMandateGenerationRecoveryMessage(value = '') {
  const message = normalizeText(value).toLowerCase()
  if (!message) return false
  return (
    message.includes('could not confirm a usable mandate draft') ||
    message.includes('select generate once more') ||
    message.includes('mandate generation failed') ||
    message.includes('mandate pdf was not saved as a generated packet version')
  )
}

const BUYER_ONBOARDING_OTP_WORKSPACE_TAB_KEY = 'onboarding_otp'
const SELLER_LEAD_WORKSPACE_TAB_KEYS = new Set(['overview', 'seller', 'property', 'mandate', 'appointments', 'documents', 'activity'])
const BUYER_LEAD_WORKSPACE_TAB_KEYS = new Set(['overview', 'properties', 'appointments', 'activity', BUYER_ONBOARDING_OTP_WORKSPACE_TAB_KEY])

function normalizeLeadWorkspaceTabKey(tabKey = '') {
  const normalized = normalizeKey(tabKey)
  if (['offer', 'offers', 'otp', 'onboarding', 'onboarding_otp', 'buyer_onboarding', 'buyer_onboarding_otp'].includes(normalized)) {
    return BUYER_ONBOARDING_OTP_WORKSPACE_TAB_KEY
  }
  if (normalized === 'activities') return 'activity'
  if (normalized === 'listing_journey') return 'overview'
  return normalized
}

function resolveLeadWorkspaceTabFromSearch(search = '') {
  if (!search) return 'overview'
  const params = new URLSearchParams(search)
  const requestedTab = normalizeLeadWorkspaceTabKey(params.get('tab') || params.get('sellerWorkspace') || '')
  if (SELLER_LEAD_WORKSPACE_TAB_KEYS.has(requestedTab) || BUYER_LEAD_WORKSPACE_TAB_KEYS.has(requestedTab)) {
    return requestedTab
  }
  return 'overview'
}

function replaceLeadWorkspaceTabInUrl(tab = '') {
  if (typeof window === 'undefined') return
  const nextTab = normalizeLeadWorkspaceTabKey(tab) || 'overview'
  const nextUrl = new URL(window.location.href)
  nextUrl.searchParams.set('tab', nextTab)
  nextUrl.searchParams.delete('sellerWorkspace')
  window.history.replaceState(window.history.state, '', `${nextUrl.pathname}${nextUrl.search}${nextUrl.hash}`)
}

