const KINGSTONS_STALE_BASELINE_DOCUMENT_KEYS = new Set([
  'seller_contact_confirmation',
  'seller_onboarding_submission',
])

function getSellerLeadDocumentCategoryKey(documentRow = {}) {
  const source = normalizeKey([
    documentRow?.category,
    documentRow?.categoryKey,
    documentRow?.documentCategory,
    documentRow?.document_category,
    documentRow?.group,
    documentRow?.requirement_group,
    documentRow?.requirementLane,
    documentRow?.requirement_lane,
    documentRow?.documentRequirementSection,
    documentRow?.document_requirement_section,
    documentRow?.partyRole,
    documentRow?.party_role,
    documentRow?.type,
    documentRow?.documentType,
    documentRow?.document_type,
    documentRow?.key,
    documentRow?.id,
    documentRow?.requirementKey,
    documentRow?.requirement_key,
    documentRow?.label,
    documentRow?.title,
  ].filter(Boolean).join(' '))

  if (/(seller_identity_fica|owner_fica|director_fica|trustee_fica|member_fica|spouse_fica)/.test(source)) return 'seller'
  if (/(authority_documents|resolution_to_sell|company_resolution|close_corporation_resolution|trust_resolution|letters_of_authority|trust_deed|spouse_consent|owner_authority_consent|all_owner_authority_consent|resolution|authority|consent)/.test(source)) return 'legal'
  if (/(marketing|asset|photo|image|gallery|brochure|floor|plan|media|campaign|listing_photo|property_photo)/.test(source)) return 'marketing'
  if (/(legal|mandate|otp|offer|agreement|contract|signature|signed|transfer|attorney|conveyancer)/.test(source)) return 'legal'
  if (/(property|valuation|appraisal|title|deed|rates|levy|hoa|body|corporate|condition|disclosure|certificate|coc|occupancy|municipal|ownership)/.test(source)) return 'property'
  return 'seller'
}

function isStaleKingstonsBaselineDocumentRow(documentRow = {}) {
  return KINGSTONS_STALE_BASELINE_DOCUMENT_KEYS.has(getSellerLeadDocumentCanonicalKey(documentRow))
}

function getSellerLeadDocumentStatusMeta(documentRow = {}) {
  const rawStatus = normalizeText(documentRow?.statusLabel || documentRow?.status || documentRow?.documentStatus || documentRow?.document_status)
  const status = normalizeKey(rawStatus)
  const hasFile = Boolean(
    documentRow?.url ||
      documentRow?.fileUrl ||
      documentRow?.file_url ||
      documentRow?.downloadUrl ||
      documentRow?.download_url ||
      documentRow?.storagePath ||
      documentRow?.storage_path ||
      documentRow?.filePath ||
      documentRow?.file_path ||
      documentRow?.generatedHtml ||
      documentRow?.generated_html ||
      documentRow?.uploadedAt ||
      documentRow?.uploaded_at,
  )

  if (/(rejected|declined|failed|invalid)/.test(status)) {
    return {
      state: 'danger',
      label: rawStatus || 'Needs attention',
      pillClass: 'border-[#f2c9c4] bg-[#fff5f4] text-[#9f3028]',
      iconClass: 'bg-[#fff5f4] text-[#9f3028]',
      Icon: AlertTriangle,
    }
  }
  if (/(approved|complete|completed|signed|verified|accepted|done)/.test(status)) {
    return {
      state: 'complete',
      label: rawStatus || 'Complete',
      pillClass: 'border-[#c8e7d4] bg-[#effaf3] text-[#1d7a52]',
      iconClass: 'bg-[#effaf3] text-[#1d7a52]',
      Icon: CheckCircle2,
    }
  }
  if (/(review|submitted|received|uploaded|processing)/.test(status) || hasFile) {
    return {
      state: 'review',
      label: rawStatus || 'Uploaded',
      pillClass: 'border-[#f0d9ab] bg-[#fff8e8] text-[#8a641d]',
      iconClass: 'bg-[#fff8e8] text-[#8a641d]',
      Icon: Clock3,
    }
  }
  return {
    state: 'pending',
    label: rawStatus || 'Pending',
    pillClass: 'border-[#dfe8f1] bg-[#f3f7fb] text-[#7890a8]',
    iconClass: 'bg-[#f3f7fb] text-[#7890a8]',
    Icon: FileText,
  }
}

function getSellerLeadDocumentCanonicalLabel(row = {}) {
  const key = normalizeKey(row?.key || row?.requirementKey || row?.requirement_key)
  if (key === 'signed_mandate') return 'Signed Mandate'
  if (key === 'signed_defect_form') return 'Signed Defect Form'
  if (key === 'signed_fica_form') return 'Signed FICA Form'
  if (key === 'property_condition_disclosure') return 'Seller Declaration / Disclosure'
  return row?.label || row?.title || row?.document_name || row?.name || 'Seller document'
}

function getSellerLeadDocumentCanonicalKey(row = {}) {
  const source = normalizeKey([
    row?.key,
    row?.requirementKey,
    row?.requirement_key,
    row?.documentType,
    row?.document_type,
    row?.document_category,
    row?.category,
    row?.label,
    row?.title,
    row?.document_name,
    row?.name,
  ].filter(Boolean).join(' '))
  if (source.includes('signed_mandate') || source.includes('mandate_signature') || (source.includes('signed') && source.includes('mandate'))) return 'signed_mandate'
  if (source.includes('signed_defect_form') || source.includes('defect_form') || (source.includes('signed') && source.includes('defect'))) return 'signed_defect_form'
  if (source.includes('signed_fica_form') || source.includes('fica_form') || (source.includes('signed') && source.includes('fica'))) return 'signed_fica_form'
  if (
    source.includes('valuation_document') ||
    source.includes('formal_valuation') ||
    (source.includes('valuation') && source.includes('document')) ||
    (source.includes('valuation') && source.includes('uploaded'))
  ) return 'valuation_document'
  if (
    source.includes('property_condition_disclosure') ||
    source.includes('condition_disclosure') ||
    source.includes('seller_declaration') ||
    source.includes('seller_disclosure') ||
    (source.includes('disclosure') && (source.includes('property') || source.includes('seller')))
  ) return 'property_condition_disclosure'
  return normalizeKey(row?.key || row?.requirementKey || row?.requirement_key || row?.label || row?.title || row?.id)
}

function getSellerLeadDocumentStatusRank(status = '') {
  const normalized = normalizeKey(status)
  if (/(approved|complete|completed|signed|verified|accepted|done|fully_signed)/.test(normalized)) return 5
  if (/(review|submitted|received|uploaded|processing)/.test(normalized)) return 4
  if (/(rejected|declined|failed|invalid)/.test(normalized)) return 3
  if (/(required|requested|pending|missing|outstanding)/.test(normalized)) return 1
  return normalized ? 2 : 0
}

function sellerLeadDocumentHasFileEvidence(row = {}) {
  return Boolean(
    row?.url ||
      row?.fileUrl ||
      row?.file_url ||
      row?.downloadUrl ||
      row?.download_url ||
      row?.storagePath ||
      row?.storage_path ||
      row?.filePath ||
      row?.file_path ||
      row?.generatedHtml ||
      row?.generated_html ||
      row?.uploadedAt ||
      row?.uploaded_at,
  )
}

function mergeSellerLeadDocumentRows(existing = {}, incoming = {}) {
  const existingRequired = existing.required !== false
  const incomingRequired = incoming.required !== false
  const existingStatusRank = getSellerLeadDocumentStatusRank(existing.status || existing.statusLabel)
  const incomingStatusRank = getSellerLeadDocumentStatusRank(incoming.status || incoming.statusLabel)
  const existingHasFile = sellerLeadDocumentHasFileEvidence(existing)
  const incomingHasFile = sellerLeadDocumentHasFileEvidence(incoming)
  const incomingIsStronger =
    incomingStatusRank > existingStatusRank ||
    (incomingStatusRank === existingStatusRank && incomingHasFile && !existingHasFile)
  const base = incomingIsStronger ? incoming : existing
  const overlay = base === existing ? incoming : existing
  const statusSource = incomingStatusRank > existingStatusRank ? incoming : existing
  const url = firstWorkspaceText(
    incoming.url,
    incoming.fileUrl,
    incoming.file_url,
    incoming.downloadUrl,
    incoming.download_url,
    existing.url,
    existing.fileUrl,
    existing.file_url,
    existing.downloadUrl,
    existing.download_url,
  )
  const storagePath = firstWorkspaceText(incoming.storagePath, incoming.storage_path, incoming.filePath, incoming.file_path, existing.storagePath, existing.storage_path, existing.filePath, existing.file_path)
  const storageBucket = firstWorkspaceText(incoming.storageBucket, incoming.storage_bucket, existing.storageBucket, existing.storage_bucket)
  const generatedHtml = firstWorkspaceText(incoming.generatedHtml, incoming.generated_html, existing.generatedHtml, existing.generated_html)
  const generatedFileName = firstWorkspaceText(incoming.generatedFileName, incoming.generated_file_name, existing.generatedFileName, existing.generated_file_name)
  const uploadedAt = firstWorkspaceText(incoming.uploadedAt, incoming.uploaded_at, existing.uploadedAt, existing.uploaded_at)
  const uploadedBy = firstWorkspaceText(incoming.uploadedBy, incoming.uploaded_by, existing.uploadedBy, existing.uploaded_by)
  const packetId = firstWorkspaceText(incoming.packetId, incoming.packet_id, existing.packetId, existing.packet_id)
  const packetVersionId = firstWorkspaceText(incoming.packetVersionId, incoming.packet_version_id, existing.packetVersionId, existing.packet_version_id)
  const canonicalKey = getSellerLeadDocumentCanonicalKey(base) || getSellerLeadDocumentCanonicalKey(overlay)
  const canonicalLabel = canonicalKey === 'signed_mandate'
    ? 'Signed Mandate'
    : canonicalKey === 'signed_defect_form'
      ? 'Signed Defect Form'
      : canonicalKey === 'signed_fica_form'
        ? 'Signed FICA Form'
    : canonicalKey === 'property_condition_disclosure'
      ? 'Seller Declaration / Disclosure'
      : base.label || base.title || overlay.label || overlay.title

  return {
    ...overlay,
    ...base,
    id: base.id || overlay.id,
    key: canonicalKey || base.key || overlay.key,
    requirementKey: canonicalKey || base.requirementKey || overlay.requirementKey,
    requirement_key: canonicalKey || base.requirement_key || overlay.requirement_key,
    title: canonicalLabel,
    label: canonicalLabel,
    required: existingRequired || incomingRequired,
    status: statusSource.status || statusSource.statusLabel || base.status,
    statusLabel: statusSource.statusLabel || statusSource.status || base.statusLabel,
    url,
    fileUrl: url,
    file_url: url,
    downloadUrl: url,
    download_url: url,
    storagePath,
    storage_path: storagePath,
    storageBucket,
    storage_bucket: storageBucket,
    generatedHtml,
    generated_html: generatedHtml,
    generatedFileName,
    generated_file_name: generatedFileName,
    uploadedFileName: firstWorkspaceText(incoming.uploadedFileName, existing.uploadedFileName, generatedFileName),
    uploaded_file_name: firstWorkspaceText(incoming.uploaded_file_name, incoming.uploadedFileName, existing.uploaded_file_name, existing.uploadedFileName, generatedFileName),
    uploadedAt,
    uploaded_at: uploadedAt,
    uploadedBy,
    uploaded_by: uploadedBy,
    packetId,
    packet_id: packetId,
    packetVersionId,
    packet_version_id: packetVersionId,
    canonicalFinalArtifact: Boolean(
      canonicalKey === 'signed_mandate' &&
        packetId &&
        packetVersionId &&
        (incoming.canonicalFinalArtifact || existing.canonicalFinalArtifact || !url),
    ),
  }
}

function dedupeSellerLeadDocumentRows(rows = []) {
  const mergedRows = []
  const indexByKey = new Map()
  for (const row of Array.isArray(rows) ? rows : []) {
    if (!row || typeof row !== 'object') continue
    const key = getSellerLeadDocumentCanonicalKey(row) || normalizeKey(row.id || row.label || row.title)
    if (!key) {
      mergedRows.push(row)
      continue
    }
    if (!indexByKey.has(key)) {
      indexByKey.set(key, mergedRows.length)
      mergedRows.push(row)
      continue
    }
    const index = indexByKey.get(key)
    mergedRows[index] = mergeSellerLeadDocumentRows(mergedRows[index], row)
  }
  return mergedRows
}

function buildSellerLeadMandatePacketForDocuments({
  mandatePacketStatus = null,
  lead = {},
  listing = null,
} = {}) {
  const listingRecord = listing && typeof listing === 'object' ? listing : {}
  const packet = mandatePacketStatus?.packet || lead?.mandatePacket || lead?.mandate_packet || listingRecord?.mandatePacket || listingRecord?.mandate_packet || listingRecord?.mandate || {}
  const versions = Array.isArray(mandatePacketStatus?.versions) ? mandatePacketStatus.versions : []
  const latestVersion = versions.find((version) =>
    normalizeText(version?.final_signed_file_path || version?.final_signed_file_url || version?.final_signed_file_access_url),
  ) || versions[0] || packet?.version || {}
  const sourceContext = packet?.source_context_json && typeof packet.source_context_json === 'object' ? packet.source_context_json : {}
  const finalSignedFilePath = firstWorkspaceText(
    latestVersion?.final_signed_file_path,
    latestVersion?.finalSignedFilePath,
    packet?.finalSignedFilePath,
    packet?.final_signed_file_path,
    listingRecord?.mandate?.finalSignedFilePath,
    listingRecord?.mandate?.final_signed_file_path,
    lead?.mandateSignedDocumentPath,
    lead?.mandate_signed_document_path,
    sourceContext?.finalSignedFilePath,
    sourceContext?.final_signed_file_path,
  )
  const finalSignedFileUrl = firstWorkspaceText(
    latestVersion?.final_signed_file_access_url,
    latestVersion?.final_signed_file_url,
    latestVersion?.finalSignedFileAccessUrl,
    latestVersion?.finalSignedFileUrl,
    packet?.finalSignedDownloadUrl,
    packet?.finalSignedFileAccessUrl,
    packet?.finalSignedFileUrl,
    packet?.final_signed_file_access_url,
    packet?.final_signed_file_url,
    listingRecord?.mandate?.finalSignedDownloadUrl,
    listingRecord?.mandate?.finalSignedFileAccessUrl,
    listingRecord?.mandate?.finalSignedFileUrl,
    listingRecord?.mandate?.final_signed_file_access_url,
    listingRecord?.mandate?.final_signed_file_url,
    lead?.mandateSignedDocumentUrl,
    lead?.mandate_signed_document_url,
    sourceContext?.finalSignedDownloadUrl,
    sourceContext?.finalSignedFileAccessUrl,
    sourceContext?.finalSignedFileUrl,
    sourceContext?.final_signed_file_access_url,
    sourceContext?.final_signed_file_url,
  )
  const finalSignedFileName = firstWorkspaceText(
    latestVersion?.final_signed_file_name,
    latestVersion?.finalSignedFileName,
    packet?.finalSignedFileName,
    packet?.final_signed_file_name,
    'Signed Mandate.pdf',
  )
  const versionId = firstWorkspaceText(
    latestVersion?.id,
    latestVersion?.versionId,
    latestVersion?.version_id,
    packet?.packetVersionId,
    packet?.packet_version_id,
  )
  const status = normalizeKey(
    mandatePacketStatus?.state ||
      mandatePacketStatus?.signingStatus ||
      packet?.status ||
      packet?.state ||
      packet?.packet?.status ||
      lead?.mandateStatus ||
      lead?.mandate_status ||
      listingRecord?.mandateStatus ||
      listingRecord?.mandate_status,
  )
  const signedStates = ['signed', 'completed', 'complete', 'fully_signed', 'uploaded_signed', 'signed_uploaded', 'finalised', 'finalized']
  const signed = signedStates.includes(status) || Boolean(finalSignedFilePath || finalSignedFileUrl)
  const finalSignedRecorded = Boolean(
    finalSignedFilePath ||
      finalSignedFileUrl ||
      latestVersion?.final_signed_document_id ||
      latestVersion?.finalSignedDocumentId ||
      packet?.finalSignedRecorded ||
      packet?.final_signed_recorded,
  )
  const packetId = firstWorkspaceText(
    packet?.id,
    packet?.packetId,
    packet?.packet_id,
    packet?.packet?.id,
    lead?.mandatePacketId,
    lead?.mandate_packet_id,
    listingRecord?.mandatePacketId,
    listingRecord?.mandate_packet_id,
  )

  if (!packetId && !finalSignedRecorded) return null

  return {
    ...packet,
    id: packetId,
    state: signed ? 'fully_signed' : status,
    status: signed ? 'fully_signed' : status,
    packet: {
      ...(packet?.packet || {}),
      id: packetId,
      status: signed ? 'fully_signed' : status,
    },
    version: {
      ...latestVersion,
      id: versionId,
      final_signed_file_path: finalSignedFilePath,
      final_signed_file_url: finalSignedFileUrl,
      final_signed_file_access_url: finalSignedFileUrl,
      final_signed_file_name: finalSignedFileName,
      final_signed_file_bucket: firstWorkspaceText(latestVersion?.final_signed_file_bucket, latestVersion?.finalSignedFileBucket, packet?.finalSignedFileBucket, packet?.final_signed_file_bucket),
      finalised_at: firstWorkspaceText(latestVersion?.finalised_at, latestVersion?.finalized_at, packet?.finalised_at, packet?.finalized_at),
    },
    finalSignedRecorded,
    final_signed_recorded: finalSignedRecorded,
    finalSignedFilePath: finalSignedFilePath,
    final_signed_file_path: finalSignedFilePath,
    finalSignedDownloadUrl: finalSignedFileUrl,
    final_signed_file_url: finalSignedFileUrl,
    finalSignedFileName: finalSignedFileName,
    final_signed_file_name: finalSignedFileName,
  }
}

function mapSellerLeadDocumentSourceRow(row = {}) {
  const upload = row?.upload || {}
  const originalDocument = row?.original?.document || {}
  const key = normalizeText(row?.key || row?.requirementKey || row?.requirement_key || row?.id)
  const label = getSellerLeadDocumentCanonicalLabel(row)
  const category = normalizeKey(row?.category) === 'sales' ? 'legal' : row?.category
  const url = firstWorkspaceText(
    upload.url,
    row.url,
    row.documentUrl,
    originalDocument.url,
    originalDocument.fileUrl,
    originalDocument.file_url,
    originalDocument.downloadUrl,
    originalDocument.download_url,
    originalDocument.signedUrl,
    originalDocument.signed_url,
  )
  const generatedHtml = firstWorkspaceText(upload.generatedHtml, row.generatedHtml, row.generated_html, originalDocument.generatedHtml, originalDocument.generated_html)
  const generatedFileName = firstWorkspaceText(upload.generatedFileName, row.generatedFileName, row.generated_file_name, originalDocument.generatedFileName, originalDocument.generated_file_name)
  const status = normalizeText(row?.status || (row?.complete ? 'completed' : 'required'))
  const packetId = firstWorkspaceText(row?.packetId, row?.packet_id, upload.packetId, upload.packet_id, originalDocument.packetId, originalDocument.packet_id)
  const packetVersionId = firstWorkspaceText(row?.packetVersionId, row?.packet_version_id, upload.packetVersionId, upload.packet_version_id, originalDocument.packetVersionId, originalDocument.packet_version_id)
  const canonicalKey = getSellerLeadDocumentCanonicalKey({ ...row, key, label })

  return {
    ...row,
    id: normalizeText(row?.id) || key || label,
    key: canonicalKey || key,
    requirementKey: canonicalKey || key,
    requirement_key: canonicalKey || key,
    title: label,
    label,
    category,
    document_category: category,
    status,
    statusLabel: row?.statusLabel || status,
    url,
    fileUrl: url,
    file_url: url,
    downloadUrl: url,
    download_url: url,
    uploadedAt: firstWorkspaceText(upload.uploadedAt, row.uploadedAt, originalDocument.uploadedAt, originalDocument.uploaded_at),
    uploaded_at: firstWorkspaceText(upload.uploadedAt, row.uploadedAt, originalDocument.uploadedAt, originalDocument.uploaded_at),
    generatedHtml,
    generated_html: generatedHtml,
    generatedFileName,
    generated_file_name: generatedFileName,
    uploadedFileName: firstWorkspaceText(upload.fileName, row.uploadedFileName, originalDocument.fileName, originalDocument.file_name, originalDocument.document_name, generatedFileName),
    packetId,
    packet_id: packetId,
    packetVersionId,
    packet_version_id: packetVersionId,
    canonicalFinalArtifact: Boolean(canonicalKey === 'signed_mandate' && packetId && packetVersionId && !url),
    originalDocument,
  }
}

function buildSellerLeadDocumentRowsFromSource({
  lead = {},
  listing = null,
  journey = null,
  mandatePacketStatus = null,
} = {}) {
  const listingRecord = listing && typeof listing === 'object' ? listing : {}
  const leadRecord = lead && typeof lead === 'object' ? lead : {}
  const formData = {
    ...getListingSellerFormData(listingRecord),
    ...getLeadSellerOnboardingFormData(leadRecord),
  }
  const documents = [
    ...(Array.isArray(listingRecord?.documents) ? listingRecord.documents : []),
    ...(Array.isArray(journey?.documents) ? journey.documents.map((document) => document?.original?.document || document).filter(Boolean) : []),
  ]
  const sourceListing = {
    ...leadRecord,
    ...listingRecord,
    id: firstWorkspaceText(listingRecord?.id, listingRecord?.private_listing_id, leadRecord?.listingId, leadRecord?.listing_id),
    private_listing_id: firstWorkspaceText(listingRecord?.private_listing_id, listingRecord?.id, leadRecord?.listingId, leadRecord?.listing_id),
    sellerLeadId: firstWorkspaceText(listingRecord?.sellerLeadId, listingRecord?.seller_lead_id, leadRecord?.leadId, leadRecord?.id),
    seller_lead_id: firstWorkspaceText(listingRecord?.seller_lead_id, listingRecord?.sellerLeadId, leadRecord?.leadId, leadRecord?.id),
    documentRequirements: Array.isArray(listingRecord?.documentRequirements)
      ? listingRecord.documentRequirements
      : Array.isArray(leadRecord?.documentRequirements)
        ? leadRecord.documentRequirements
        : [],
    documents,
    sellerOnboarding: {
      ...(isPlainObject(leadRecord?.sellerOnboarding) ? leadRecord.sellerOnboarding : {}),
      ...(isPlainObject(listingRecord?.sellerOnboarding) ? listingRecord.sellerOnboarding : {}),
      status: firstWorkspaceText(listingRecord?.sellerOnboardingStatus, listingRecord?.seller_onboarding_status, leadRecord?.sellerOnboardingStatus, leadRecord?.seller_onboarding_status),
      formData,
      form_data: formData,
    },
    seller_onboarding: {
      ...(isPlainObject(leadRecord?.seller_onboarding) ? leadRecord.seller_onboarding : {}),
      ...(isPlainObject(listingRecord?.seller_onboarding) ? listingRecord.seller_onboarding : {}),
      status: firstWorkspaceText(listingRecord?.sellerOnboardingStatus, listingRecord?.seller_onboarding_status, leadRecord?.sellerOnboardingStatus, leadRecord?.seller_onboarding_status),
      formData,
      form_data: formData,
    },
  }
  const source = buildSellerDocumentSourceOfTruth({
    listing: sourceListing,
    documents,
    formData,
    mandatePacket: buildSellerLeadMandatePacketForDocuments({ mandatePacketStatus, lead: leadRecord, listing: listingRecord }),
  })

  return dedupeSellerLeadDocumentRows(source.rows.map(mapSellerLeadDocumentSourceRow))
}

function openSellerLeadGeneratedDocumentHtml(markup = '', fileName = 'seller-document.html') {
  if (typeof window === 'undefined' || typeof URL === 'undefined' || typeof Blob === 'undefined') return
  const html = String(markup || '').trim()
  if (!html) return
  const targetWindow = window.open('about:blank', '_blank')
  if (!targetWindow) return
  const documentTitle = normalizeText(fileName).replace(/[-_]+/g, ' ').replace(/\.(html?|pdf)$/i, '').trim() || 'Seller document'
  const htmlWithTitle = html.replace(
    /<\/body>\s*<\/html>\s*$/i,
    `<script>window.addEventListener('load',function(){document.title=${JSON.stringify(documentTitle)}})</script></body></html>`,
  )
  const blob = new Blob([htmlWithTitle || html], { type: 'text/html;charset=utf-8' })
  const url = URL.createObjectURL(blob)
  targetWindow.location.href = url
  window.setTimeout(() => URL.revokeObjectURL(url), 60 * 1000)
}

function sanitizeSellerLeadDownloadFileName(value = '', fallback = 'seller-document.pdf') {
  const normalized = normalizeText(value)
    .replace(/[\\/:*?"<>|]+/g, '-')
    .replace(/\s+/g, ' ')
    .trim()
  return normalized || fallback
}

function toSellerLeadPdfFileName(value = '', fallback = 'seller-document.pdf') {
  const raw = sanitizeSellerLeadDownloadFileName(value || fallback, fallback)
  return raw.replace(/\.(html?|pdf)$/i, '') + '.pdf'
}

async function triggerSellerLeadBrowserDownload(url = '', fileName = 'seller-document.pdf') {
  const downloadUrl = normalizeText(url)
  if (!downloadUrl) throw new Error('The download link is not available yet.')
  if (typeof document === 'undefined') return

  const safeFileName = sanitizeSellerLeadDownloadFileName(fileName)
  let objectUrl = ''
  let href = downloadUrl
  try {
    if (typeof fetch === 'function' && typeof URL !== 'undefined' && typeof URL.createObjectURL === 'function') {
      try {
        const response = await fetch(downloadUrl)
        if (!response.ok) throw new Error('The document could not be downloaded.')
        const blob = await response.blob()
        objectUrl = URL.createObjectURL(blob)
        href = objectUrl
      } catch (downloadError) {
        if (downloadError?.message === 'The document could not be downloaded.') throw downloadError
        console.warn('[AgencyPipelinePage] Falling back to direct document download.', downloadError)
      }
    }

    const anchor = document.createElement('a')
    anchor.href = href
    anchor.download = safeFileName
    anchor.rel = 'noopener'
    anchor.style.display = 'none'
    document.body.appendChild(anchor)
    anchor.click()
    anchor.remove()
  } finally {
    if (objectUrl && typeof URL !== 'undefined' && typeof URL.revokeObjectURL === 'function') {
      URL.revokeObjectURL(objectUrl)
    }
  }
}

async function downloadGeneratedSellerLeadDocumentPdf(markup = '', fileName = 'seller-document.pdf') {
  if (typeof window === 'undefined' || typeof document === 'undefined') {
    throw new Error('PDF downloads are only available in the browser.')
  }

  let pdfStage = null
  let styleElement = null
  try {
    const { default: html2pdf } = await import('html2pdf.js/src/index.js')
    const pdfDocument = new window.DOMParser().parseFromString(String(markup || ''), 'text/html')
    const style = pdfDocument.head.querySelector('style')
    styleElement = document.createElement('style')
    styleElement.setAttribute('data-seller-lead-generated-document-pdf-style', 'true')
    styleElement.textContent = style?.textContent || ''
    pdfStage = document.createElement('div')
    pdfStage.setAttribute('data-seller-lead-generated-document-pdf-stage', 'true')
    pdfStage.style.position = 'fixed'
    pdfStage.style.left = '-10000px'
    pdfStage.style.top = '0'
    pdfStage.style.width = '210mm'
    pdfStage.style.background = '#ffffff'
    pdfStage.style.pointerEvents = 'none'
    pdfStage.innerHTML = pdfDocument.body.innerHTML
    document.head.appendChild(styleElement)
    document.body.appendChild(pdfStage)

    const imageLoads = Array.from(pdfStage.querySelectorAll('img')).map((image) => {
      if (image.complete) return Promise.resolve()
      return new Promise((resolve) => {
        image.onload = resolve
        image.onerror = resolve
      })
    })
    await Promise.all(imageLoads)
    await new Promise((resolve) => window.requestAnimationFrame(resolve))

    const exportTarget = pdfStage.querySelector('.property-disclosure-document') || pdfStage
    await html2pdf()
      .set({
        margin: 0,
        filename: toSellerLeadPdfFileName(fileName),
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: {
          scale: 2,
          useCORS: true,
          backgroundColor: '#ffffff',
          windowWidth: 794,
          windowHeight: 1123,
        },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
        pagebreak: { mode: ['css', 'legacy'] },
      })
      .from(exportTarget)
      .save()
  } finally {
    pdfStage?.remove()
    styleElement?.remove()
  }
}

function buildSellerLeadDocumentCategories(documents = []) {
  const grouped = new Map(SELLER_LEAD_DOCUMENT_CATEGORY_CONFIG.map((category) => [category.key, []]))
  documents.forEach((documentRow) => {
    const key = getSellerLeadDocumentCategoryKey(documentRow)
    grouped.get(grouped.has(key) ? key : 'seller').push(documentRow)
  })

  return SELLER_LEAD_DOCUMENT_CATEGORY_CONFIG.map((category) => {
    const items = grouped.get(category.key) || []
    const completed = items.filter((documentRow) => {
      const state = getSellerLeadDocumentStatusMeta(documentRow).state
      return state === 'complete' || state === 'review'
    }).length
    const total = items.length
    const progress = total ? Math.round((completed / total) * 100) : 0
    return {
      ...category,
      items,
      completed,
      total,
      progress,
    }
  })
}

function isKingstonsFicaRoleplayerDocumentRow(documentRow = {}) {
  const key = normalizeKey(documentRow.key || documentRow.requirementKey || documentRow.requirement_key || documentRow.documentType || documentRow.document_type)
  const source = normalizeKey(documentRow.source || documentRow.generatedBy || documentRow.generated_by)
  const section = normalizeKey(documentRow.documentRequirementSection || documentRow.document_requirement_section)
  return source === normalizeKey(KINGSTONS_FICA_ROLEPLAYER_SOURCE) ||
    section === 'seller_identity_fica' ||
    key.startsWith('seller_fica_') ||
    /(owner_fica|director_fica|trustee_fica|member_fica|spouse_fica)/.test(key)
}

function buildRoleplayerFicaDocumentModel(rows = [], { fallbackTitle = 'FICA' } = {}) {
  const groups = []
  const groupIndexById = new Map()
  ;(Array.isArray(rows) ? rows : []).filter(isKingstonsFicaRoleplayerDocumentRow).forEach((documentRow) => {
    const partyName = normalizeText(documentRow.ficaRoleplayerLabel || documentRow.fica_roleplayer_label || documentRow.partyName || documentRow.party_name)
    const partyRole = normalizeKey(documentRow.partyRole || documentRow.party_role || 'roleplayer')
    const rawGroupId = normalizeText(documentRow.ficaRoleplayerId || documentRow.fica_roleplayer_id)
    const groupId = normalizeKey((partyName && `${partyRole}-${partyName}`) || rawGroupId || documentRow.key || documentRow.id)
    if (!groupId) return
    if (!groupIndexById.has(groupId)) {
      groupIndexById.set(groupId, groups.length)
      groups.push({
        id: groupId,
        role: partyRole,
        tabLabel: normalizeText(documentRow.ficaRoleplayerTabLabel || documentRow.fica_roleplayer_tab_label) || (
          partyRole === 'spouse'
            ? 'Spouse'
            : partyRole === 'director'
              ? `Director ${groups.length + 1}`
              : partyRole === 'trustee'
                ? `Trustee ${groups.length + 1}`
                : partyRole === 'member'
                  ? `Member ${groups.length + 1}`
                  : `Seller ${groups.length + 1}`
        ),
        title: partyName || fallbackTitle,
        items: [],
      })
    }
    groups[groupIndexById.get(groupId)].items.push(documentRow)
  })

  return groups.map((group) => {
    const items = [...group.items].sort((left, right) => {
      const leftOrder = Number(left.ficaDocumentOrder ?? left.fica_document_order ?? 999)
      const rightOrder = Number(right.ficaDocumentOrder ?? right.fica_document_order ?? 999)
      return leftOrder - rightOrder || normalizeText(left.label).localeCompare(normalizeText(right.label))
    })
    const completed = items.filter((documentRow) => {
      const state = getSellerLeadDocumentStatusMeta(documentRow).state
      return state === 'complete' || state === 'review'
    }).length
    return {
      ...group,
      items,
      completed,
      total: items.length,
      progress: items.length ? Math.round((completed / items.length) * 100) : 0,
    }
  })
}

function getBuyerFicaRoleplayerDocumentDefinitions(roleplayer = {}) {
  if (roleplayer.type === 'entity') return []
  return BUYER_FICA_ROLEPLAYER_DOCUMENTS
}

function buildBuyerFicaRoleplayerModel({
  lead = {},
  contact = {},
  formData = {},
  transaction = {},
  onboardingSubmitted = false,
} = {}) {
  let configuration = null
  try {
    configuration = deriveOnboardingConfiguration(formData, {
      transaction,
      purchaserType: formData.purchaser_type || transaction?.purchaser_type || lead?.purchaserType || lead?.buyerType,
      financeType: formData.purchase_finance_type || transaction?.finance_type || lead?.financeType || lead?.finance_type,
    })
  } catch {
    configuration = null
  }
  const parties = Array.isArray(configuration?.parties) ? configuration.parties : []
  const people = parties.filter((party) => party?.type !== 'entity')
  const fallbackName = getLeadPrimaryPersonName(lead, contact) || 'Buyer 1'
  const roleplayers = (people.length ? people : [{ role: 'primary_purchaser', name: fallbackName, purchaser: true, signatory: true }])
    .map((party, index) => {
      const role = normalizeKey(party.role || party.relationship || (index ? 'co_purchaser' : 'primary_purchaser'))
      const name = normalizeText(party.name || party.fullName || party.full_name) || (index ? `Buyer ${index + 1}` : fallbackName)
      const tabLabel = role.includes('spouse')
        ? 'Spouse'
        : role.includes('director')
          ? `Director ${index + 1}`
          : role.includes('trustee')
            ? `Trustee ${index + 1}`
            : `Buyer ${index + 1}`
      return {
        ...party,
        id: normalizeKey(party.id || party.key || `${role}-${name}` || `buyer-${index + 1}`),
        role,
        name,
        tabLabel,
      }
    })

  return roleplayers.map((roleplayer) => {
    const items = getBuyerFicaRoleplayerDocumentDefinitions(roleplayer).map((definition, index) => ({
      ...definition,
      id: normalizeKey(`buyer_fica_${roleplayer.id}_${definition.key}`),
      key: normalizeKey(`buyer_fica_${roleplayer.id}_${definition.key}`),
      label: definition.label,
      title: definition.label,
      description: definition.description,
      required: true,
      status: onboardingSubmitted ? 'In review' : 'Not requested',
      statusLabel: onboardingSubmitted ? 'In review' : 'Not requested',
      ficaDocumentOrder: index,
      fica_document_order: index,
    }))
    return {
      id: roleplayer.id,
      role: roleplayer.role,
      tabLabel: roleplayer.tabLabel,
      title: roleplayer.name,
      items,
      completed: onboardingSubmitted ? items.length : 0,
      total: items.length,
      progress: onboardingSubmitted && items.length ? 100 : 0,
    }
  }).filter((group) => group.items.length)
}

function normalizeAppointmentCategorySignal(value) {
  return normalizeKey(value)
    .replace(/[_-]+/g, ' ')
    .replace(/[^a-z0-9\s/]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

function resolveAppointmentCategoryKey(appointment = {}) {
  const primaryType = normalizeAppointmentCategorySignal(appointment?.appointmentType || appointment?.appointment_type)
  const title = normalizeAppointmentCategorySignal(appointment?.title)
  const customType = normalizeAppointmentCategorySignal(appointment?.customTypeLabel || appointment?.custom_type_label)
  const source = normalizeAppointmentCategorySignal(appointment?.source)
  const related = normalizeAppointmentCategorySignal(
    [
      appointment?.category,
      appointment?.appointmentCategory,
      appointment?.relatedEntityType,
      appointment?.related_entity_type,
      appointment?.linkedWorkflow,
      appointment?.linked_workflow,
      appointment?.linkedWorkflowStage,
      appointment?.linked_workflow_stage,
      appointment?.completionBehavior,
      appointment?.completion_behavior,
    ].filter(Boolean).join(' '),
  )
  const label = normalizeAppointmentCategorySignal(getAppointmentTypeLabel(primaryType) || appointment?.appointmentTypeLabel)
  const signal = [primaryType, customType, label, title, source, related].filter(Boolean).join(' ')

  if (/(viewing|property viewing|viewing request|showing|show day|open house)/.test(signal)) return 'viewing'
  if (/(seller consultation|seller consult|seller meeting|seller lead|mandate consultation|mandate meeting)/.test(signal)) return 'seller_consultation'
  if (/(buyer consultation|buyer consult|buyer meeting|buyer lead|buyer appointment)/.test(signal)) return 'buyer_consultation'
  if (/(signing|signature|sign |otp|offer to purchase|document signing|mandate signing|contract signing)/.test(signal)) return 'signing'
  if (/(valuation|appraisal|market appraisal|cma|comparative market analysis|price opinion)/.test(signal)) return 'valuation'
  if (/(photo|photos|photography|media|video|virtual tour|floor plan|floorplan|property photos)/.test(signal)) return 'media'
  if (primaryType === 'other' || primaryType === 'unknown' || /\b(other|unknown|misc)\b/.test(signal)) return 'other'
  return 'general'
}

function getAppointmentCategory(appointment = {}) {
  const key = resolveAppointmentCategoryKey(appointment)
  return APPOINTMENT_CATEGORY_CONFIG[key] || APPOINTMENT_CATEGORY_CONFIG.general
}

function getAppointmentCategoryCardStyle(appointment = {}) {
  const category = getAppointmentCategory(appointment)
  return {
    backgroundColor: category.background,
    borderColor: category.border,
    borderLeftColor: category.accent,
  }
}

function getAppointmentCategoryBadgeStyle(appointment = {}) {
  const category = getAppointmentCategory(appointment)
  return {
    backgroundColor: category.badgeBackground,
    color: category.text,
  }
}

function isUuidLike(value) {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(normalizeText(value))
}

function normalizeLeadUuid(value) {
  const raw = normalizeText(value)
  if (!raw) return ''
  return raw.match(UUID_PATTERN)?.[0] || ''
}

function normalizeWorkspaceUuid(value) {
  const raw = normalizeText(value)
  if (!raw) return ''
  return raw.match(UUID_PATTERN)?.[0] || ''
}

function normalizeLeadUuidFromLead(lead = {}) {
  return [lead?.leadId, lead?.lead_id, lead?.id]
    .map((value) => normalizeLeadUuid(value))
    .find(Boolean) || ''
}

function normalizeLeadIdentityKey(value) {
  return normalizeLeadUuid(value) || normalizeText(value)
}

function normalizeShowDaySignal(value) {
  return normalizeText(value)
    .toLowerCase()
    .replace(/[_-]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
}

function isShowDayLead(lead = {}) {
  const source = normalizeShowDaySignal(lead?.leadSource || lead?.lead_source || lead?.source)
  const reference = normalizeText(
    lead?.sourceReferenceId ||
      lead?.source_reference_id ||
      lead?.externalReference ||
      lead?.external_reference,
  ).toLowerCase()
  const notes = normalizeShowDaySignal(lead?.notes)
  return (
    source === normalizeShowDaySignal(SHOW_DAY_SOURCE_LABEL) ||
    source.includes('show day') ||
    reference.startsWith('show-day:') ||
    notes.includes('show day capture reference')
  )
}

function isOpenCrmTask(task = {}) {
  const status = normalizeShowDaySignal(task?.status || 'Pending')
  return !['completed', 'done', 'cancelled', 'canceled', 'closed'].includes(status)
}

function isShowDayFollowUpTask(task = {}) {
  const signal = normalizeShowDaySignal([
    task?.title,
    task?.description,
    task?.source,
    task?.metadata?.source,
    task?.sourceEvent,
  ].filter(Boolean).join(' '))
  return signal.includes(SHOW_DAY_FOLLOW_UP_TITLE_FRAGMENT) || signal.includes('show day')
}

function isTaskDueBeforeToday(task = {}, now = new Date()) {
  const due = new Date(task?.dueDate || task?.due_date || 0)
  if (Number.isNaN(due.getTime())) return false
  const startOfToday = new Date(now.getFullYear(), now.getMonth(), now.getDate()).getTime()
  return due.getTime() < startOfToday
}

function isCompletedViewingAppointment(appointment = {}) {
  const status = normalizeShowDaySignal(appointment?.status)
  return (
    resolveAppointmentCategoryKey(appointment) === 'viewing' &&
    (
      status.includes('completed') ||
      Boolean(appointment?.completedAt || appointment?.completed_at || appointment?.outcomeSummary || appointment?.outcome_summary)
    )
  )
}

function hasPositiveShowDayOutcome(value = {}) {
  const signal = normalizeShowDaySignal([
    value?.outcomeSummary,
    value?.outcome_summary,
    value?.clientFeedback,
    value?.client_feedback,
    value?.buyerFeedback,
    value?.buyer_feedback,
    value?.nextStep,
    value?.next_step,
    value?.status,
  ].filter(Boolean).join(' '))
  return ['interested', 'wants to offer', 'offer requested', 'offer draft', 'needs follow up', 'needs follow-up']
    .some((token) => signal.includes(token))
}

function getShowDayLeadDisplayName(lead = {}) {
  return normalizeText(
    lead?.displayName ||
      lead?.name ||
      lead?.contactName ||
      lead?.contact_name ||
      [lead?.firstName || lead?.first_name, lead?.lastName || lead?.last_name].filter(Boolean).join(' ') ||
      lead?.email ||
      lead?.phone,
  ) || 'Show-day buyer'
}

function buildShowDayFollowUpSummary({
  leads = [],
  tasks = [],
  appointments = [],
  deals = [],
} = {}) {
  const showDayLeads = (Array.isArray(leads) ? leads : []).filter(isShowDayLead)
  const taskRows = Array.isArray(tasks) ? tasks : []
  const appointmentRows = Array.isArray(appointments) ? appointments : []
  const dealLeadKeys = new Set(
    (Array.isArray(deals) ? deals : [])
      .map((deal) => normalizeLeadIdentityKey(deal?.leadId || deal?.lead_id || deal?.buyerLeadId || deal?.buyer_lead_id))
      .filter(Boolean),
  )
  const now = new Date()
  const rows = showDayLeads.map((lead) => {
    const leadKey = normalizeLeadIdentityKey(lead?.leadId || lead?.id)
    const leadTasks = taskRows
      .filter((task) => normalizeLeadIdentityKey(task?.leadId || task?.lead_id) === leadKey)
      .filter(isShowDayFollowUpTask)
      .sort((left, right) => new Date(left?.dueDate || left?.createdAt || 0) - new Date(right?.dueDate || right?.createdAt || 0))
    const openTasks = leadTasks.filter(isOpenCrmTask)
    const leadAppointments = appointmentRows
      .filter((appointment) => normalizeLeadIdentityKey(appointment?.leadId || appointment?.lead_id) === leadKey)
      .filter(isCompletedViewingAppointment)
      .sort((left, right) => new Date(right?.completedAt || right?.dateTime || right?.updatedAt || 0) - new Date(left?.completedAt || left?.dateTime || left?.updatedAt || 0))
    const positiveViewing = leadAppointments.find(hasPositiveShowDayOutcome) || leadAppointments[0] || null
    const stageSignal = normalizeShowDaySignal(`${lead?.stage || ''} ${lead?.status || ''}`)
    const hasCompletedViewing = Boolean(positiveViewing) || stageSignal.includes('viewing completed')
    const offerReady = hasCompletedViewing && !dealLeadKeys.has(leadKey)
    const dueTask = openTasks[0] || null
    const dueDate = normalizeText(dueTask?.dueDate || dueTask?.due_date || lead?.nextFollowUpDate || lead?.next_follow_up_date)

    return {
      lead,
      leadId: normalizeText(lead?.leadId || lead?.id),
      name: getShowDayLeadDisplayName(lead),
      property: normalizeText(lead?.propertyInterest || lead?.enquiredPropertyTitle || lead?.enquiredPropertyAddress || lead?.areaInterest || lead?.listingId),
      dueDate,
      openFollowUps: openTasks.length,
      overdue: openTasks.some((task) => isTaskDueBeforeToday(task, now)),
      viewed: hasCompletedViewing,
      offerReady,
      outcome: normalizeText(positiveViewing?.outcomeSummary || positiveViewing?.clientFeedback || lead?.stage || lead?.status),
      latestViewingAt: normalizeText(positiveViewing?.completedAt || positiveViewing?.dateTime || positiveViewing?.updatedAt),
    }
  })

  const queue = rows
    .filter((row) => row.openFollowUps > 0 || row.offerReady)
    .sort((left, right) => {
      if (left.overdue !== right.overdue) return left.overdue ? -1 : 1
      const leftTime = new Date(left.dueDate || left.latestViewingAt || 8640000000000000).getTime()
      const rightTime = new Date(right.dueDate || right.latestViewingAt || 8640000000000000).getTime()
      return (Number.isFinite(leftTime) ? leftTime : 0) - (Number.isFinite(rightTime) ? rightTime : 0)
    })

  return {
    captured: rows.length,
    viewed: rows.filter((row) => row.viewed).length,
    due: rows.reduce((count, row) => count + row.openFollowUps, 0),
    overdue: rows.filter((row) => row.overdue).length,
    offerReady: rows.filter((row) => row.offerReady).length,
    queue,
  }
}

function isAuthSessionMissingError(error) {
  const message = normalizeText(error?.message || error).toLowerCase()
  return message.includes('auth session missing') || message.includes('missing auth session')
}

function getCanvassingStorageKey(organisationId) {
  const workspaceId = normalizeText(organisationId)
  if (!workspaceId) throw new Error('A resolved workspace is required before loading canvassing data.')
  return `${CANVASSING_STORAGE_PREFIX}:${workspaceId}`
}

function readCanvassingStore(organisationId) {
  if (typeof window === 'undefined') return { prospects: [], activities: [] }
  if (!isUnsafeFallbackAllowed()) return { prospects: [], activities: [] }
  try {
    const parsed = JSON.parse(window.localStorage.getItem(getCanvassingStorageKey(organisationId)) || '{}')
    return {
      prospects: Array.isArray(parsed?.prospects) ? parsed.prospects : [],
      activities: Array.isArray(parsed?.activities) ? parsed.activities : [],
    }
  } catch {
    return { prospects: [], activities: [] }
  }
}

function resolveCanvassingProspectCategory(prospect = {}) {
  const type = normalizeText(prospect?.prospectType).toLowerCase()
  if (type.includes('seller') || type.includes('landlord')) return 'Seller'
  if (type.includes('buyer') || type.includes('tenant') || type.includes('investor')) return 'Buyer'
  return 'Buyer'
}

function buildLeadContactFallback(lead = {}) {
  const explicitName = normalizeText(lead?.name || lead?.buyerName)
  const explicitParts = explicitName.split(/\s+/).filter(Boolean)
  const firstName = normalizeText(
    lead?.sellerName ||
    lead?.firstName ||
    lead?.first_name ||
    explicitParts[0],
  )
  const lastName = normalizeText(
    lead?.sellerSurname ||
    lead?.lastName ||
    lead?.last_name ||
    explicitParts.slice(1).join(' '),
  )
  const phone = normalizeText(lead?.sellerPhone || lead?.phone)
  const email = normalizeText(lead?.sellerEmail || lead?.email).toLowerCase()
  if (!firstName && !lastName && !phone && !email) return null
  return {
    contactId: normalizeText(lead?.contactId),
    firstName,
    lastName,
    phone,
    email,
    contactType: normalizeText(lead?.leadCategory) || 'Lead',
  }
}

function isGenericLeadPersonName(value = '') {
  const normalized = normalizeKey(value).replace(/\s+/g, ' ')
  return !normalized || ['lead', 'contact', 'buyer', 'seller', 'unnamed lead', 'unnamed'].includes(normalized)
}

function formatContactName(contact = null) {
  return [contact?.firstName, contact?.lastName].map(normalizeText).filter(Boolean).join(' ').trim()
}

function mergeLeadContactSnapshot(primary = null, secondary = null) {
  if (!primary && !secondary) return null
  return {
    ...(secondary || {}),
    ...(primary || {}),
    contactId: normalizeText(primary?.contactId || secondary?.contactId),
    firstName: normalizeText(primary?.firstName || secondary?.firstName),
    lastName: normalizeText(primary?.lastName || secondary?.lastName),
    phone: normalizeText(primary?.phone || secondary?.phone),
    email: normalizeText(primary?.email || secondary?.email).toLowerCase(),
    contactType: normalizeText(primary?.contactType || secondary?.contactType) || 'Lead',
  }
}

function resolveLeadContactSnapshot(lead = {}, contact = null, prospect = null) {
  const leadFallback = buildLeadContactFallback(lead)
  const prospectFallback = buildCanvassingProspectContactFallback(prospect)
  const candidates = [contact, leadFallback, prospectFallback].filter(Boolean)
  const namedCandidate = candidates.find((candidate) => !isGenericLeadPersonName(formatContactName(candidate)))

  if (namedCandidate) {
    const detailFallback = candidates.find((candidate) => candidate !== namedCandidate) || null
    return mergeLeadContactSnapshot(namedCandidate, detailFallback)
  }

  return mergeLeadContactSnapshot(contact, leadFallback || prospectFallback) || leadFallback || prospectFallback || null
}

function resolveLeadDisplayName(lead = {}, contact = null, prospect = null, fallback = 'Unnamed Lead') {
  const resolvedContact = resolveLeadContactSnapshot(lead, contact, prospect)
  const contactName = formatContactName(resolvedContact)
  if (!isGenericLeadPersonName(contactName)) return contactName

  const leadName = normalizeText(lead?.name || lead?.buyerName || [lead?.sellerName, lead?.sellerSurname].filter(Boolean).join(' '))
  if (!isGenericLeadPersonName(leadName)) return leadName

  const prospectName = [prospect?.firstName, prospect?.lastName].map(normalizeText).filter(Boolean).join(' ').trim()
  if (!isGenericLeadPersonName(prospectName)) return prospectName

  return fallback
}

function buildCanvassingProspectContactFallback(prospect = {}) {
  const firstName = normalizeText(prospect?.firstName)
  const lastName = normalizeText(prospect?.lastName)
  const phone = normalizeText(prospect?.phone)
  const email = normalizeText(prospect?.email).toLowerCase()
  if (!firstName && !lastName && !phone && !email) return null
  return {
    contactId: '',
    firstName,
    lastName,
    phone,
    email,
    contactType: resolveCanvassingProspectCategory(prospect),
  }
}

function formatCurrency(value) {
  const amount = Number(value || 0)
  if (!Number.isFinite(amount) || amount <= 0) return 'R 0'
  return new Intl.NumberFormat('en-ZA', { style: 'currency', currency: 'ZAR', maximumFractionDigits: 0 }).format(amount)
}

function parseCurrencyAmount(value) {
  if (typeof value === 'number') return Number.isFinite(value) ? value : 0
  const raw = normalizeText(value).toLowerCase()
  if (!raw) return 0
  const firstNumber = raw.match(/[\d]+(?:[.,]\d+)?/)
  if (!firstNumber) return 0
  const number = Number(firstNumber[0].replace(',', '.'))
  if (!Number.isFinite(number)) return 0
  if (raw.includes('million') || raw.includes('m')) return number * 1000000
  if (raw.includes('k')) return number * 1000
  return number
}

const PROPERTY_WORKSPACE_FIELD_MAPPING = [
  { uiField: 'fullAddress', source: 'property', sourceField: 'sellerPropertyAddress', fallbackSource: 'seller_onboarding.propertyAddress', writable: true },
  { uiField: 'propertyType', source: 'property', sourceField: 'propertyInterest', fallbackSource: 'seller_onboarding.propertyType', writable: true },
  { uiField: 'propertySubtype', source: 'seller_onboarding', sourceField: 'propertyStructureType', fallbackSource: 'listing.propertyType', writable: true },
  { uiField: 'suburb', source: 'property', sourceField: 'suburb', fallbackSource: 'seller_onboarding.suburb', writable: true },
  { uiField: 'city', source: 'property', sourceField: 'city', fallbackSource: 'seller_onboarding.city', writable: true },
  { uiField: 'province', source: 'property', sourceField: 'province', fallbackSource: 'seller_onboarding.province', writable: true },
  { uiField: 'postalCode', source: 'property', sourceField: 'postalCode', fallbackSource: 'seller_onboarding.postalCode', writable: true },
  { uiField: 'bedrooms', source: 'property', sourceField: 'bedrooms', fallbackSource: 'seller_onboarding.bedrooms', writable: true },
  { uiField: 'bathrooms', source: 'property', sourceField: 'bathrooms', fallbackSource: 'seller_onboarding.bathrooms', writable: true },
  { uiField: 'features', source: 'seller_onboarding', sourceField: 'propertyFeatures', fallbackSource: 'listing.features', writable: false },
  { uiField: 'occupancyStatus', source: 'seller_onboarding', sourceField: 'occupancyStatus', fallbackSource: null, writable: false },
  { uiField: 'listingStatus', source: 'listing', sourceField: 'listingStatus', fallbackSource: 'seller_journey.kpis.listing', writable: false },
  { uiField: 'listingReadiness', source: 'listing', sourceField: 'sellerReadiness.listingReadiness', fallbackSource: null, writable: false },
  { uiField: 'mediaCounts', source: 'media', sourceField: 'listing.marketing', fallbackSource: 'seller_onboarding.imageGallery', writable: false },
]

function isPlainObject(value) {
  return Boolean(value && typeof value === 'object' && !Array.isArray(value))
}

function asArray(value) {
  return Array.isArray(value) ? value : []
}

function firstWorkspaceText(...values) {
  return values.map(normalizeText).find(Boolean) || ''
}

function workspaceTextLooksLikeAddress(value = '') {
  const text = normalizeText(value)
  if (!text) return false
  return text.includes(',') || /\d/.test(text)
}

function buildWorkspaceFormattedAddress(addressLine = '', ...parts) {
  const line = normalizeText(addressLine)
  const lineKey = line.toLowerCase()
  const rows = [line]
  for (const part of parts.map(normalizeText).filter(Boolean)) {
    const partKey = part.toLowerCase()
    if (rows.some((row) => row.toLowerCase() === partKey)) continue
    if (lineKey && lineKey.includes(partKey)) continue
    rows.push(part)
  }
  return rows.filter(Boolean).join(', ')
}

function firstWorkspaceValue(...values) {
  for (const value of values) {
    if (Array.isArray(value) && value.length) return value
    if (isPlainObject(value) && Object.keys(value).length) return value
    if (typeof value === 'number' && Number.isFinite(value) && value !== 0) return value
    if (typeof value === 'boolean') return value
    const text = normalizeText(value)
    if (text) return value
  }
  return ''
}

function formatCapturedValue(value, fallback = 'Not captured') {
  if (typeof value === 'boolean') return value ? 'Yes' : 'No'
  const text = normalizeText(value)
  return text || fallback
}

function formatMaybeCurrency(value) {
  const amount = parseCurrencyAmount(value)
  return amount > 0 ? formatCurrency(amount) : formatCapturedValue(value)
}

function titleCaseWorkspaceValue(value = '') {
  const text = normalizeText(value).replace(/[_-]+/g, ' ')
  if (!text) return ''
  return text.replace(/\b\w/g, (letter) => letter.toUpperCase())
}

function formatMetricValue(value, suffix = '') {
  const text = normalizeText(value)
  if (!text) return 'Not captured'
  const amount = Number(text)
  if (Number.isFinite(amount) && amount > 0) {
    return suffix ? `${new Intl.NumberFormat('en-ZA').format(amount)} ${suffix}` : new Intl.NumberFormat('en-ZA').format(amount)
  }
  return suffix && !text.includes(suffix) ? `${text} ${suffix}` : text
}

function splitWorkspaceTextList(value) {
  if (Array.isArray(value)) return value.flatMap(splitWorkspaceTextList)
  if (isPlainObject(value)) {
    return Object.entries(value)
      .filter(([, entryValue]) => entryValue === true || normalizeText(entryValue))
      .map(([key, entryValue]) => entryValue === true ? titleCaseWorkspaceValue(key) : normalizeText(entryValue))
  }
  const text = normalizeText(value)
  if (!text) return []
  return text
    .split(/[,;\n]+/)
    .map((item) => item.trim())
    .filter(Boolean)
    .slice(0, 16)
}

function uniqueWorkspaceList(values = []) {
  const seen = new Set()
  const rows = []
  for (const value of values.flatMap(splitWorkspaceTextList)) {
    const label = titleCaseWorkspaceValue(value)
    const key = normalizeText(label).toLowerCase()
    if (!key || seen.has(key)) continue
    seen.add(key)
    rows.push(label)
  }
  return rows
}

function countWorkspaceMedia(...groups) {
  return groups.flatMap((group) => {
    if (Array.isArray(group)) return group
    if (group) return [group]
    return []
  }).filter(Boolean).length
}

function getWorkspaceSellerOnboarding(lead = {}, listing = {}) {
  return {
    ...getListingSellerFormData(listing?.sourceListing || listing || {}),
    ...getLeadSellerOnboardingFormData(lead),
  }
}

function buildSellerPropertyWorkspaceViewModel({ lead = {}, listing = null, journey = {}, readiness = {}, documentSummary = {} } = {}) {
  const listingSource = listing?.sourceListing && isPlainObject(listing.sourceListing) ? listing.sourceListing : (listing || {})
  const onboarding = getWorkspaceSellerOnboarding(lead, listingSource)
  const propertyDetails = {
    ...(isPlainObject(listingSource?.propertyDetails) ? listingSource.propertyDetails : {}),
    ...(isPlainObject(listingSource?.property_details) ? listingSource.property_details : {}),
    ...(isPlainObject(lead?.propertyDetails) ? lead.propertyDetails : {}),
    ...(isPlainObject(lead?.property_details) ? lead.property_details : {}),
  }
  const marketing = {
    ...(isPlainObject(listingSource?.marketing) ? listingSource.marketing : {}),
    ...(isPlainObject(listingSource?.marketing_details) ? listingSource.marketing_details : {}),
  }
  const addressLine = firstWorkspaceText(
    lead?.sellerPropertyAddress,
    lead?.seller_property_address,
    lead?.formattedAddress,
    lead?.streetAddress,
    onboarding?.propertyAddress,
    onboarding?.formattedAddress,
    onboarding?.streetAddress,
    propertyDetails?.address,
    listingSource?.propertyAddress,
    listingSource?.property_address,
    listingSource?.address,
    listing?.address,
  )
  const suburb = firstWorkspaceText(lead?.suburb, onboarding?.suburb, propertyDetails?.suburb, listingSource?.suburb, listing?.suburb)
  const city = firstWorkspaceText(lead?.city, onboarding?.city, propertyDetails?.city, listingSource?.city)
  const province = firstWorkspaceText(lead?.province, onboarding?.province, propertyDetails?.province, listingSource?.province)
  const postalCode = firstWorkspaceText(lead?.postalCode, lead?.postal_code, onboarding?.postalCode, onboarding?.postal_code, propertyDetails?.postalCode, listingSource?.postalCode, listingSource?.postal_code)
  const formattedAddress = buildWorkspaceFormattedAddress(addressLine, suburb, city, province, postalCode)
  const listingId = firstWorkspaceText(listingSource?.id, listingSource?.listingId, listingSource?.listing_id, listing?.id, lead?.listingId, lead?.listing_id)
  const listingStatus = firstWorkspaceText(
    listingSource?.listingStatus,
    listingSource?.listing_status,
    listingSource?.status,
    listing?.status,
    journey?.kpis?.find?.((item) => item.key === 'listing')?.value,
  )
  const readinessModel = readiness?.listingReadiness || {}
  const listingReadiness = {
    percent: Number(readinessModel?.percent || 0) || 0,
    items: asArray(readinessModel?.items),
    incompleteItems: asArray(readinessModel?.incompleteItems).length
      ? asArray(readinessModel?.incompleteItems)
      : asArray(readiness?.blockers),
  }
  const leadPropertyInterestAsType = workspaceTextLooksLikeAddress(lead?.propertyInterest) ? '' : lead?.propertyInterest
  const propertyType = firstWorkspaceText(lead?.propertyType, lead?.property_type, onboarding?.propertyType, onboarding?.property_type, propertyDetails?.propertyType, listingSource?.propertyType, listing?.propertyType, leadPropertyInterestAsType)
  const features = uniqueWorkspaceList([
    propertyDetails?.features,
    propertyDetails?.propertyFeatures,
    onboarding?.propertyFeatures,
    onboarding?.features,
    onboarding?.property_features,
    listingSource?.features,
    listingSource?.amenities,
  ])
  const photos = countWorkspaceMedia(
    listingSource?.galleryImages,
    listingSource?.gallery_images,
    listingSource?.images,
    listingSource?.photos,
    listingSource?.media,
    marketing?.imageGallery,
    marketing?.image_gallery,
    onboarding?.imageGallery,
    onboarding?.image_gallery,
    listingSource?.coverImage,
    listingSource?.imageUrl,
    listing?.thumbnailUrl,
  )
  return {
    fieldMapping: PROPERTY_WORKSPACE_FIELD_MAPPING,
    profile: {
      address: formattedAddress || addressLine || 'No property address yet',
      sourceLabel: Object.keys(onboarding).length ? 'Provided by seller' : 'Updated by agent',
      rows: [
        { label: 'Property type', value: propertyType },
        { label: 'Property title type', value: firstWorkspaceText(onboarding?.propertyTitleType, onboarding?.property_title_type, onboarding?.propertySubtype, onboarding?.property_subtype, onboarding?.propertyStructureType, onboarding?.property_structure_type, propertyDetails?.propertyTitleType, propertyDetails?.property_title_type, propertyDetails?.propertySubtype, propertyDetails?.propertyStructureType) },
        { label: 'Complex / Estate', value: firstWorkspaceText(onboarding?.complexName, onboarding?.estateName, onboarding?.estateComplexName, propertyDetails?.complexName, listingSource?.estateName) },
        { label: 'Erf / Stand number', value: firstWorkspaceText(lead?.erfNumber, onboarding?.erfNumber, onboarding?.standNumber, onboarding?.propertyReference, propertyDetails?.erfNumber) },
        { label: 'Sectional title', value: firstWorkspaceValue(onboarding?.sectionalTitle, onboarding?.isSectionalTitle, propertyDetails?.sectionalTitle) },
        { label: 'Unit number', value: firstWorkspaceText(onboarding?.unitNumber, onboarding?.unit_number, propertyDetails?.unitNumber) },
        { label: 'Suburb', value: suburb },
        { label: 'City', value: city },
        { label: 'Province', value: province },
        { label: 'Postal code', value: postalCode },
        { label: 'GPS coordinates', value: firstWorkspaceText(
          lead?.latitude && lead?.longitude ? `${lead.latitude}, ${lead.longitude}` : '',
          onboarding?.latitude && onboarding?.longitude ? `${onboarding.latitude}, ${onboarding.longitude}` : '',
          propertyDetails?.latitude && propertyDetails?.longitude ? `${propertyDetails.latitude}, ${propertyDetails.longitude}` : '',
        ) },
      ].map((row) => ({ ...row, value: formatCapturedValue(row.value) })),
    },
    listing: {
      hasListing: Boolean(listingId || journey?.listingCreated),
      id: listingId,
      status: listingStatus || 'Not created',
      statusTone: journey?.listingLive || normalizeText(listingStatus).toLowerCase().includes('live') || normalizeText(listingStatus).toLowerCase().includes('active') ? 'success' : listingId ? 'warning' : 'neutral',
      title: firstWorkspaceText(listingSource?.listingTitle, listingSource?.title, listingSource?.propertyName, listing?.title, formattedAddress, addressLine),
      reference: firstWorkspaceText(listingSource?.listingReference, listingSource?.reference, listingSource?.listing_reference, listingId),
      askingPrice: firstWorkspaceValue(listingSource?.askingPrice, listingSource?.asking_price, listingSource?.price, lead?.estimatedValue, onboarding?.askingPrice),
      estimatedValue: firstWorkspaceValue(lead?.estimatedValue, lead?.estimated_value, listingSource?.estimatedValue, listingSource?.estimated_value, onboarding?.estimatedValue),
      createdAt: firstWorkspaceText(listingSource?.createdAt, listingSource?.created_at, listing?.createdAt, lead?.createdAt),
      updatedAt: firstWorkspaceText(listingSource?.updatedAt, listingSource?.updated_at, listing?.updatedAt, lead?.updatedAt),
      readiness: listingReadiness,
      nextAction: readiness?.nextAction || null,
    },
    characteristics: {
      metrics: [
        { label: 'Bedrooms', value: firstWorkspaceValue(lead?.bedrooms, onboarding?.bedrooms, propertyDetails?.bedrooms, listingSource?.bedrooms, listing?.bedrooms), Icon: BedDouble },
        { label: 'Bathrooms', value: firstWorkspaceValue(lead?.bathrooms, onboarding?.bathrooms, propertyDetails?.bathrooms, listingSource?.bathrooms, listing?.bathrooms), Icon: Bath },
        { label: 'Garages', value: firstWorkspaceValue(lead?.garages, onboarding?.garages, propertyDetails?.garages, listingSource?.garages), Icon: Home },
        { label: 'Parking', value: firstWorkspaceValue(lead?.parking, onboarding?.parking, onboarding?.parkingSpaces, propertyDetails?.parking, listingSource?.coveredParking, listingSource?.openParking, listing?.parking), Icon: Car },
        { label: 'Erf size', value: firstWorkspaceValue(lead?.erfSize, onboarding?.erfSize, onboarding?.propertySize, propertyDetails?.erfSize, listingSource?.erfSize), suffix: 'm²', Icon: Ruler },
        { label: 'Floor size', value: firstWorkspaceValue(lead?.floorSize, onboarding?.floorSize, propertyDetails?.floorSize, listingSource?.floorSize), suffix: 'm²', Icon: Building2 },
      ],
      details: [
        { label: 'Storeys', value: firstWorkspaceValue(onboarding?.storeys, propertyDetails?.storeys) },
        { label: 'Year built', value: firstWorkspaceValue(onboarding?.yearBuilt, propertyDetails?.yearBuilt) },
        { label: 'Condition', value: firstWorkspaceValue(onboarding?.propertyCondition, onboarding?.condition, propertyDetails?.condition) },
      ].map((row) => ({ ...row, value: formatCapturedValue(row.value) })),
      features,
    },
    occupancy: {
      rows: [
        { label: 'Occupancy status', value: firstWorkspaceText(onboarding?.occupancyStatus, onboarding?.occupancy_status, onboarding?.occupationStatus), Icon: UserRound },
        { label: 'Current occupants', value: firstWorkspaceText(onboarding?.currentOccupants, onboarding?.occupants), Icon: Home },
        { label: 'Vacant from', value: firstWorkspaceText(onboarding?.vacantFrom, onboarding?.vacant_from), Icon: CalendarDays },
        { label: 'Tenancy', value: firstWorkspaceText(onboarding?.tenancyStatus, onboarding?.tenancy_status, onboarding?.leaseStatus), Icon: FileText },
        { label: 'Lease end date', value: firstWorkspaceText(onboarding?.leaseEndDate, onboarding?.lease_end_date), Icon: Clock3 },
        { label: 'Rates & taxes', value: firstWorkspaceValue(onboarding?.ratesAndTaxes, onboarding?.ratesTaxes, onboarding?.monthlyRates), Icon: Tag, format: 'currency' },
        { label: 'Levies', value: firstWorkspaceValue(onboarding?.levies, onboarding?.monthlyLevies), Icon: Columns3, format: 'currency' },
        { label: 'Viewing availability', value: firstWorkspaceText(onboarding?.viewingAvailabilityWindows, onboarding?.viewing_availability_windows, onboarding?.canonicalSellerFacts?.occupancy?.viewing_availability_windows), Icon: CalendarDays },
        { label: 'Access arrangement', value: firstWorkspaceText(onboarding?.viewingAccessInstructions, onboarding?.viewing_access_instructions, onboarding?.accessArrangement, onboarding?.accessInstructions, onboarding?.viewingInstructions), Icon: Lock },
      ],
    },
    marketing: {
      listingDescription: firstWorkspaceText(listingSource?.description, listingSource?.propertyDescription, listingSource?.property_description, marketing?.description),
      sellerDescription: firstWorkspaceText(onboarding?.marketingDescription, onboarding?.propertyDescription, onboarding?.description, onboarding?.sellerNotes, lead?.notes),
      headline: firstWorkspaceText(marketing?.headline, listingSource?.headline, onboarding?.marketingHeadline),
      keySellingPoints: uniqueWorkspaceList([marketing?.keySellingPoints, marketing?.sellingPoints, onboarding?.keySellingPoints, onboarding?.sellingPoints]),
      mediaCounts: {
        photos,
        videos: countWorkspaceMedia(listingSource?.videos, marketing?.videos, onboarding?.videos, onboarding?.videoGallery),
        floorplans: countWorkspaceMedia(listingSource?.floorplans, listingSource?.floorPlans, marketing?.floorplans, marketing?.floorPlans, onboarding?.floorplans, onboarding?.floorPlans),
        virtualTours: countWorkspaceMedia(listingSource?.virtualTours, listingSource?.virtual_tours, marketing?.virtualTours, onboarding?.virtualTours),
        documents: Number(documentSummary?.total || 0) || asArray(listingSource?.documents).length,
      },
    },
  }
}

function formatCompactCurrency(value) {
  const amount = Number(value || 0)
  if (!Number.isFinite(amount) || amount <= 0) return 'Not captured'
  if (amount >= 1000000) {
    const compact = amount / 1000000
    return `R${Number.isInteger(compact) ? compact.toFixed(0) : compact.toFixed(1)}m`
  }
  if (amount >= 1000) return `R${Math.round(amount / 1000)}k`
  return formatCurrency(amount)
}

function buildBuyerBudgetRangeLabel({ lead = {}, financeSummary = {} } = {}) {
  const rawBudget = normalizeText(lead?.budget)
  const rawEstimated = normalizeText(lead?.estimatedValue)
  if (rawBudget && /[a-z]|-|–|—/i.test(rawBudget) && parseCurrencyAmount(rawBudget) > 0) return rawBudget

  const affordability = financeSummary?.affordabilityEstimate || {}
  const min = Number(affordability.estimatedPurchaseRangeMin || 0) || 0
  const max = Number(affordability.estimatedPurchaseRangeMax || 0) || 0
  if (min > 0 && max > 0 && min !== max) return `${formatCompactCurrency(min)} - ${formatCompactCurrency(max)}`

  const budget = parseCurrencyAmount(rawBudget)
  const estimated = parseCurrencyAmount(rawEstimated)
  if (budget > 0 && estimated > 0 && budget !== estimated) {
    return `${formatCompactCurrency(Math.min(budget, estimated))} - ${formatCompactCurrency(Math.max(budget, estimated))}`
  }
  if (budget > 0) return formatCompactCurrency(budget)
  if (estimated > 0) return formatCompactCurrency(estimated)
  return 'Not captured'
}

function getBuyerUrgencyLabel({ lead = {}, openActions = {}, activityInsights = {} } = {}) {
  const priority = normalizeText(lead?.priority || lead?.leadScore).toLowerCase()
  if (priority.includes('high') || priority.includes('hot') || openActions?.overdueCount > 0) return 'High'
  if (activityInsights?.temperature === 'Hot') return 'High'
  if (priority.includes('low') || activityInsights?.temperature === 'Cool') return 'Low'
  return 'Medium'
}

function getBuyerUrgencyClassName(label = '') {
  const normalized = normalizeText(label).toLowerCase()
  if (normalized === 'high') return 'border-[#ffd0d3] bg-[#fff2f2] text-[#c3263c]'
  if (normalized === 'low') return 'border-[#dce8f2] bg-[#f6f9fc] text-[#60758b]'
  return 'border-[#f2ddb4] bg-[#fff8e8] text-[#9a6416]'
}

function resolveBuyerWorkspaceTabKey(tabKey = '') {
  const normalized = normalizeLeadWorkspaceTabKey(tabKey)
  if (['documents', 'insights', 'mapping'].includes(normalized)) return 'overview'
  return normalized
}

function buildAppointmentListingLabel(listing = {}) {
  const reference = normalizeText(listing?.listingReference || listing?.reference || listing?.listing_reference)
  const title = normalizeText(listing?.listingTitle || listing?.title || listing?.propertyName || listing?.property_name)
  const address = normalizeText(listing?.propertyAddress || listing?.address || listing?.addressLine1 || listing?.address_line_1)
  const suburb = normalizeText(listing?.suburb)
  const price = Number(listing?.askingPrice || listing?.asking_price || listing?.price || listing?.estimatedValue || 0)
  const displayReference = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(reference)
    ? ''
    : reference
  const primaryLabel = title || address || displayReference || suburb || 'Listing'
  const primaryLabelKey = primaryLabel.toLowerCase()
  const addressKey = address.toLowerCase()
  const suburbKey = suburb.toLowerCase()
  const showSuburb = suburb && suburb !== primaryLabel && !primaryLabelKey.includes(suburbKey) && !addressKey.includes(suburbKey)
  return [
    primaryLabel,
    address && address !== primaryLabel ? address : '',
    showSuburb ? suburb : '',
    Number.isFinite(price) && price > 0 ? formatCurrency(price) : '',
  ].filter(Boolean).join(' — ')
}

function resolveMediaUrl(media = {}) {
  if (!media || typeof media !== 'object') return ''
  return normalizeText(media?.url || media?.signedUrl || media?.publicUrl || media?.fileUrl || media?.src)
}

function resolveListingImageUrl(listing = {}) {
  const marketing = listing?.marketing && typeof listing.marketing === 'object' ? listing.marketing : {}
  const propertyDetails = listing?.propertyDetails && typeof listing.propertyDetails === 'object' ? listing.propertyDetails : {}
  const onboardingFormData =
    listing?.sellerOnboarding?.formData && typeof listing.sellerOnboarding.formData === 'object'
      ? listing.sellerOnboarding.formData
      : {}
  const gallery = [
    ...(Array.isArray(marketing.imageGallery) ? marketing.imageGallery : []),
    ...(Array.isArray(listing?.imageGallery) ? listing.imageGallery : []),
    ...(Array.isArray(onboardingFormData.imageGallery) ? onboardingFormData.imageGallery : []),
    ...(Array.isArray(listing?.images) ? listing.images : []),
  ].filter((item) => resolveMediaUrl(item))
  const coverImageId = normalizeText(marketing.coverImageId || propertyDetails.coverImageId || onboardingFormData.coverImageId || listing?.coverImageId || listing?.cover_image_id)
  const coverImage =
    resolveMediaUrl(listing?.coverImage)
      ? listing.coverImage
      : gallery.find((item) => normalizeText(item?.id || item?.path) === coverImageId) || gallery[0] || null
  return normalizeText(marketing.mediaUrl || listing?.mediaUrl || listing?.coverImageUrl || listing?.thumbnailUrl || resolveMediaUrl(coverImage))
}

function resolveListingAddressLabel(listing = {}) {
  return normalizeText(
    listing?.propertyAddress ||
      listing?.property_address ||
      listing?.sellerPropertyAddress ||
      listing?.seller_property_address ||
      listing?.address ||
      listing?.formattedAddress ||
      listing?.formatted_address ||
      listing?.addressLine1 ||
      listing?.address_line_1 ||
      listing?.streetAddress ||
      listing?.street_address,
  )
}

function resolveRouteLeadStagePatchFromLinkedListing(lead = {}, listing = {}) {
  const journey = buildSellerJourney({
    lead: {
      ...lead,
      listingId: normalizeText(lead?.listingId || lead?.listing_id || listing?.id || listing?.listingId || listing?.listing_id),
      mandatePacketId: normalizeText(lead?.mandatePacketId || lead?.mandate_packet_id || listing?.mandatePacketId || listing?.mandate_packet_id),
    },
    listing,
    documents: Array.isArray(listing?.documents) ? listing.documents : [],
  })
  if (journey?.isSeller && journey?.stage?.label) {
    return {
      stage: journey.stage.label,
      status: normalizeText(journey.stage.status) || journey.stage.label,
    }
  }

  const mandateStatus = normalizeKey(listing?.mandateStatus || listing?.mandate_status)
  const combinedLeadStage = normalizeKey(`${lead?.stage || ''} ${lead?.status || ''}`)
  const hasSignedMandate = Boolean(
    mandateStatus.includes('signed') ||
      mandateStatus.includes('completed') ||
      normalizeText(lead?.mandatePacketId || lead?.mandate_packet_id || listing?.mandatePacketId || listing?.mandate_packet_id),
  )
  if (!hasSignedMandate || combinedLeadStage.includes('mandate_signed') || combinedLeadStage.includes('listing')) {
    return {}
  }
  return {
    stage: 'Mandate Signed',
    status: 'Signed',
  }
}

function enrichRouteLeadWithLinkedListing(lead = {}, listing = null) {
  if (!lead || !listing) return lead
  const onboarding = listing?.sellerOnboarding && typeof listing.sellerOnboarding === 'object'
    ? listing.sellerOnboarding
    : listing?.seller_onboarding && typeof listing.seller_onboarding === 'object'
      ? listing.seller_onboarding
      : null
  const address = resolveListingAddressLabel(listing)
  const stagePatch = resolveRouteLeadStagePatchFromLinkedListing(lead, listing)
  const mandatePacketId = normalizeText(lead?.mandatePacketId || lead?.mandate_packet_id || listing?.mandatePacketId || listing?.mandate_packet_id)
  return {
    ...lead,
    ...stagePatch,
    sellerPropertyAddress: normalizeText(lead?.sellerPropertyAddress || lead?.seller_property_address) || address,
    formattedAddress: normalizeText(lead?.formattedAddress || lead?.formatted_address) || normalizeText(listing?.formattedAddress || listing?.formatted_address),
    streetAddress: normalizeText(lead?.streetAddress || lead?.street_address) || normalizeText(listing?.streetAddress || listing?.street_address || listing?.addressLine1 || listing?.address_line_1),
    suburb: normalizeText(lead?.suburb) || normalizeText(listing?.suburb),
    city: normalizeText(lead?.city) || normalizeText(listing?.city),
    province: normalizeText(lead?.province) || normalizeText(listing?.province),
    country: normalizeText(lead?.country) || normalizeText(listing?.country) || 'South Africa',
    postalCode: normalizeText(lead?.postalCode || lead?.postal_code) || normalizeText(listing?.postalCode || listing?.postal_code),
    latitude: lead?.latitude ?? listing?.latitude ?? null,
    longitude: lead?.longitude ?? listing?.longitude ?? null,
    googlePlaceId: normalizeText(lead?.googlePlaceId || lead?.google_place_id) || normalizeText(listing?.googlePlaceId || listing?.google_place_id),
    estimatedValue: Number(lead?.estimatedValue || lead?.estimated_value || 0) || Number(listing?.estimatedValue || listing?.estimated_value || listing?.askingPrice || listing?.asking_price || 0) || 0,
    listingId: normalizeText(lead?.listingId || lead?.listing_id || listing?.id || listing?.listingId || listing?.listing_id),
    mandatePacketId,
    sellerOnboardingStatus: normalizeText(lead?.sellerOnboardingStatus || lead?.seller_onboarding_status || listing?.sellerOnboardingStatus || listing?.seller_onboarding_status || onboarding?.status),
    sellerOnboardingToken: normalizeText(lead?.sellerOnboardingToken || lead?.seller_onboarding_token || onboarding?.token || listing?.sellerOnboardingToken || listing?.seller_onboarding_token),
    mandateStatus: normalizeText(lead?.mandateStatus || lead?.mandate_status || listing?.mandateStatus || listing?.mandate_status),
    sellerOnboarding: {
      ...(lead?.sellerOnboarding && typeof lead.sellerOnboarding === 'object' ? lead.sellerOnboarding : {}),
      ...(onboarding || {}),
    },
  }
}

function readRouteLeadLinkedListingSyncValue(lead = {}, key = '') {
  const snakeKey = key.replace(/[A-Z]/g, (letter) => `_${letter.toLowerCase()}`)
  return lead?.[key] ?? lead?.[snakeKey]
}

function addRouteLeadSyncPatchValue(patch, lead = {}, key = '', nextValue, options = {}) {
  const { numeric = false, allowZero = false } = options
  if (numeric) {
    const nextNumber = Number(nextValue)
    if (!Number.isFinite(nextNumber) || (!allowZero && nextNumber === 0)) return
    const currentNumber = Number(readRouteLeadLinkedListingSyncValue(lead, key))
    if (!Number.isFinite(currentNumber) || currentNumber !== nextNumber) {
      patch[key] = nextNumber
    }
    return
  }

  const nextText = normalizeText(nextValue)
  if (!nextText) return
  const currentText = normalizeText(readRouteLeadLinkedListingSyncValue(lead, key))
  if (currentText !== nextText) {
    patch[key] = nextText
  }
}

function buildRouteLeadLinkedListingSyncPatch(lead = {}, listing = null) {
  if (!lead || !listing) return {}
  const patch = {}
  const onboarding = listing?.sellerOnboarding && typeof listing.sellerOnboarding === 'object'
    ? listing.sellerOnboarding
    : listing?.seller_onboarding && typeof listing.seller_onboarding === 'object'
      ? listing.seller_onboarding
      : {}
  const stagePatch = resolveRouteLeadStagePatchFromLinkedListing(lead, listing)
  addRouteLeadSyncPatchValue(patch, lead, 'stage', stagePatch.stage)
  addRouteLeadSyncPatchValue(patch, lead, 'status', stagePatch.status)
  addRouteLeadSyncPatchValue(patch, lead, 'sellerPropertyAddress', resolveListingAddressLabel(listing))
  addRouteLeadSyncPatchValue(patch, lead, 'formattedAddress', listing?.formattedAddress || listing?.formatted_address || resolveListingAddressLabel(listing))
  addRouteLeadSyncPatchValue(patch, lead, 'streetAddress', listing?.streetAddress || listing?.street_address || listing?.addressLine1 || listing?.address_line_1)
  addRouteLeadSyncPatchValue(patch, lead, 'suburb', listing?.suburb)
  addRouteLeadSyncPatchValue(patch, lead, 'city', listing?.city)
  addRouteLeadSyncPatchValue(patch, lead, 'province', listing?.province)
  addRouteLeadSyncPatchValue(patch, lead, 'country', listing?.country || 'South Africa')
  addRouteLeadSyncPatchValue(patch, lead, 'postalCode', listing?.postalCode || listing?.postal_code)
  addRouteLeadSyncPatchValue(patch, lead, 'googlePlaceId', listing?.googlePlaceId || listing?.google_place_id)
  addRouteLeadSyncPatchValue(patch, lead, 'estimatedValue', listing?.estimatedValue || listing?.estimated_value || listing?.askingPrice || listing?.asking_price, { numeric: true })
  addRouteLeadSyncPatchValue(patch, lead, 'listingId', listing?.id || listing?.listingId || listing?.listing_id)
  addRouteLeadSyncPatchValue(patch, lead, 'mandatePacketId', listing?.mandatePacketId || listing?.mandate_packet_id)
  addRouteLeadSyncPatchValue(patch, lead, 'sellerOnboardingToken', onboarding?.token || listing?.sellerOnboardingToken || listing?.seller_onboarding_token)
  addRouteLeadSyncPatchValue(patch, lead, 'sellerOnboardingStatus', listing?.sellerOnboardingStatus || listing?.seller_onboarding_status || onboarding?.status)

  if (listing?.latitude !== null && listing?.latitude !== undefined && listing?.latitude !== '') {
    addRouteLeadSyncPatchValue(patch, lead, 'latitude', listing.latitude, { numeric: true, allowZero: true })
  }
  if (listing?.longitude !== null && listing?.longitude !== undefined && listing?.longitude !== '') {
    addRouteLeadSyncPatchValue(patch, lead, 'longitude', listing.longitude, { numeric: true, allowZero: true })
  }

  return patch
}

function normalizeAppointmentListingOption(listing = {}) {
  const id = normalizeText(listing?.id || listing?.listingId || listing?.listing_id)
  if (!id) return null
  const status = normalizeText(listing?.status || listing?.listingStatus || listing?.lifecycleStatus || listing?.listing_status).toLowerCase()
  if (['archived', 'deleted', 'withdrawn', 'removed'].some((blocked) => status.includes(blocked))) return null
  const bedrooms = Number(listing?.bedrooms || listing?.propertyDetails?.bedrooms || 0) || 0
  const bathrooms = Number(listing?.bathrooms || listing?.propertyDetails?.bathrooms || 0) || 0
  const parking = Number(listing?.garages || listing?.coveredParking || listing?.openParking || listing?.propertyDetails?.garages || listing?.propertyDetails?.coveredParking || listing?.propertyDetails?.openParking || 0) || 0
  const askingPrice = Number(listing?.askingPrice || listing?.asking_price || listing?.price || listing?.propertyDetails?.price || listing?.estimatedValue || 0) || 0
  return {
    id,
    sourceListing: listing,
    label: buildAppointmentListingLabel(listing),
    status: status || 'active',
    title: normalizeText(listing?.listingTitle || listing?.title || listing?.propertyName || listing?.property_name),
    address: normalizeText(listing?.propertyAddress || listing?.address || listing?.addressLine1 || listing?.address_line_1),
    suburb: normalizeText(listing?.suburb),
    askingPrice,
    bedrooms,
    bathrooms,
    parking,
    thumbnailUrl: resolveListingImageUrl(listing),
    assignedAgentId: normalizeText(listing?.assignedAgentId || listing?.assigned_agent_id || listing?.agentId || listing?.agent_id),
    assignedAgentEmail: normalizeText(listing?.assignedAgentEmail || listing?.assigned_agent_email || listing?.agentEmail || listing?.agent_email).toLowerCase(),
    createdBy: normalizeText(listing?.createdBy || listing?.created_by),
    organisationId: normalizeText(listing?.organisationId || listing?.organisation_id),
    updatedAt: listing?.updatedAt || listing?.updated_at || listing?.createdAt || listing?.created_at || null,
  }
}

function buildListingOptionsFromLeads(leads = []) {
  const options = []
  for (const lead of Array.isArray(leads) ? leads : []) {
    const listingId = normalizeText(lead?.listingId || lead?.listing_id)
    if (!listingId) continue
    options.push(normalizeAppointmentListingOption({
      id: listingId,
      listingReference: listingId,
      title: lead?.propertyInterest,
      address: lead?.sellerPropertyAddress,
      suburb: lead?.areaInterest,
      estimatedValue: lead?.estimatedValue || lead?.budget,
      assignedAgentId: lead?.assignedAgentId || lead?.assigned_agent_id,
      assignedAgentEmail: lead?.assignedAgentEmail || lead?.assigned_agent_email,
      createdBy: lead?.createdBy || lead?.created_by,
      organisationId: lead?.organisationId || lead?.organisation_id,
      updatedAt: lead?.updatedAt,
    }))
  }
  return options.filter(Boolean)
}

function readQuickCreateAppointments() {
  if (typeof window === 'undefined') return []
  if (!isUnsafeFallbackAllowed()) return []
  try {
    const parsed = JSON.parse(window.localStorage.getItem(QUICK_CREATE_STORAGE_KEY) || '{}')
    return Array.isArray(parsed?.appointments) ? parsed.appointments : []
  } catch {
    return []
  }
}

function mapLocalStatusToAppointmentStatus(value = '') {
  const normalized = normalizeKey(value).replace(/\s+/g, '_')
  if (normalized === 'scheduled') return 'confirmed'
  if (normalized === 'pending_approval' || normalized === 'viewing_requested') return 'requested'
  if (normalized === 'reschedule_requested') return 'alternative_requested'
  if (normalized === 'no_show') return 'no_show'
  return APPOINTMENT_STATUSES.includes(normalized) ? normalized : 'requested'
}

function buildAgentLookupKeys(agent = {}) {
  return [
    agent?.id,
    agent?.userId,
    agent?.email,
    agent?.fullName,
    agent?.name,
  ].map((value) => normalizeKey(value)).filter(Boolean)
}

function appointmentBelongsToAgent(appointment = {}, agent = {}) {
  const agentKeys = new Set(buildAgentLookupKeys(agent))
  if (!agentKeys.size) return false
  const appointmentKeys = [
    appointment?.assignedAgentId,
    appointment?.assignedAgentEmail,
    appointment?.assignedAgentName,
    appointment?.agentId,
    appointment?.agentEmail,
    appointment?.createdBy,
    appointment?.createdById,
    ...(Array.isArray(appointment?.participants)
      ? appointment.participants.flatMap((participant) => [
          participant?.userId,
          participant?.email,
          participant?.name,
        ])
      : []),
  ].map((value) => normalizeKey(value)).filter(Boolean)
  return appointmentKeys.some((key) => agentKeys.has(key))
}

function mapQuickCreateAppointmentToCalendar(row = {}, { organisationId = '', currentAgent = {} } = {}) {
  const appointmentId = normalizeText(row?.appointmentId || row?.appointment_id || row?.id)
  const dateTime = normalizeText(row?.dateTime || row?.date_time || row?.startTime || row?.startsAt)
  const date = normalizeText(row?.date) || (dateTime ? dateTime.slice(0, 10) : '')
  const startTime = normalizeText(row?.time || row?.start_time) || (dateTime ? dateTime.slice(11, 16) : '')
  const rowOrganisationId = normalizeText(row?.organisationId || row?.organisation_id)
  const resolvedOrganisationId = !rowOrganisationId || rowOrganisationId === 'default'
    ? normalizeText(organisationId)
    : rowOrganisationId
  if (!appointmentId || (!date && !dateTime)) return null
  return {
    appointmentId,
    organisationId: resolvedOrganisationId || null,
    assignedAgentId: normalizeText(row?.assignedAgentId || row?.agentId || currentAgent?.id) || null,
    assignedAgentName: normalizeText(row?.assignedAgent || row?.assignedAgentName || currentAgent?.fullName) || null,
    assignedAgentEmail: normalizeText(row?.assignedAgentEmail || row?.agentEmail || currentAgent?.email).toLowerCase() || null,
    appointmentType: normalizeText(row?.appointmentType || row?.appointment_type) || 'other',
    title: normalizeText(row?.title) || getAppointmentTypeLabel(row?.appointmentType || 'other'),
    date: date || null,
    startTime: startTime || null,
    endTime: normalizeText(row?.endTime || row?.end_time) || null,
    dateTime: dateTime || (date ? `${date}T${startTime || '00:00'}` : null),
    location: normalizeText(row?.location),
    notes: normalizeText(row?.notes),
    status: mapLocalStatusToAppointmentStatus(row?.status),
    relatedEntityType: normalizeText(row?.relatedEntityType || row?.related_entity_type || (row?.relatedRecord ? 'quick_create' : 'none')),
    relatedEntityId: normalizeText(row?.relatedEntityId || row?.related_entity_id || row?.relatedRecord) || null,
    createdBy: normalizeText(row?.createdBy || row?.createdById || currentAgent?.id) || null,
    createdAt: row?.createdAt || row?.created_at || new Date().toISOString(),
    updatedAt: row?.updatedAt || row?.updated_at || row?.createdAt || row?.created_at || new Date().toISOString(),
    source: normalizeText(row?.source) || 'quick_create',
    participants: [],
  }
}

function mapViewingRequestToCalendarAppointment(row = {}, { organisationId = '', currentAgent = {} } = {}) {
  const viewingId = normalizeText(row?.viewing_id || row?.viewingId || row?.id)
  if (!viewingId) return null
  const date = normalizeText(row?.proposed_date || row?.proposedDate)
  const startTime = normalizeText(row?.proposed_time || row?.proposedTime)
  if (!date && !startTime) return null
  const agentParticipant = (Array.isArray(row?.participants) ? row.participants : [])
    .find((participant) => normalizeKey(participant?.role) === 'agent')
  return {
    appointmentId: `viewing:${viewingId}`,
    organisationId: normalizeText(row?.organisationId || row?.organisation_id || organisationId) || null,
    assignedAgentId: normalizeText(row?.agent_id || row?.agentId || currentAgent?.id) || null,
    assignedAgentName: normalizeText(row?.agentName || agentParticipant?.name || currentAgent?.fullName) || null,
    assignedAgentEmail: normalizeText(row?.agentEmail || currentAgent?.email).toLowerCase() || null,
    appointmentType: 'viewing',
    title: `Viewing: ${normalizeText(row?.listing_title || row?.listingTitle) || 'Listing'}`,
    date: date || null,
    startTime: startTime || null,
    endTime: null,
    dateTime: date ? `${date}T${startTime || '00:00'}` : null,
    location: normalizeText(row?.location),
    notes: normalizeText(row?.notes),
    status: mapLocalStatusToAppointmentStatus(row?.status),
    leadId: normalizeText(row?.buyer_lead_id || row?.buyerLeadId) || null,
    listingId: normalizeText(row?.listing_id || row?.listingId) || null,
    relatedEntityType: 'viewing_request',
    relatedEntityId: viewingId,
    createdBy: normalizeText(row?.created_by || row?.createdBy || currentAgent?.id) || null,
    createdAt: row?.created_at || row?.createdAt || new Date().toISOString(),
    updatedAt: row?.updated_at || row?.updatedAt || row?.created_at || row?.createdAt || new Date().toISOString(),
    source: 'viewing_request',
    participants: (Array.isArray(row?.participants) ? row.participants : []).map((participant) => ({
      participantId: normalizeText(participant?.participant_id || participant?.participantId),
      name: normalizeText(participant?.name),
      participantRole: normalizeText(participant?.role),
      rsvpStatus: normalizeText(participant?.response_status),
    })),
  }
}

function mergeCalendarAppointmentRows(remoteRows = [], localRows = []) {
  const byId = new Map()
  for (const row of [...remoteRows, ...localRows]) {
    const id = normalizeText(row?.appointmentId || row?.appointment_id || row?.id)
    if (!id) continue
    if (!byId.has(id)) {
      byId.set(id, row)
      continue
    }
    const existing = byId.get(id)
    const existingIsLocal = normalizeText(existing?.source)
    const rowIsRemote = !normalizeText(row?.source)
    if (existingIsLocal && rowIsRemote) byId.set(id, row)
  }
  return Array.from(byId.values())
}

function buildLocalCalendarAppointments({ organisationId = '', currentAgent = {}, includeAll = false } = {}) {
  const quickAppointments = readQuickCreateAppointments()
    .map((row) => mapQuickCreateAppointmentToCalendar(row, { organisationId, currentAgent }))
    .filter(Boolean)
  const viewingAppointments = readViewingRequests()
    .map((row) => mapViewingRequestToCalendarAppointment(row, { organisationId, currentAgent }))
    .filter(Boolean)
  const rows = [...quickAppointments, ...viewingAppointments]
  if (includeAll) return rows
  return rows.filter((row) => appointmentBelongsToAgent(row, currentAgent))
}

function dedupeListingOptions(options = []) {
  const byId = new Map()
  for (const option of Array.isArray(options) ? options : []) {
    if (!option?.id) continue
    const existing = byId.get(option.id)
    if (!existing) {
      byId.set(option.id, option)
      continue
    }
    const existingTime = new Date(existing.updatedAt || 0).getTime()
    const optionTime = new Date(option.updatedAt || 0).getTime()
    const newerOption = optionTime >= existingTime ? option : existing
    const olderOption = optionTime >= existingTime ? existing : option
    byId.set(option.id, {
      ...olderOption,
      ...newerOption,
      label: normalizeText(newerOption.label) || normalizeText(olderOption.label),
      title: normalizeText(newerOption.title) || normalizeText(olderOption.title),
      address: normalizeText(newerOption.address) || normalizeText(olderOption.address),
      suburb: normalizeText(newerOption.suburb) || normalizeText(olderOption.suburb),
      thumbnailUrl: normalizeText(newerOption.thumbnailUrl) || normalizeText(olderOption.thumbnailUrl),
      askingPrice: Number(newerOption.askingPrice || 0) || Number(olderOption.askingPrice || 0) || 0,
      bedrooms: Number(newerOption.bedrooms || 0) || Number(olderOption.bedrooms || 0) || 0,
      bathrooms: Number(newerOption.bathrooms || 0) || Number(olderOption.bathrooms || 0) || 0,
      parking: Number(newerOption.parking || 0) || Number(olderOption.parking || 0) || 0,
      assignedAgentId: normalizeText(newerOption.assignedAgentId) || normalizeText(olderOption.assignedAgentId),
      assignedAgentEmail: normalizeText(newerOption.assignedAgentEmail) || normalizeText(olderOption.assignedAgentEmail),
      createdBy: normalizeText(newerOption.createdBy) || normalizeText(olderOption.createdBy),
      organisationId: normalizeText(newerOption.organisationId) || normalizeText(olderOption.organisationId),
      updatedAt: newerOption.updatedAt || olderOption.updatedAt || null,
    })
  }
  return Array.from(byId.values()).sort((left, right) => left.label.localeCompare(right.label))
}

function formatDate(value) {
  if (!value) return '—'
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return '—'
  return date.toLocaleString('en-ZA')
}

function formatDateTime(value, fallback = '—') {
  if (!value) return fallback
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return fallback
  return date.toLocaleString('en-ZA', {
    day: '2-digit',
    month: 'short',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  })
}

function formatDateShort(value) {
  if (!value) return '—'
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return '—'
  return date.toLocaleDateString('en-ZA', { day: '2-digit', month: 'short', year: 'numeric' })
}

function formatViewingRequestUserError(error, fallback = "We couldn't send the availability request.") {
  const message = normalizeText(error?.message || error)
  const lower = message.toLowerCase()
  if (!message) return fallback
  if (lower.includes('valid organisation and lead') || lower.includes('invalid_context')) {
    return `${fallback} Reload the buyer workspace so the lead context can sync, then try again.`
  }
  if (lower.includes('edge function') || lower.includes('functionsfetcherror') || lower.includes('failed to send a request')) {
    return `${fallback} Please check the buyer's email address and try again.`
  }
  if (lower.includes('not_authenticated') || lower.includes('sign in')) {
    return `${fallback} Please refresh your session and try again.`
  }
  if (lower.includes('missing required field') || lower.includes('email')) {
    return `${fallback} Please check the recipient email address and try again.`
  }
  return message
}

// Keep historical link handlers dormant while old public links/data remain readable.
const LEGACY_VIEWING_AVAILABILITY_REQUESTS_ENABLED = false
const AGENT_KANBAN_COLORS = ['#32a9e0', '#30bf73', '#f26b4f', '#8b6ce8', '#f0a92e', '#1f6f9f', '#d64c7f']

function getAgentKanbanColor(value = '') {
  const text = normalizeText(value) || 'unassigned'
  let hash = 0
  for (let index = 0; index < text.length; index += 1) {
    hash = (hash * 31 + text.charCodeAt(index)) % AGENT_KANBAN_COLORS.length
  }
  return AGENT_KANBAN_COLORS[Math.abs(hash) % AGENT_KANBAN_COLORS.length]
}

function getInitials(value = '') {
  const parts = normalizeText(value).split(/\s+/).filter(Boolean)
  if (!parts.length) return 'NA'
  return parts.slice(0, 2).map((part) => part[0]).join('').toUpperCase()
}

function formatEntityDisplayReference(prefix, row = {}, index = 0) {
  const explicitReference = normalizeText(
    row?.displayReference ||
    row?.display_reference ||
    row?.referenceNumber ||
    row?.reference_number ||
    row?.reference ||
    row?.listingReference ||
    row?.listing_reference ||
    row?.leadReference ||
    row?.lead_reference ||
    row?.transactionReference ||
    row?.transaction_reference ||
    row?.appointmentReference ||
    row?.appointment_reference,
  )
  if (explicitReference && !isUuidLike(explicitReference)) return explicitReference
  const explicitSequence = Number(row?.sequenceNumber || row?.sequence_number || row?.sequence || 0)
  const sequence = Number.isFinite(explicitSequence) && explicitSequence > 0 ? explicitSequence : index + 1
  return `${prefix}-${String(sequence).padStart(5, '0')}`
}

function safeDisplayText(value, fallback = '') {
  const text = normalizeText(value)
  if (!text || isUuidLike(text)) return fallback
  return text
}

function buildParticipantIdentityKey(participant = {}) {
  return normalizeKey(
    participant?.email ||
    participant?.phone ||
    [participant?.participantRole || participant?.role, participant?.name || participant?.company].filter(Boolean).join(':'),
  )
}

function buildAppointmentParticipant({ name = '', email = '', phone = '', role = 'Client', company = '', source = '' } = {}) {
  const displayName = safeDisplayText(name, '') || safeDisplayText(company, '') || safeDisplayText(email, '') || role
  if (!displayName && !email && !phone) return null
  return {
    name: displayName,
    email: normalizeText(email).toLowerCase(),
    phone: normalizeText(phone),
    participantRole: role,
    company: safeDisplayText(company, ''),
    source,
    isRequired: true,
    rsvpStatus: 'Pending',
  }
}

function getLeadSourceChipTone(value = '') {
  const source = normalizeText(value).toLowerCase()
  if (source.includes('property24') || source.includes('private property')) return 'border-[#d9e8ff] bg-[#eef5ff] text-[#2d63aa]'
  if (source.includes('referral')) return 'border-[#d6ecde] bg-[#eef9f2] text-[#2d7a52]'
  if (source.includes('website') || source.includes('facebook') || source.includes('instagram')) return 'border-[#eadcfb] bg-[#f7f0ff] text-[#7b4ab0]'
  if (source.includes('manual')) return 'border-[#f4e1bf] bg-[#fff6e7] text-[#9a6a1c]'
  return 'border-[#dbe6f1] bg-[#f8fbff] text-[#4f6b86]'
}

const LEAD_SOURCE_LOGOS = {
  property24: {
    src: '/lead-sources/property24.png',
    alt: 'Property24',
    imageClassName: 'h-5 max-w-[88px]',
  },
  privateProperty: {
    src: '/lead-sources/private-property.jpeg',
    alt: 'Private Property',
    imageClassName: 'h-6 max-w-[106px]',
  },
}

function normalizeLeadSourceForBadge(value = '') {
  const source = normalizeText(value).toLowerCase()
  if (!source) return 'unknown'
  if (source.includes('property24')) return 'property24'
  if (source.includes('private') && source.includes('property')) return 'privateProperty'
  if (source.includes('whatsapp')) return 'whatsapp'
  if (source.includes('website')) return 'website'
  if (source.includes('facebook') || source.includes('instagram')) return 'social'
  if (source.includes('google')) return 'google'
  if (source.includes('referral')) return 'referral'
  if (source.includes('show day') || source.includes('showday') || source.includes('open house')) return 'showDay'
  if (source.includes('walk in') || source.includes('walk-in')) return 'walkIn'
  if (source.includes('call') || source.includes('phone')) return 'call'
  if (source.includes('manual')) return 'manual'
  return 'unknown'
}

function getLeadSourceBadgeLabel(source = '', key = normalizeLeadSourceForBadge(source)) {
  const explicitSource = normalizeText(source)
  if (explicitSource && key === 'unknown') return explicitSource
  if (key === 'whatsapp') return 'WhatsApp'
  if (key === 'website') return 'Website'
  if (key === 'social') return explicitSource || 'Social'
  if (key === 'google') return 'Google'
  if (key === 'referral') return explicitSource || 'Referral'
  if (key === 'showDay') return 'Show Day'
  if (key === 'walkIn') return 'Walk-in'
  if (key === 'call') return 'Call'
  if (key === 'manual') return explicitSource || 'Manual'
  return explicitSource || 'Unknown source'
}

function LeadSourceBadge({ source = '', compact = false } = {}) {
  const sourceKey = normalizeLeadSourceForBadge(source)
  const sourceLogo = LEAD_SOURCE_LOGOS[sourceKey]
  if (sourceLogo) {
    return (
      <span
        className={`inline-flex ${compact ? 'h-7 min-w-[92px] max-w-[112px]' : 'h-9 min-w-[112px] max-w-[136px]'} items-center justify-center rounded-full border border-[#dbe6f1] bg-white px-3 shadow-sm`}
        title={sourceLogo.alt}
      >
        <img
          src={sourceLogo.src}
          alt={sourceLogo.alt}
          className={`${sourceLogo.imageClassName} w-auto object-contain`}
          loading="lazy"
        />
      </span>
    )
  }
  return (
    <span className={`inline-flex max-w-full items-center rounded-full border px-2.5 ${compact ? 'py-1 text-[0.7rem]' : 'py-1.5 text-[0.78rem]'} font-semibold ${getLeadSourceChipTone(source || 'Unknown source')}`}>
      <span className="truncate">{getLeadSourceBadgeLabel(source, sourceKey)}</span>
    </span>
  )
}

function AgentPicker({ agents = [], value = '', onChange, label = 'Assigned Agent', className = '' }) {
  const [open, setOpen] = useState(false)
  const pickerRef = useRef(null)
  const selectedAgent = useMemo(() => {
    const selectedKey = normalizeKey(value)
    return agents.find((agent) => normalizeKey(agent.id) === selectedKey || normalizeKey(agent.email) === selectedKey) || agents[0] || null
  }, [agents, value])

  useEffect(() => {
    if (!open || typeof document === 'undefined') return undefined
    const handlePointerDown = (event) => {
      if (pickerRef.current?.contains(event.target)) return
      setOpen(false)
    }
    const handleKeyDown = (event) => {
      if (event.key === 'Escape') setOpen(false)
    }
    document.addEventListener('mousedown', handlePointerDown)
    document.addEventListener('keydown', handleKeyDown)
    return () => {
      document.removeEventListener('mousedown', handlePointerDown)
      document.removeEventListener('keydown', handleKeyDown)
    }
  }, [open])

  const selectedColor = getAgentKanbanColor(selectedAgent?.id || selectedAgent?.email || selectedAgent?.name || label)

  return (
    <div ref={pickerRef} className={`relative ${className}`.trim()}>
      <p className="mb-1.5 px-1 text-[0.68rem] font-semibold uppercase tracking-[0.11em] text-[#7c8da1]">{label}</p>
      <button
        type="button"
        className="flex min-h-[52px] w-full items-center justify-between gap-3 rounded-[14px] border border-[#dbe4ee] bg-white px-3 text-left shadow-[0_8px_18px_rgba(24,45,68,0.04)] transition hover:border-[#bfd0e1] hover:bg-[#fbfdff] focus:border-[#1f6f4a] focus:outline-none focus:ring-4 focus:ring-[#1f6f4a]/10"
        onClick={() => setOpen((previous) => !previous)}
        aria-haspopup="listbox"
        aria-expanded={open}
      >
        <span className="flex min-w-0 items-center gap-3">
          <span
            className="grid h-9 w-9 shrink-0 place-items-center rounded-full text-[0.78rem] font-bold text-white shadow-sm"
            style={{ backgroundImage: `linear-gradient(135deg, ${selectedColor}, #173e63)` }}
          >
            {getInitials(selectedAgent?.name || selectedAgent?.email || 'Agent')}
          </span>
          <span className="min-w-0">
            <span className="block truncate text-sm font-semibold text-[#142132]">{selectedAgent?.name || 'Select agent'}</span>
            <span className="mt-0.5 block truncate text-xs font-medium text-[#6f8399]">{selectedAgent?.email || 'Choose who owns this lead'}</span>
          </span>
        </span>
        <ChevronDown className={`h-4 w-4 shrink-0 text-[#7890a8] transition ${open ? 'rotate-180' : ''}`} />
      </button>
      {open ? (
        <div className="absolute left-0 right-0 z-40 mt-2 max-h-72 overflow-y-auto rounded-[16px] border border-[#d6e3ef] bg-white p-2 shadow-[0_22px_48px_rgba(18,44,68,0.18)]" role="listbox">
          {agents.map((agent) => {
            const agentValue = agent.id || agent.email
            const isSelected =
              normalizeKey(agent.id) === normalizeKey(selectedAgent?.id) ||
              normalizeKey(agent.email) === normalizeKey(selectedAgent?.email)
            const agentColor = getAgentKanbanColor(agent.id || agent.email || agent.name)
            return (
              <button
                key={`${agent.id}:${agent.email}`}
                type="button"
                role="option"
                aria-selected={isSelected}
                className={`flex w-full items-center gap-3 rounded-[12px] px-3 py-2.5 text-left transition ${
                  isSelected ? 'bg-[#edf7f2] text-[#133627]' : 'text-[#20364c] hover:bg-[#f6f9fc]'
                }`}
                onClick={() => {
                  onChange?.(agentValue)
                  setOpen(false)
                }}
              >
                <span
                  className="grid h-9 w-9 shrink-0 place-items-center rounded-full text-[0.76rem] font-bold text-white shadow-sm"
                  style={{ backgroundImage: `linear-gradient(135deg, ${agentColor}, #173e63)` }}
                >
                  {getInitials(agent.name || agent.email || 'Agent')}
                </span>
                <span className="min-w-0 flex-1">
                  <span className="block truncate text-sm font-semibold">{agent.name || 'Agent'}</span>
                  <span className="mt-0.5 block truncate text-xs font-medium text-[#6f8399]">{agent.email || 'No email captured'}</span>
                </span>
                {isSelected ? <CheckCircle2 className="h-4 w-4 shrink-0 text-[#1f7a4d]" /> : null}
              </button>
            )
          })}
        </div>
      ) : null}
    </div>
  )
}

