function stripLeadNoteBlock(notes = '', startMarker = '', endMarker = '') {
  const raw = String(notes || '').trim()
  const startIndex = raw.indexOf(startMarker)
  if (startIndex === -1) return raw
  const endIndex = raw.indexOf(endMarker, startIndex)
  const before = raw.slice(0, startIndex).trim()
  const after = endIndex === -1 ? '' : raw.slice(endIndex + endMarker.length).trim()
  return [before, after].filter(Boolean).join('\n\n')
}

function replaceLeadNoteBlock(notes = '', startMarker = '', endMarker = '', block = '') {
  return [stripLeadNoteBlock(notes, startMarker, endMarker), normalizeText(block)].filter(Boolean).join('\n\n')
}

function stripBuyerQualificationNoteBlock(notes = '') {
  return stripLeadNoteBlock(notes, BUYER_QUALIFICATION_NOTE_START, BUYER_QUALIFICATION_NOTE_END)
}

function stripBuyerViewingPlanNoteBlock(notes = '') {
  return stripLeadNoteBlock(notes, BUYER_VIEWING_PLAN_NOTE_START, BUYER_VIEWING_PLAN_NOTE_END)
}

function stripBuyerStructuredNoteBlocks(notes = '') {
  return stripBuyerViewingPlanNoteBlock(stripBuyerQualificationNoteBlock(notes))
}

function parseBuyerQualificationNoteBlock(notes = '') {
  const raw = String(notes || '')
  const startIndex = raw.indexOf(BUYER_QUALIFICATION_NOTE_START)
  const endIndex = raw.indexOf(BUYER_QUALIFICATION_NOTE_END, startIndex)
  if (startIndex === -1 || endIndex === -1 || endIndex <= startIndex) return {}

  const labelToKey = new Map(BUYER_QUALIFICATION_NOTE_FIELDS.map((field) => [field.label, field.key]))
  const parsed = {}
  let activeKey = ''
  raw
    .slice(startIndex + BUYER_QUALIFICATION_NOTE_START.length, endIndex)
    .trim()
    .split(/\r?\n/)
    .forEach((line) => {
      const labelMatch = line.match(/^([^:]+):\s*(.*)$/)
      const matchedKey = labelMatch ? labelToKey.get(normalizeText(labelMatch[1])) : ''
      if (matchedKey) {
        activeKey = matchedKey
        parsed[matchedKey] = normalizeText(labelMatch[2])
        return
      }
      if (activeKey && normalizeText(line)) {
        parsed[activeKey] = [parsed[activeKey], normalizeText(line)].filter(Boolean).join('\n')
      }
    })
  return parsed
}

function buildBuyerQualificationFormFromLead(lead = {}) {
  const parsed = parseBuyerQualificationNoteBlock(lead?.notes)
  const freeformNotes = stripBuyerStructuredNoteBlocks(lead?.notes)
  return {
    ...BUYER_QUALIFICATION_FORM_DEFAULTS,
    ...parsed,
    budget: normalizeText(parsed.budget) || normalizeText(lead?.budget),
    areaInterest: normalizeText(parsed.areaInterest) || normalizeText(lead?.areaInterest),
    propertyNeed: normalizeText(parsed.propertyNeed) || normalizeText(lead?.propertyInterest),
    additionalNotes: [normalizeText(parsed.additionalNotes), parsed.additionalNotes ? freeformNotes : ''].filter(Boolean).join('\n\n') || freeformNotes,
  }
}

function getBuyerQualificationAnsweredFields(form = {}) {
  return BUYER_QUALIFICATION_NOTE_FIELDS
    .map(({ key, label }) => ({ key, label, value: normalizeText(form[key]) }))
    .filter((field) => field.value)
}

function getBuyerQualificationEvidence(form = {}) {
  const answeredFields = getBuyerQualificationAnsweredFields(form)
  return {
    answeredFields,
    answeredCount: answeredFields.length,
    minimumCount: BUYER_QUALIFICATION_MINIMUM_ANSWER_COUNT,
    complete: answeredFields.length >= BUYER_QUALIFICATION_MINIMUM_ANSWER_COUNT,
  }
}

function buildBuyerQualificationBlock(form = {}) {
  const rows = BUYER_QUALIFICATION_NOTE_FIELDS.map(({ key, label }) => {
    const value = normalizeText(form[key])
    return `${label}: ${value}`
  })
  return [
    BUYER_QUALIFICATION_NOTE_START,
    ...rows,
    BUYER_QUALIFICATION_NOTE_END,
  ].join('\n')
}

function buildBuyerQualificationNotes(form = {}, existingNotes = '') {
  return replaceLeadNoteBlock(
    existingNotes,
    BUYER_QUALIFICATION_NOTE_START,
    BUYER_QUALIFICATION_NOTE_END,
    buildBuyerQualificationBlock(form),
  )
}

function parseBuyerViewingPlanNoteBlock(notes = '') {
  const raw = String(notes || '')
  const startIndex = raw.indexOf(BUYER_VIEWING_PLAN_NOTE_START)
  const endIndex = raw.indexOf(BUYER_VIEWING_PLAN_NOTE_END, startIndex)
  if (startIndex === -1 || endIndex === -1 || endIndex <= startIndex) {
    return {
      status: 'draft',
      selectedPropertyIds: [],
      confirmedPropertyIds: [],
      availabilityWindows: '',
      responseNotes: '',
      sellerRecipientEmails: '',
      sellerCoordinationNotes: '',
      bookedPropertyIds: [],
      bookedAppointmentIds: [],
      updatedAt: '',
      requestedAt: '',
      respondedAt: '',
      sellerRequestedAt: '',
      bookedAt: '',
      recipientEmail: '',
      buyerEmailDeliveryStatus: '',
      buyerEmailDeliveryId: '',
      buyerEmailProviderMessageId: '',
      buyerEmailDeliveryFailure: '',
      sellerEmailDeliveryStatus: '',
      sellerEmailDeliveryIds: '',
      sellerEmailProviderMessageIds: '',
      sellerEmailDeliveryFailure: '',
    }
  }

  const labelToKey = new Map([
    ['Status', 'status'],
    ['Selected property ids', 'selectedPropertyIds'],
    ['Confirmed property ids', 'confirmedPropertyIds'],
    ['Buyer availability windows', 'availabilityWindows'],
    ['Buyer response notes', 'responseNotes'],
    ['Seller recipients', 'sellerRecipientEmails'],
    ['Seller coordination notes', 'sellerCoordinationNotes'],
    ['Booked property ids', 'bookedPropertyIds'],
    ['Booked appointment ids', 'bookedAppointmentIds'],
    ['Buyer availability requested at', 'requestedAt'],
    ['Buyer responded at', 'respondedAt'],
    ['Seller availability requested at', 'sellerRequestedAt'],
    ['Viewing appointments booked at', 'bookedAt'],
    ['Buyer email', 'recipientEmail'],
    ['Buyer email delivery status', 'buyerEmailDeliveryStatus'],
    ['Buyer email delivery id', 'buyerEmailDeliveryId'],
    ['Buyer email provider message id', 'buyerEmailProviderMessageId'],
    ['Buyer email delivery failure', 'buyerEmailDeliveryFailure'],
    ['Seller email delivery status', 'sellerEmailDeliveryStatus'],
    ['Seller email delivery ids', 'sellerEmailDeliveryIds'],
    ['Seller email provider message ids', 'sellerEmailProviderMessageIds'],
    ['Seller email delivery failure', 'sellerEmailDeliveryFailure'],
    ['Updated at', 'updatedAt'],
  ])
  const parsed = {}
  let activeKey = ''
  raw
    .slice(startIndex + BUYER_VIEWING_PLAN_NOTE_START.length, endIndex)
    .trim()
    .split(/\r?\n/)
    .forEach((line) => {
      const labelMatch = line.match(/^([^:]+):\s*(.*)$/)
      const matchedKey = labelMatch ? labelToKey.get(normalizeText(labelMatch[1])) : ''
      if (matchedKey) {
        activeKey = matchedKey
        parsed[matchedKey] = normalizeText(labelMatch[2])
        return
      }
      if (activeKey && normalizeText(line)) {
        parsed[activeKey] = [parsed[activeKey], normalizeText(line)].filter(Boolean).join('\n')
      }
    })

  const status = normalizeText(parsed.status).toLowerCase() || 'draft'
  const knownStatus = BUYER_VIEWING_PLAN_STATUS_OPTIONS.some((option) => option.key === status) ? status : 'draft'
  return {
    status: knownStatus,
    selectedPropertyIds: normalizeText(parsed.selectedPropertyIds)
      .split(',')
      .map(normalizeText)
      .filter(Boolean),
    confirmedPropertyIds: normalizeText(parsed.confirmedPropertyIds)
      .split(',')
      .map(normalizeText)
      .filter(Boolean),
    availabilityWindows: normalizeText(parsed.availabilityWindows),
    responseNotes: normalizeText(parsed.responseNotes),
    sellerRecipientEmails: normalizeText(parsed.sellerRecipientEmails),
    sellerCoordinationNotes: normalizeText(parsed.sellerCoordinationNotes),
    bookedPropertyIds: normalizeText(parsed.bookedPropertyIds)
      .split(',')
      .map(normalizeText)
      .filter(Boolean),
    bookedAppointmentIds: normalizeText(parsed.bookedAppointmentIds)
      .split(',')
      .map(normalizeText)
      .filter(Boolean),
    updatedAt: normalizeText(parsed.updatedAt),
    requestedAt: normalizeText(parsed.requestedAt),
    respondedAt: normalizeText(parsed.respondedAt),
    sellerRequestedAt: normalizeText(parsed.sellerRequestedAt),
    bookedAt: normalizeText(parsed.bookedAt),
    recipientEmail: normalizeText(parsed.recipientEmail),
    buyerEmailDeliveryStatus: normalizeText(parsed.buyerEmailDeliveryStatus),
    buyerEmailDeliveryId: normalizeText(parsed.buyerEmailDeliveryId),
    buyerEmailProviderMessageId: normalizeText(parsed.buyerEmailProviderMessageId),
    buyerEmailDeliveryFailure: normalizeText(parsed.buyerEmailDeliveryFailure),
    sellerEmailDeliveryStatus: normalizeText(parsed.sellerEmailDeliveryStatus),
    sellerEmailDeliveryIds: normalizeText(parsed.sellerEmailDeliveryIds),
    sellerEmailProviderMessageIds: normalizeText(parsed.sellerEmailProviderMessageIds),
    sellerEmailDeliveryFailure: normalizeText(parsed.sellerEmailDeliveryFailure),
  }
}

function buildBuyerViewingPlanBlock({
  status = 'draft',
  selectedPropertyIds = [],
  confirmedPropertyIds = [],
  availabilityWindows = '',
  responseNotes = '',
  sellerRecipientEmails = '',
  sellerCoordinationNotes = '',
  bookedPropertyIds = [],
  bookedAppointmentIds = [],
  updatedAt = '',
  requestedAt = '',
  respondedAt = '',
  sellerRequestedAt = '',
  bookedAt = '',
  recipientEmail = '',
  buyerEmailDeliveryStatus = '',
  buyerEmailDeliveryId = '',
  buyerEmailProviderMessageId = '',
  buyerEmailDeliveryFailure = '',
  sellerEmailDeliveryStatus = '',
  sellerEmailDeliveryIds = '',
  sellerEmailProviderMessageIds = '',
  sellerEmailDeliveryFailure = '',
} = {}) {
  return [
    BUYER_VIEWING_PLAN_NOTE_START,
    `Status: ${normalizeText(status) || 'draft'}`,
    `Selected property ids: ${(Array.isArray(selectedPropertyIds) ? selectedPropertyIds : []).map(normalizeText).filter(Boolean).join(', ')}`,
    `Confirmed property ids: ${(Array.isArray(confirmedPropertyIds) ? confirmedPropertyIds : []).map(normalizeText).filter(Boolean).join(', ')}`,
    `Buyer availability windows: ${normalizeText(availabilityWindows)}`,
    `Buyer response notes: ${normalizeText(responseNotes)}`,
    `Seller recipients: ${normalizeText(sellerRecipientEmails)}`,
    `Seller coordination notes: ${normalizeText(sellerCoordinationNotes)}`,
    `Booked property ids: ${(Array.isArray(bookedPropertyIds) ? bookedPropertyIds : []).map(normalizeText).filter(Boolean).join(', ')}`,
    `Booked appointment ids: ${(Array.isArray(bookedAppointmentIds) ? bookedAppointmentIds : []).map(normalizeText).filter(Boolean).join(', ')}`,
    `Buyer availability requested at: ${normalizeText(requestedAt)}`,
    `Buyer responded at: ${normalizeText(respondedAt)}`,
    `Seller availability requested at: ${normalizeText(sellerRequestedAt)}`,
    `Viewing appointments booked at: ${normalizeText(bookedAt)}`,
    `Buyer email: ${normalizeText(recipientEmail)}`,
    `Buyer email delivery status: ${normalizeText(buyerEmailDeliveryStatus)}`,
    `Buyer email delivery id: ${normalizeText(buyerEmailDeliveryId)}`,
    `Buyer email provider message id: ${normalizeText(buyerEmailProviderMessageId)}`,
    `Buyer email delivery failure: ${normalizeText(buyerEmailDeliveryFailure)}`,
    `Seller email delivery status: ${normalizeText(sellerEmailDeliveryStatus)}`,
    `Seller email delivery ids: ${normalizeText(sellerEmailDeliveryIds)}`,
    `Seller email provider message ids: ${normalizeText(sellerEmailProviderMessageIds)}`,
    `Seller email delivery failure: ${normalizeText(sellerEmailDeliveryFailure)}`,
    `Updated at: ${normalizeText(updatedAt)}`,
    BUYER_VIEWING_PLAN_NOTE_END,
  ].join('\n')
}

function buildBuyerViewingPlanNotes(plan = {}, existingNotes = '') {
  return replaceLeadNoteBlock(
    existingNotes,
    BUYER_VIEWING_PLAN_NOTE_START,
    BUYER_VIEWING_PLAN_NOTE_END,
    buildBuyerViewingPlanBlock(plan),
  )
}

function buildBuyerViewingAvailabilityEmailProperties(properties = [], origin = '') {
  return (Array.isArray(properties) ? properties : []).map((property) => {
    const listingId = normalizeText(property?.id)
    const hasListingRoute = origin && listingId && !listingId.startsWith('recommended-')
    return {
      id: listingId,
      title: normalizeText(property?.title) || 'Recommended property',
      price: normalizeText(property?.price),
      area: normalizeText(property?.area),
      match: normalizeText(property?.match) ? `${property.match}%` : '',
      imageUrl: normalizeText(property?.image || property?.imageUrl || property?.thumbnailUrl),
      link: hasListingRoute ? `${origin}/listings/${encodeURIComponent(listingId)}` : '',
      sellerViewingAvailability: normalizeText(property?.sellerViewingAvailability),
      sellerViewingAvailabilityWindows: normalizeText(property?.sellerViewingAvailabilityWindows),
      sellerViewingAccessInstructions: normalizeText(property?.sellerViewingAccessInstructions),
      sellerViewingNoticePeriod: normalizeText(property?.sellerViewingNoticePeriod),
      sellerViewingNoticeRequired: Boolean(property?.sellerViewingNoticeRequired),
    }
  })
}

function normalizeBuyerViewingPreferenceResponse(link = {}) {
  const response = link?.response && typeof link.response === 'object' && !Array.isArray(link.response) ? link.response : {}
  const selectedPropertyIds = (Array.isArray(link?.selectedPropertyIds) ? link.selectedPropertyIds : [])
    .map(normalizeText)
    .filter(Boolean)
  const responseRows = Array.isArray(response.propertyResponses) ? response.propertyResponses : []
  const confirmedPropertyIds = (Array.isArray(response.confirmedPropertyIds) && response.confirmedPropertyIds.length
    ? response.confirmedPropertyIds
    : responseRows
      .filter((row) => row?.wantsToView === true)
      .map((row) => row?.propertyId || row?.property_id || row?.id))
    .map(normalizeText)
    .filter(Boolean)
  const availabilityWindows = (Array.isArray(response.availabilityWindows) ? response.availabilityWindows : [])
    .map(normalizeText)
    .filter(Boolean)
  const responseNotes = [
    normalizeText(response.responseNotes || response.response_notes),
    normalizeText(response.attendeeNotes || response.attendee_notes)
      ? `Attendees: ${normalizeText(response.attendeeNotes || response.attendee_notes)}`
      : '',
  ].filter(Boolean).join('\n')

  return {
    id: normalizeText(link?.id),
    status: normalizeText(link?.status).toLowerCase(),
    selectedPropertyIds,
    confirmedPropertyIds,
    availabilityWindows,
    availabilityText: availabilityWindows.join('\n'),
    responseNotes,
    submittedAt: normalizeText(link?.submittedAt || response.submittedAt || response.submitted_at),
  }
}

function getBuyerViewingPreferencePropertyTitle(propertyId = '', links = [], fallbackProperties = []) {
  const normalizedId = normalizeText(propertyId)
  if (!normalizedId) return ''
  const fallback = (Array.isArray(fallbackProperties) ? fallbackProperties : [])
    .find((property) => normalizeText(property?.id) === normalizedId)
  if (fallback) return normalizeText(fallback.title)
  for (const link of Array.isArray(links) ? links : []) {
    const property = (Array.isArray(link?.properties) ? link.properties : [])
      .find((row) => normalizeText(row?.id) === normalizedId)
    if (property) return normalizeText(property.title || property.name || property.address)
  }
  return normalizedId
}

function buyerViewingPreferenceMatchesSavedPlan(savedPlan = {}, normalizedResponse = {}) {
  const savedConfirmed = (Array.isArray(savedPlan.confirmedPropertyIds) ? savedPlan.confirmedPropertyIds : []).map(normalizeText).filter(Boolean).sort()
  const responseConfirmed = (Array.isArray(normalizedResponse.confirmedPropertyIds) ? normalizedResponse.confirmedPropertyIds : []).map(normalizeText).filter(Boolean).sort()
  return Boolean(
    normalizeText(savedPlan.respondedAt) &&
      savedConfirmed.join('|') === responseConfirmed.join('|') &&
      normalizeText(savedPlan.availabilityWindows) === normalizeText(normalizedResponse.availabilityText),
  )
}

function normalizeSellerViewingCoordinationResponse(link = {}) {
  const response = link?.response && typeof link.response === 'object' && !Array.isArray(link.response) ? link.response : {}
  const responseRows = Array.isArray(response.propertyResponses)
    ? response.propertyResponses
    : Array.isArray(response.property_responses)
      ? response.property_responses
      : []
  const confirmedPropertyIds = (Array.isArray(response.confirmedPropertyIds) && response.confirmedPropertyIds.length
    ? response.confirmedPropertyIds
    : Array.isArray(response.confirmed_property_ids) && response.confirmed_property_ids.length
      ? response.confirmed_property_ids
      : responseRows
        .filter((row) => row?.canHostViewing === true || row?.can_host_viewing === true || row?.wantsToView === true)
        .map((row) => row?.propertyId || row?.property_id || row?.id))
    .map(normalizeText)
    .filter(Boolean)
  const availabilityWindows = (Array.isArray(response.availabilityWindows) ? response.availabilityWindows : Array.isArray(response.availability_windows) ? response.availability_windows : [])
    .map(normalizeText)
    .filter(Boolean)
  const accessNotes = normalizeText(response.accessNotes || response.access_notes || response.attendeeNotes || response.attendee_notes)
  const responseNotes = [
    normalizeText(response.responseNotes || response.response_notes),
    accessNotes ? `Access notes: ${accessNotes}` : '',
  ].filter(Boolean).join('\n')

  return {
    id: normalizeText(link?.id),
    status: normalizeText(link?.status).toLowerCase(),
    selectedPropertyIds: (Array.isArray(link?.selectedPropertyIds) ? link.selectedPropertyIds : []).map(normalizeText).filter(Boolean),
    confirmedPropertyIds,
    availabilityWindows,
    availabilityText: availabilityWindows.join('\n'),
    accessNotes,
    responseNotes,
    sellerEmail: normalizeText(link?.sellerEmail),
    submittedAt: normalizeText(link?.submittedAt || response.submittedAt || response.submitted_at),
  }
}

function getSellerViewingCoordinationPropertyTitle(propertyId = '', links = [], fallbackProperties = []) {
  const normalizedId = normalizeText(propertyId)
  if (!normalizedId) return ''
  const fallback = (Array.isArray(fallbackProperties) ? fallbackProperties : [])
    .find((property) => normalizeText(property?.id) === normalizedId)
  if (fallback) return normalizeText(fallback.title)
  for (const link of Array.isArray(links) ? links : []) {
    const property = (Array.isArray(link?.properties) ? link.properties : [])
      .find((row) => normalizeText(row?.id) === normalizedId)
    if (property) return normalizeText(property.title || property.name || property.address)
  }
  return normalizedId
}

function sellerViewingCoordinationMatchesSavedPlan(savedPlan = {}, normalizedResponse = {}) {
  const sellerNotes = normalizeText(savedPlan.sellerCoordinationNotes)
  const submittedAt = normalizeText(normalizedResponse.submittedAt)
  return Boolean(submittedAt && sellerNotes.includes(submittedAt))
}

function _buildSellerViewingAvailabilityEmailBody({
  sellerName = 'there',
  buyerName = 'the buyer',
  agentName = 'your agent',
  properties = [],
  availabilityWindows = '',
  coordinationNotes = '',
  origin = '',
} = {}) {
  const propertyLines = properties.map((property, index) => {
    const listingId = normalizeText(property?.id)
    const listingLink = origin && listingId && !listingId.startsWith('recommended-')
      ? `\n   Link: ${origin}/listings/${encodeURIComponent(listingId)}`
      : ''
    return [
      `${index + 1}. ${normalizeText(property?.title) || 'Selected property'}`,
      normalizeText(property?.price) ? `   Price: ${property.price}` : '',
      normalizeText(property?.area) ? `   Area: ${property.area}` : '',
      listingLink,
    ].filter(Boolean).join('\n')
  }).join('\n\n')

  return [
    `Hi ${normalizeText(sellerName) || 'there'},`,
    '',
    `${normalizeText(buyerName) || 'The buyer'} has confirmed interest in viewing the following propert${properties.length === 1 ? 'y' : 'ies'}:`,
    '',
    propertyLines || '1. Your listed property',
    '',
    'The buyer is available during these time windows:',
    normalizeText(availabilityWindows) || 'Availability still needs to be confirmed.',
    '',
    normalizeText(coordinationNotes) ? `Notes: ${normalizeText(coordinationNotes)}` : '',
    '',
    'Please reply with the times that will work for access, and I will confirm the appointment with the buyer.',
    '',
    'Regards,',
    normalizeText(agentName) || 'Your agent',
  ].filter((line, index, lines) => line || lines[index - 1] !== '').join('\n')
}

function parseEmailList(value = '') {
  return normalizeText(value)
    .split(/[,;\n]/)
    .map((email) => normalizeText(email).toLowerCase())
    .filter(Boolean)
}

function parseBuyerQualificationAreas(value = '') {
  return normalizeText(value)
    .split(/[,;\n]/)
    .map(normalizeText)
    .filter(Boolean)
}

function formatBuyerQualificationBudget(value = '') {
  const raw = normalizeText(value)
  const amount = parseCurrencyAmount(raw)
  if (amount > 0) return formatCurrency(amount)
  return raw || 'Not captured'
}

function buildBuyerQualificationQuestionRows(form = {}) {
  return [
    { label: 'Budget', value: formatBuyerQualificationBudget(form.budget) },
    { label: 'Preferred areas', value: normalizeText(form.areaInterest) || 'Not captured' },
    { label: 'Move timeframe', value: normalizeText(form.moveTimeframe) || 'Not captured' },
    { label: 'Cash or bond', value: normalizeText(form.financeType) || 'Not captured' },
    { label: 'Subject to finance', value: normalizeText(form.subjectToFinance) || 'Not captured' },
    { label: 'Deposit available', value: normalizeText(form.depositAvailable) || 'Not captured' },
    { label: 'Pre-approval status', value: normalizeText(form.preApprovalStatus) || 'Not captured' },
    { label: 'Property to sell first', value: normalizeText(form.propertyToSell) || 'Not captured' },
    { label: 'Property need', value: normalizeText(form.propertyNeed) || 'Not captured' },
    { label: 'Call notes', value: normalizeText(form.additionalNotes) || 'Not captured', wide: true },
  ]
}

function buildLeadAddressValue(lead = {}) {
  const formattedAddress = normalizeText(
    lead.formattedAddress ||
      [lead.sellerPropertyAddress || lead.streetAddress, lead.suburb || lead.areaInterest, lead.city, lead.province].filter(Boolean).join(', '),
  )

  if (!formattedAddress) return null

  return {
    formattedAddress,
    streetAddress: normalizeText(lead.streetAddress || lead.sellerPropertyAddress),
    suburb: normalizeText(lead.suburb || lead.areaInterest),
    city: normalizeText(lead.city),
    province: normalizeText(lead.province),
    country: normalizeText(lead.country) || 'South Africa',
    postalCode: normalizeText(lead.postalCode),
    latitude: typeof lead.latitude === 'number' ? lead.latitude : Number(lead.latitude) || undefined,
    longitude: typeof lead.longitude === 'number' ? lead.longitude : Number(lead.longitude) || undefined,
    placeId: normalizeText(lead.googlePlaceId || lead.placeId),
  }
}

function mergeLeadAddress(previous = {}, value = null) {
  if (!value) {
    return {
      ...previous,
      sellerPropertyAddress: '',
      formattedAddress: '',
      streetAddress: '',
      suburb: '',
      city: '',
      province: '',
      country: 'South Africa',
      postalCode: '',
      latitude: null,
      longitude: null,
      googlePlaceId: '',
    }
  }

  const suburb = normalizeText(value.suburb)

  return {
    ...previous,
    sellerPropertyAddress: normalizeText(value.streetAddress || value.formattedAddress),
    formattedAddress: normalizeText(value.formattedAddress),
    streetAddress: normalizeText(value.streetAddress || value.formattedAddress),
    suburb,
    city: normalizeText(value.city),
    province: normalizeText(value.province),
    country: normalizeText(value.country) || 'South Africa',
    postalCode: normalizeText(value.postalCode),
    latitude: value.latitude ?? null,
    longitude: value.longitude ?? null,
    googlePlaceId: normalizeText(value.placeId),
    areaInterest: normalizeText(previous.areaInterest) || suburb,
  }
}

